local config = {
  ui_story_5036_50360101_1_dialog_content = "Ahhh—!",
  ui_story_5036_50360101_2_dialog_content = "Help!",
  ui_story_5036_50360101_3_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5036_50360101_4_dialog_content = "Ugh! *Coughs*",
  ui_story_5036_50360101_5_dialog_content = "How dare you touch me? Don't you know who I am? I own the Star Theater!",
  ui_story_5036_50360101_6_dialog_content = "Do you even realize what you're doing?",
  ui_story_5036_50360101_7_dialog_content = "*Coughs*",
  ui_story_5036_50360101_8_dialog_content = "Unfortunately, I won't be letting you perform in my theater anymore, Miss Goldie.",
  ui_story_5036_50360101_9_dialog_content = "... What a shame.",
  ui_story_5036_50360101_10_dialog_content = "Morning!",
  ui_story_5036_50360101_11_dialog_content = "*Yawns* Good morning.",
  ui_story_5036_50360101_12_dialog_content = "You're here pretty early. Has something urgent come up?",
  ui_story_5036_50360101_13_dialog_content = "Oops, is this a bad time?",
  ui_story_5036_50360101_14_dialog_content = "Sorry, I got so excited about the interview that I didn't even realize the time!",
  ui_story_5036_50360101_15_dialog_content = "Uh, wait a second... Don't you remember me?",
  ui_story_5036_50360101_16_option_content = "We remember you",
  ui_story_5036_50360101_17_dialog_content = "You do look somewhat familiar...?",
  ui_story_5036_50360101_18_dialog_content = "Oh wait, weren't you an extra in \"Tattletale\"?",
  ui_story_5036_50360101_19_option_content = "Don't remember you",
  ui_story_5036_50360101_20_dialog_content = "Uh...",
  ui_story_5036_50360101_21_dialog_content = "Should we know you?",
  ui_story_5036_50360101_22_dialog_content = "Er, ahem...",
  ui_story_5036_50360101_23_dialog_content = "I'm <color=#FFB400>Brandy</color>, intern reporter for The Daily Scoop!",
  ui_story_5036_50360101_24_dialog_content = "We met briefly in front of the Andersen Haunted House before.",
  ui_story_5036_50360101_25_dialog_content = "I didn't get to interview you two then, and my editor slammed the article I wrote...",
  ui_story_5036_50360101_26_dialog_content = "But that's okay!",
  ui_story_5036_50360101_27_dialog_content = "I'm very grateful to you for today's exclusive interview!",
  ui_story_5036_50360101_28_dialog_content = "Huh? When did I agree to that?",
  ui_story_5036_50360101_29_dialog_content = "Well, we don't have a moment to lose! Why don't we get the interview started then?",
  ui_story_5036_50360101_30_dialog_content = "What are your thoughts on the <color=#FFB400>Wandering Colossus</color>?",
  ui_story_5036_50360101_31_dialog_content = "Wandering Colossus?",
  ui_story_5036_50360101_32_dialog_content = "Is that what the young people in Umbraton call Soroz?",
  ui_story_5036_50360101_33_dialog_content = "Huh?",
  ui_story_5036_50360101_34_dialog_content = "You don't know about the Wandering Colossus?",
  ui_story_5036_50360101_35_dialog_content = "Almost everybody knows about it, from Northland to the Rediesel Desert, from Lumopolis to Umbraton.",
  ui_story_5036_50360101_36_dialog_content = "But you haven't heard of it, despite being a Caelestite?",
  ui_story_5036_50360101_37_dialog_content = "I guess that counts as news too!",
  ui_story_5036_50360101_38_dialog_content = "Hmmm, it has headline news potential. I should jot this down!",
  ui_story_5036_50360101_39_dialog_content = "Ahem. I've... been too busy with work and things lately to keep up with current affairs.",
  ui_story_5036_50360101_40_dialog_content = "Don't tell me there are tabloids spreading rumors about me again?",
  ui_story_5036_50360101_41_dialog_content = "Not at all!",
  ui_story_5036_50360101_42_dialog_content = "Look, here's a bit from last night.",
  ui_story_5036_50360101_43_dialog_content = "Extra:",
  ui_story_5036_50360101_44_dialog_content = "Trail of the Wandering Colossus Forecasted",
  ui_story_5036_50360101_45_dialog_content = "Heading for Umbraton Along the Gold River!",
  ui_story_5036_50360101_46_dialog_content = "I'll read it for you guys!",
  ui_story_5036_50360101_47_dialog_content = "\"Latest Update: The Wandering Colossus has left Northland.\"",
  ui_story_5036_50360101_48_dialog_content = "\"Scientists are currently tracking it, and according to their calculations...\"",
  ui_story_5036_50360101_49_dialog_content = "\"The Colossus will continue southward toward Umbraton along the Gold River.\"",
  ui_story_5036_50360101_50_dialog_content = "\"The Colossus first appeared abruptly in the skies right above Northland and was thought to come from the Dark Zone.\"",
  ui_story_5036_50360101_51_dialog_content = "\"After an anonymous scientist confirmed this theory, the news rocked the entire continent.\"",
  ui_story_5036_50360101_52_dialog_content = "\"Some claim the Colossus has no Navigator or passengers, nor does it carry any destructive weapons.\"",
  ui_story_5036_50360101_53_dialog_content = "\"But the exterior, especially the bottom, is equipped with giant screens and stereo devices that appear to be from ancient times.\"",
  ui_story_5036_50360101_54_dialog_content = "\"Presently, Illumina and Lumopolis are looking into ways to intercept the Wandering Colossus...\"",
  ui_story_5036_50360101_55_dialog_content = "\"... to decide how they will proceed with the situation.\"",
  ui_story_5036_50360101_56_dialog_content = "A Wandering... Colossus?",
  ui_story_5036_50360101_57_dialog_content = "I have so many questions, I don't even know where to start.",
  ui_story_5036_50360101_58_dialog_content = "A Colossus outfitted with screens and stereo systems?",
  ui_story_5036_50360101_59_dialog_content = "I think I've read about it before somewhere!",
  ui_story_5036_50360101_60_dialog_content = "Really? What else can you tell me?",
  ui_story_5036_50360101_61_dialog_content = "Sorry, I can't remember much about it.",
  ui_story_5036_50360101_62_dialog_content = "But don't look so disappointed. I'll go ask Officer Gronru right now.",
  ui_story_5036_50360101_63_dialog_content = "I'm sure she can tell us more with her breadth of knowledge on Colossi!",
  ui_story_5036_50360101_64_dialog_content = "That won't be necessary.",
  ui_story_5036_50360101_65_dialog_content = "Carleen...? You're back!",
  ui_story_5036_50360101_66_dialog_content = "I thought you were going to stay in Lumopolis forever.",
  ui_story_5036_50360101_67_dialog_content = "I read about the Wanderer Colossus in the news a few days ago and found the whole situation rather strange, so I buried myself in library research.",
  ui_story_5036_50360101_68_dialog_content = "You must've found something!",
  ui_story_5036_50360101_69_dialog_content = "Or you wouldn't have come here in such a hurry...",
  ui_story_5036_50360101_70_dialog_content = "Yes, I found something from more than a century ago.",
  ui_story_5036_50360101_71_dialog_content = "More than a century?",
  ui_story_5036_50360101_72_dialog_content = "That's right. Caelestites were isolationists and didn't have much contact with Aurorians back then.",
  ui_story_5036_50360101_73_dialog_content = "But one day, they suddenly sought help from Lumopolis and Illumina.",
  ui_story_5036_50360101_74_dialog_content = "Their plea for help implied that they seemed to have lost contact with a Colossus called <color=#FFB400>Eulogoz</color>.",
  ui_story_5036_50360101_75_dialog_content = "Eulogoz has a very prominent feature—",
  ui_story_5036_50360101_76_dialog_content = "<color=#FFB400>It has giant external screens</color>.",
  ui_story_5036_50360101_77_dialog_content = "Giant screens? That's how the paper described the Wandering Colossus.",
  ui_story_5036_50360101_78_dialog_content = "What's notable is that the Caelestites failed to find Eulogoz a hundred years ago.",
  ui_story_5036_50360101_79_dialog_content = "You mean... the Wandering Colossus is the long-lost Eulogoz?",
  ui_story_5036_50360101_80_dialog_content = "That's what I'm guessing.",
  ui_story_5036_50360101_81_dialog_content = "How is it possible for it to disappear for over a century and remain undiscovered until now?!",
  ui_story_5036_50360101_82_dialog_content = "I thought you would know something, being a Caelestite yourself.",
  ui_story_5036_50360101_83_dialog_content = "Maybe it can make itself invisible?",
  ui_story_5036_50360101_84_dialog_content = "I've never heard of a Caelestite capable of invisibility.",
  ui_story_5036_50360101_85_dialog_content = "Its name and origins are hardly of importance right now.",
  ui_story_5036_50360101_86_dialog_content = "The imporant thing is, a Colossus appeared out of the blue in the sky!",
  ui_story_5036_50360101_87_dialog_content = "We all know Colossi are exclusive to Caelestites.",
  ui_story_5036_50360101_88_dialog_content = "And we have a genuine, authentic Caelestite right here.",
  ui_story_5036_50360101_89_dialog_content = "Yet it's Lumopolis and Illumina that are deciding what to do with the Colossus.",
  ui_story_5036_50360101_90_dialog_content = "How do you feel about that, PlayerName?",
  ui_story_5036_50360101_91_dialog_content = "I trust Illumina researchers will notify PlayerName after a thorough investigation.",
  ui_story_5036_50360101_92_dialog_content = "The knights true to the God of Light would never take something that doesn't belong to us.",
  ui_story_5036_50360101_93_dialog_content = "*Ahem* I wanted to ask PlayerName's opinion on the situation since he's a Caelestite.",
  ui_story_5036_50360101_94_dialog_content = "...",
  ui_story_5036_50360101_95_dialog_content = "Sorry.",
  ui_story_5036_50360101_96_dialog_content = "Huh?",
  ui_story_5036_50360101_97_dialog_content = "I can't answer without seeing the Colossus in person first.",
  ui_story_5036_50360101_98_dialog_content = "You're planning to...",
  ui_story_5036_50360101_99_dialog_content = "Regardless, I have the right to investigate something that belongs to the Caelestites.",
  ui_story_5036_50360101_100_dialog_content = "Will you two come with me?",
  ui_story_5036_50360101_101_dialog_content = "I was planning to do exactly that.",
  ui_story_5036_50360101_102_dialog_content = "Do you even have to ask?",
  ui_story_5036_50360101_103_dialog_content = "All right!",
  ui_story_5036_50360101_104_dialog_content = "Soroz...",
  ui_story_5036_50360101_105_option_content = "Full speed ahead!",
  ui_story_5036_50360101_106_dialog_content = "Oh my, so this is how cool PlayerName the Caelestite looks when commanding a Colossus!",
  ui_story_5036_50360101_107_dialog_content = "I need to record this!",
  ui_story_5036_50360101_108_dialog_content = "<color=#e8d9bb>Warning! Warning! Command invalid.</color>",
  ui_story_5036_50360101_109_dialog_content = "Huh?",
  ui_story_5036_50360101_110_dialog_content = "<color=#e8d9bb>Please enter target coordinates.</color>",
  ui_story_5036_50360101_111_dialog_content = "Oh, that...",
  ui_story_5036_50360101_112_dialog_content = "Say, has anyone got the coordinates for the Wandering Colossus?",
  ui_story_5036_50360101_113_dialog_content = "...",
  ui_story_5036_50360101_114_dialog_content = "I was wondering when you were going to ask.",
  ui_story_5036_50360101_115_dialog_content = "Sorry, but I can't rent the theater to you.",
  ui_story_5036_50360101_116_dialog_content = "Please, revenue isn't a problem! My concerts are well-attended!",
  ui_story_5036_50360101_117_dialog_content = "Won't you reconsider?",
  ui_story_5036_50360101_118_dialog_content = "I suggest you try your luck elsewhere.",
  ui_story_5036_50360101_119_dialog_content = "But all the other theaters in Umbraton already turned me away...",
  ui_story_5036_50360101_120_dialog_content = "Extra, extra! Wandering Colossus forecasted to head for Umbraton along the Gold River!",
  ui_story_5036_50360101_121_dialog_content = "Wandering Colossus?",
  ui_story_5036_50360101_122_dialog_content = "Can I have a copy, please?",
  ui_story_5036_50360101_123_dialog_content = "<color=#e8d9bb>Whoosh!</color>",
  ui_story_5036_50360101_124_dialog_content = "Whoa!",
  ui_story_5036_50360101_125_dialog_content = "We're really taking off!",
  ui_story_5036_50360101_126_dialog_content = "That editor who harasses me day in day out would never even have imagined this in a million years!",
  ui_story_5036_50360101_127_dialog_content = "That of all the journalists scrambling for a chance to follow one of the Caelestite's stories in Umbraton, I'm the only one to actually fly inside the Colossus!",
  ui_story_5036_50360101_128_dialog_content = "I'll show him who's the most awesome reporter in town!",
  ui_story_5036_50360101_129_dialog_content = "Uh, Brandy...?",
  ui_story_5036_50360101_130_dialog_content = "Oh no, I shouldn't have exposed myself in front of my interviewees!",
  ui_story_5036_50360101_131_dialog_content = "Ahem. Please rest assured, everyone. I'm a professional and will proceed with my work with utmost objectivity.",
  ui_story_5036_50360101_132_dialog_content = "That's not what I meant.",
  ui_story_5036_50360101_133_dialog_content = "Did you want to go back to Umbraton? I can drop you off on the way.",
  ui_story_5036_50360101_134_dialog_content = "Oh, not at all! I'm not even close to finishing my interview with you yet.",
  ui_story_5036_50360101_135_dialog_content = "I'd also like your permission to come along on your journey to the Wandering Colossus.",
  ui_story_5036_50360101_136_dialog_content = "I promise I'll write the most epic, most glorious article about you!",
  ui_story_5036_50360101_137_dialog_content = "Those in Lumopolis and Illumina won't even think about touching Caelestite property after they read it!",
  ui_story_5036_50360101_138_dialog_content = "Er, that's... that's a little dramatic, ha...",
  ui_story_5036_50360101_139_dialog_content = "Hey, what's that?",
  ui_story_5036_50360101_140_dialog_content = "A poster just slipped out of your bag, Brandy.",
  ui_story_5036_50360101_141_dialog_content = "Ahahaha, right! Thanks! Putting it away immediately!",
  ui_story_5036_50360101_142_dialog_content = "Wait, don't we know that person on the poster?",
  ui_story_5036_50360101_143_dialog_content = "Yeah, isn't that Goldie?",
  ui_story_5036_50360101_144_dialog_content = "After \"Into the Haunted House\" premiered, we met her once at the Andersen Haunted House.",
  ui_story_5036_50360101_145_dialog_content = "The film got great reviews, but she decided to quit acting.",
  ui_story_5036_50360101_146_dialog_content = "I wonder what she's been doing lately?",
  ui_story_5036_50360101_147_dialog_content = "I feel like she's gotten popular in Umbraton as of late though. I see posters of her everywhere I go.",
  ui_story_5036_50360101_148_dialog_content = "This one I have is different from the ones on the street.",
  ui_story_5036_50360101_149_dialog_content = "This one is a limited-edition collectible!",
  ui_story_5036_50360101_150_dialog_content = "So you're a fan of hers?",
  ui_story_5036_50360101_151_dialog_content = "I-I wouldn't really call myself a Goldilock...",
  ui_story_5036_50360101_152_dialog_content = "A Goldilock?",
  ui_story_5036_50360101_153_dialog_content = "That's what Goldie's fans are called. I'm really not one of them!",
  ui_story_5036_50360101_154_dialog_content = "I just interviewed Goldie after \"Into the Haunted House\" premiered.",
  ui_story_5036_50360101_155_dialog_content = "I found her very optimistic and kind, like a warm breeze dispersing all my troubles.",
  ui_story_5036_50360101_156_dialog_content = "Otherwise, I probably wouldn't have lasted as long as I did as an intern at The Daily Scoop.",
  ui_story_5036_50360101_157_dialog_content = "So after that I just followed her work from time to time, that's all.",
  ui_story_5036_50360101_158_dialog_content = "Doesn't that basically make you a fan?",
  ui_story_5036_50360101_159_dialog_content = "D-Does it? But I heard through the grapevine that Goldie violent tendencies.",
  ui_story_5036_50360101_160_dialog_content = "It's true that many public figures have a side nobody knows about.",
  ui_story_5036_50360101_161_dialog_content = "But I don't want to idolize somebody who's violent.",
  ui_story_5036_50360101_162_dialog_content = "Goldie, violent? No way!",
  ui_story_5036_50360101_163_dialog_content = "There's been a lot of absurd rumors going around lately, and that's probably one of them.",
  ui_story_5036_50360101_164_dialog_content = "Umbraton newspapers are probably depicting PlayerName as some mystical three-headed monster by now.",
  ui_story_5036_50360101_165_dialog_content = "True! I hate it.",
  ui_story_5036_50360101_166_dialog_content = "You'd better not drag me through the mud like them, Brandy!",
  ui_story_5036_50360101_167_dialog_content = "Relax!",
  ui_story_5036_50360101_168_dialog_content = "I only report the truth as I see it with my own eyes.",
  ui_story_5036_50360101_169_dialog_content = "I wish there were more journalists like you in Umbraton.",
  ui_story_5036_50360101_170_dialog_content = "M-Me? Oh, gosh, hehehe...",
  ui_story_5036_50360101_171_dialog_content = "<color=#e8d9bb>Warning: Unidentified flying object detected ahead.</color>",
  ui_story_5036_50360101_172_dialog_content = "<color=#e8d9bb>Please give command for evasive action!</color>",
  ui_story_5036_50360101_173_dialog_content = "Unidentified flying object?",
  ui_story_5036_50360101_174_dialog_content = "Its build is very different from Soroz...",
  ui_story_5036_50360101_175_dialog_content = "but the design and shine of its hull are obviously that of a Colossus!",
  ui_story_5036_50360101_176_dialog_content = "The screen...",
  ui_story_5036_50360101_177_dialog_content = "I see it! Is that huge square thing the screen?",
  ui_story_5036_50360101_178_dialog_content = "That's definitely not from our time!",
  ui_story_5036_50360101_179_dialog_content = "That must be it! That has to be the Wandering Colossus!",
  ui_story_5036_50360101_180_dialog_content = "But why isn't Soroz able to identify it by name?",
  ui_story_5036_50360101_181_dialog_content = "And why can't I sense its Navigator?",
  ui_story_5036_50360101_182_dialog_content = "Are you really the Eulogoz that vanished a century ago?",
  ui_story_5036_50360101_183_dialog_content = "♪ La... La la la... ♪",
  ui_story_5036_50360101_184_dialog_content = "(Who's singing?)",
  ui_story_5036_50360101_185_dialog_content = "Do you guys hear that?",
  ui_story_5036_50360101_186_dialog_content = "Hear what?",
  ui_story_5036_50360101_187_dialog_content = "♪ Oo-oo-oo-oo... ♪",
  ui_story_5036_50360101_188_dialog_content = "Singing... Somebody's singing!",
  ui_story_5036_50360101_189_dialog_content = "What? I don't hear anything.",
  ui_story_5036_50360101_190_dialog_content = "♪ La la la la... ♪",
  ui_story_5036_50360101_191_dialog_content = "(Are you Eulogoz's Navigator?)",
  ui_story_5036_50360101_192_dialog_content = "♪ Oo-oo-oo-oo... ♪",
  ui_story_5036_50360101_193_dialog_content = "(Why did you abandon your Colossus?)",
  ui_story_5036_50360101_194_dialog_content = "♪ La... La la... ♪",
  ui_story_5036_50360101_195_dialog_content = "(Why...?)",
  ui_story_5036_50360101_196_dialog_content = "<color=#e8d9bb>Warning: Unidentified flying object detected ahead.</color>",
  ui_story_5036_50360101_197_dialog_content = "<color=#e8d9bb>To avoid collision, the Colossus will auto-change flight path in three seconds.</color>",
  ui_story_5036_50360101_198_dialog_content = "<color=#e8d9bb>Three...</color>",
  ui_story_5036_50360101_199_dialog_content = "<color=#e8d9bb>Two...</color>",
  ui_story_5036_50360101_200_dialog_content = "Stop flight path diversion.",
  ui_story_5036_50360101_201_dialog_content = "Match the speed and direction of the unidentified flying object.",
  ui_story_5036_50360101_202_dialog_content = "Adjust flight as needed.",
  ui_story_5036_50360201_1_dialog_content = "<color=#e8d9bb>Attention, approaching unidentified flying object.</color>",
  ui_story_5036_50360201_2_dialog_content = "The Colossus is shaking a lot! Did we collide with the Wandering Colossus?",
  ui_story_5036_50360201_3_dialog_content = "Don't worry. It's just Soroz reducing speed.",
  ui_story_5036_50360201_4_dialog_content = "That's too bad. I thought I could capture a shot of two Colossi crashing into each other.",
  ui_story_5036_50360201_5_dialog_content = "Such an awesome photo would make the front page of every newspaper!",
  ui_story_5036_50360201_6_dialog_content = "If that happened, I doubt you'd have time to snap a photo.",
  ui_story_5036_50360201_7_dialog_content = "I'm just saying!",
  ui_story_5036_50360201_8_dialog_content = "That said, your camera does look pretty unique.",
  ui_story_5036_50360201_9_dialog_content = "You've got a good eye, Vice!",
  ui_story_5036_50360201_10_dialog_content = "Not everyone has the privilege of owning an advanced device like a camera.",
  ui_story_5036_50360201_11_dialog_content = "Not to mention I always update its parts so I can get better shots.",
  ui_story_5036_50360201_12_dialog_content = "I was hired as an intern thanks to this camera.",
  ui_story_5036_50360201_13_dialog_content = "Wow! So can your camera make people look prettier in pictures?",
  ui_story_5036_50360201_14_dialog_content = "That I can't promise, but I can guarantee it will capture the most authentic, true-to-life image!",
  ui_story_5036_50360201_15_dialog_content = "<color=#e8d9bb>Adjustment made to keep consistent speed and direction with the unidentified object.</color>",
  ui_story_5036_50360201_16_dialog_content = "Let's go.",
  ui_story_5036_50360201_17_dialog_content = "Wait, we're still a long ways off from the Wandering Colossus.",
  ui_story_5036_50360201_18_dialog_content = "How are we supposed to get near it?",
  ui_story_5036_50360201_19_dialog_content = "By flying, of course.",
  ui_story_5036_50360201_20_dialog_content = "<anim type=Shake>Ahhhh!!!</anim>",
  ui_story_5036_50360201_21_dialog_content = "W-We really flew over!",
  ui_story_5036_50360201_22_dialog_content = "That was my first time on an airship, it was brilliant!",
  ui_story_5036_50360201_23_dialog_content = "Not to mention, I can't believe the Wandering Colossus is actually beneath my feet right now!",
  ui_story_5036_50360201_24_dialog_content = "Oh gosh, so many reporters would die for an opportunity like this!",
  ui_story_5036_50360201_25_dialog_content = "But oops, no matter how excited I am, a professional reporter should never neglect the subject of their writing.",
  ui_story_5036_50360201_26_dialog_content = "Let me ask how PlayerName feels at this moment!",
  ui_story_5036_50360201_27_dialog_content = "Excuse me, PlayerName...?",
  ui_story_5036_50360201_28_dialog_content = "...",
  ui_story_5036_50360201_29_dialog_content = "Hey, you look pale...Is this some form of wordless protest against the actions of Illumina and Lumopolis?",
  ui_story_5036_50360201_30_dialog_content = "It's Darkflow! So much Darkflow all of a sudden!",
  ui_story_5036_50360201_31_dialog_content = "What? Are we in the wrong place?",
  ui_story_5036_50360201_32_dialog_content = "Impossible, Chief Judge Irridon gave me the coordinates herself. They can't be wrong.",
  ui_story_5036_50360201_33_dialog_content = "Guys, there's no time for that right now, we've got a bigger problem!",
  ui_story_5036_50360201_34_dialog_content = "<size=45>Grah!!!</size>",
  ui_story_5036_50360202_1_dialog_content = "♪ La... La la la... ♪",
  ui_story_5036_50360202_2_dialog_content = "(It's the singing again...)",
  ui_story_5036_50360202_3_dialog_content = "(Why does it sound strangely familiar when I've never heard it before?)",
  ui_story_5036_50360202_4_dialog_content = "(It's like a rhythm that's always been pulsing through my veins, only bubbling up to the surface of my memory in this moment.)",
  ui_story_5036_50360202_5_dialog_content = "♪ Oo-oo-oo-oo... ♪",
  ui_story_5036_50360202_6_dialog_content = "♪ La la la la... ♪",
  ui_story_5036_50360202_7_dialog_content = "Y-You're...",
  ui_story_5036_50360202_8_dialog_content = "How dare a mere Caelestite forget the name of Judge Matthieu!",
  ui_story_5036_50360202_9_dialog_content = "Not even a soul in Lumopolis dares overlook me thus! I refuse to suffer such indignity!",
  ui_story_5036_50360202_10_dialog_content = "Don't you agree, Loewe? ... What are you doing, Loewe?",
  ui_story_5036_50360202_11_dialog_content = "Are you okay, Your Highness?",
  ui_story_5036_50360202_12_dialog_content = "I'm fine. It was just a few Eclipsites.",
  ui_story_5036_50360202_13_dialog_content = "But thanks to your timely arrival, we got rid of them quickly enough.",
  ui_story_5036_50360202_14_dialog_content = "Hmph, I never would've guessed...",
  ui_story_5036_50360202_15_dialog_content = "that you'd one day learn to take credit and steal the thunder for yourself, Loewe!",
  ui_story_5036_50360202_16_dialog_content = "The investigation is not over yet.",
  ui_story_5036_50360202_17_dialog_content = "But someone wanted to go home.",
  ui_story_5036_50360202_18_dialog_content = "Again with that!",
  ui_story_5036_50360202_19_dialog_content = "I have no idea where Loewe learned to be a suck-up and backstab his colleagues.",
  ui_story_5036_50360202_20_dialog_content = "Do not let his nonsense sway you, Lady Carleen.",
  ui_story_5036_50360202_21_dialog_content = "Over the past several days, I've led the Lumopolis investigation unit's work on the Wandering Colossus in the most proper, orderly manner.",
  ui_story_5036_50360202_22_dialog_content = "You'll be able to read my detailed report from atop your plushy velvet cushion in Lumopolis in due time.",
  ui_story_5036_50360202_23_dialog_content = "Oh really? So you haven't been loitering around Siobhan in an attempt to plagiarize her work, huh?",
  ui_story_5036_50360202_24_dialog_content = "Rest assured, Officer Gronru.",
  ui_story_5036_50360202_25_dialog_content = "I will protect our files with everything I've got.",
  ui_story_5036_50360202_26_dialog_content = "Looks like you've been caught red-handed.",
  ui_story_5036_50360202_27_dialog_content = "Oh, shut up! I was just confirming our own findings!",
  ui_story_5036_50360202_28_dialog_content = "Officer Gronru, Miss Siobhan!",
  ui_story_5036_50360202_29_dialog_content = "So you're here on-assignment on the Wandering Colossus?",
  ui_story_5036_50360202_30_dialog_content = "Let's take a look at you... Vice, darling, have you lost weight again?",
  ui_story_5036_50360202_31_dialog_content = "Uh, have I?",
  ui_story_5036_50360202_32_dialog_content = "If you keep treating Vice like this, PlayerName, I'm going to steal her away from you!",
  ui_story_5036_50360202_33_dialog_content = "I-I haven't done anything...",
  ui_story_5036_50360202_34_dialog_content = "Is that so? Heehee...",
  ui_story_5036_50360202_35_dialog_content = "Anyway, you got here much later than I expected.",
  ui_story_5036_50360202_36_dialog_content = "I almost thought PlayerName had given up the notion of inspecting this Colossus.",
  ui_story_5036_50360202_37_dialog_content = "But as far as I know...",
  ui_story_5036_50360202_38_dialog_content = "Neither Lumopolis nor the Illumina Federation ever officially notified PlayerName about the Wandering Colossus.",
  ui_story_5036_50360202_39_dialog_content = "Hmm? I don't believe we've met.",
  ui_story_5036_50360202_40_dialog_content = "Hello, I'm Brandy, an intern reporter for The Daily Scoop.",
  ui_story_5036_50360202_41_dialog_content = "I'm doing a feature on PlayerName. Please answer my question.",
  ui_story_5036_50360202_42_dialog_content = "Why didn't any of you inform PlayerName about the Wandering Colossus?",
  ui_story_5036_50360202_43_dialog_content = "Is it true that Illumina and Lumopolis planned to split the Colossus behind the Caelestite's back?",
  ui_story_5036_50360202_44_dialog_content = "Young reporter, is Illumina obligated to inform PlayerName?",
  ui_story_5036_50360202_45_dialog_content = "Officer Gronru!",
  ui_story_5036_50360202_46_dialog_content = "Oh! Did I spook you all?",
  ui_story_5036_50360202_47_dialog_content = "Ehehe fine, I'll answer nicely.",
  ui_story_5036_50360202_48_dialog_content = "We sent a large team to investigate as soon as we received news about the Wandering Colossus.",
  ui_story_5036_50360202_49_dialog_content = "We've got a lot of support on standby both on the ground and in the air nearby.",
  ui_story_5036_50360202_50_dialog_content = "Contrary to your assumptions, our primary objective is not to take the Colossus for ourselves.",
  ui_story_5036_50360202_51_dialog_content = "We're here to evaluate what level of threat a Colossus drifting out from the Dark Zone could pose to Illumina.",
  ui_story_5036_50360202_52_dialog_content = "After all, it came from the Dark Zone, and no one knows what types of <color=#FFB400>passengers</color> are on board.",
  ui_story_5036_50360202_53_dialog_content = "Lumopolis shares this view.",
  ui_story_5036_50360202_54_dialog_content = "I just don't get why I always got chosen for laborious, dirty tasks like this.",
  ui_story_5036_50360202_55_dialog_content = "News of the Wandering Colossus was never censored.",
  ui_story_5036_50360202_56_dialog_content = "I'm curious myself as to why PlayerName wasn't aware of it.",
  ui_story_5036_50360202_57_dialog_content = "W-Well, there's a reason...",
  ui_story_5036_50360202_58_dialog_content = "Oh?",
  ui_story_5036_50360202_59_dialog_content = "Never mind that. I don't think we got here too late.",
  ui_story_5036_50360202_60_dialog_content = "But I'm puzzled to see Eclipsites roaming through the halls of the Wandering Colossus.",
  ui_story_5036_50360202_61_dialog_content = "I am very sorry you had to experience such a scare upon arrival, Lady Carleen.",
  ui_story_5036_50360202_62_dialog_content = "If I may, I recommend you leave this Colossus immediately.",
  ui_story_5036_50360202_63_dialog_content = "Not only is it filled with cobwebs, it also seems to house countless dirty Eclipsites.",
  ui_story_5036_50360202_64_dialog_content = "However, you need not concern yourself with our safety.",
  ui_story_5036_50360202_65_dialog_content = "Following days of effort, we have contained most Eclipsites in a <color=#FFB400>blockaded area</color> at the rear section.",
  ui_story_5036_50360202_66_dialog_content = "So rest assured!",
  ui_story_5036_50360202_67_dialog_content = "I've already sent people to step up the elimination of Eclipsites, I promise!",
  ui_story_5036_50360202_68_dialog_content = "Those filthy scum will never bother you again.",
  ui_story_5036_50360202_69_dialog_content = "Well done, Judge Matthieu.",
  ui_story_5036_50360202_70_dialog_content = "The honor is mine.",
  ui_story_5036_50360202_71_dialog_content = "So it's relatively safe on this Colossus for the time being?",
  ui_story_5036_50360202_72_dialog_content = "As long as you don't set foot in the <color=#FFB400>blockaded area</color> where the difficulty is dialed way up, you should be fine!",
  ui_story_5036_50360202_73_dialog_content = "Gronru, I want to know more about this Colossus'...",
  ui_story_5036_50360202_74_option_content = "Control system",
  ui_story_5036_50360202_75_dialog_content = "Maybe I can try to land it.",
  ui_story_5036_50360202_76_dialog_content = "I thought of that too, so we thoroughly checked the bridge.",
  ui_story_5036_50360202_77_dialog_content = "But we found the control and navigation systems, even the Echo Template, all damaged.",
  ui_story_5036_50360202_78_dialog_content = "Even you probably can't control it now.",
  ui_story_5036_50360202_79_dialog_content = "How could this be? Then what about the—",
  ui_story_5036_50360202_80_option_content = "Power core",
  ui_story_5036_50360202_81_dialog_content = "The Colossus still moves, so the power core should be intact, right?",
  ui_story_5036_50360202_82_dialog_content = "You could say that.",
  ui_story_5036_50360202_83_dialog_content = "Since it's still supplying power for the Colossus to keep flying.",
  ui_story_5036_50360202_84_dialog_content = "But at the same time, it's also not in the best shape...",
  ui_story_5036_50360202_85_dialog_content = "because it suffered Eclipsite attacks at some point in the past.",
  ui_story_5036_50360202_86_dialog_content = "It's not bad enough for power to suddenly be lost, but it's definitely impacted energy output.",
  ui_story_5036_50360202_87_dialog_content = "That's fixable, right?",
  ui_story_5036_50360202_88_dialog_content = "Restoring the power core is no easy task.",
  ui_story_5036_50360202_89_dialog_content = "At the very least, you've got to shut down the Colossus and turn off the power core first.",
  ui_story_5036_50360202_90_dialog_content = "Otherwise we don't have enough time to diagnose and repair it.",
  ui_story_5036_50360202_91_dialog_content = "Except right now we don't even know how to stop it from flying.",
  ui_story_5036_50360202_92_dialog_content = "How could this be? Then what about the—",
  ui_story_5036_50360202_93_option_content = "Screen and speaker system",
  ui_story_5036_50360202_94_dialog_content = "I noticed it was equipped with what seemed like a screen and speakers on the outside.",
  ui_story_5036_50360202_95_dialog_content = "Yeah, those are authentic!",
  ui_story_5036_50360202_96_dialog_content = "The technology is far beyond our current breadth of knowledge.",
  ui_story_5036_50360202_97_dialog_content = "They're surprisingly well-preserved despite their age.",
  ui_story_5036_50360202_98_dialog_content = "Thanks to help from Siobhan, we figured out how to turn them on!",
  ui_story_5036_50360202_99_dialog_content = "It would be spectacular to play movies on such a giant screen!",
  ui_story_5036_50360202_100_dialog_content = "And...",
  ui_story_5036_50360202_100X1_dialog_content = "Is there anything else?",
  ui_story_5036_50360202_100X2_option_content = "Yes",
  ui_story_5036_50360202_100X3_option_content = "That's all",
  ui_story_5036_50360202_101_dialog_content = "Oh, and another thing...",
  ui_story_5036_50360202_102_dialog_content = "Did you discover any Caelestites or related items?",
  ui_story_5036_50360202_103_dialog_content = "Mm, not yet.",
  ui_story_5036_50360202_104_dialog_content = "But speaking of that...",
  ui_story_5036_50360202_105_dialog_content = "My dear assistant Siobhan helped us dig up historical records concerning this wandering Colossus.",
  ui_story_5036_50360202_106_dialog_content = "From its appearance and size, it's very obvious that this Colossus was the one reported missing by the Caelestites more than a hundred years ago, called—",
  ui_story_5036_50360202_107_dialog_content = "<color=#FFB400>Eulogoz?</color>",
  ui_story_5036_50360202_108_dialog_content = "What, you already knew?",
  ui_story_5036_50360202_109_dialog_content = "Unfortunately, knowing its name matters not.",
  ui_story_5036_50360202_110_dialog_content = "This Colossus is filled to the brim with evil technology and must inevitably be destroyed.",
  ui_story_5036_50360202_111_dialog_content = "Sorry, what? Who's destroying Eulogoz?",
  ui_story_5036_50360202_112_dialog_content = "Don't misunderstand. It wasn't my sole decision.",
  ui_story_5036_50360202_113_dialog_content = "It was the solution that the majority of us agreed on.",
  ui_story_5036_50360202_114_dialog_content = "Wow, can you act any more villainous?",
  ui_story_5036_50360202_115_dialog_content = "It's too soon to say that. I haven't signed off on it yet.",
  ui_story_5036_50360202_116_dialog_content = "Well, perhaps it won't be your choice at all in the end.",
  ui_story_5036_50360202_117_dialog_content = "What's going on, Judge Matthieu? Please elaborate.",
  ui_story_5036_50360202_118_dialog_content = "You heard me, Lady Carleen.",
  ui_story_5036_50360202_119_dialog_content = "This Colossus is of no value and is teeming with uncontrollable Eclipsites.",
  ui_story_5036_50360202_120_dialog_content = "Leaving it to drift along will pose a great threat to the survival of everyone in Astra.",
  ui_story_5036_50360202_121_dialog_content = "Also...",
  ui_story_5036_50360202_122_dialog_content = "What happens if it crash lands in Lumopolis?",
  ui_story_5036_50360202_123_dialog_content = "Destroying this derelict machine keeps our hometown safe.",
  ui_story_5036_50360202_124_dialog_content = "I'm sure you're as aware as I am that the City Lord would make the same call if he was present.",
  ui_story_5036_50360202_125_dialog_content = "Our expedition teams have been searching endlessly for remnants of Colossi in the wilderness.",
  ui_story_5036_50360202_126_dialog_content = "Now that we've finally found one that's actually working, we're going to destroy it?",
  ui_story_5036_50360202_127_dialog_content = "Don't listen to his villainous nonsense, Vice.",
  ui_story_5036_50360202_128_dialog_content = "We already determined that its flight path won't cross into Lumopolis.",
  ui_story_5036_50360202_129_dialog_content = "And if we keep doing what we're doing here, we'll get rid of all the Eclipsites.",
  ui_story_5036_50360202_130_dialog_content = "Furthermore, Eulogoz isn't \"completely worthless\" as that buffoon claims.",
  ui_story_5036_50360202_131_dialog_content = "Every single part of it is valuable to research.",
  ui_story_5036_50360202_132_dialog_content = "Even though a lot is damaged and very hard to fix...",
  ui_story_5036_50360202_133_dialog_content = "I still think it's worth the price of fixing.",
  ui_story_5036_50360202_134_dialog_content = "But you must also realize...",
  ui_story_5036_50360202_135_dialog_content = "that it's much more financially efficient for you to just salvage the parts you want to study and blow up the rest.",
  ui_story_5036_50360202_136_dialog_content = "Why leave this uncontrollable thing flying all over the sky?",
  ui_story_5036_50360202_137_dialog_content = "It's much more valuable to study a whole sample!",
  ui_story_5036_50360202_138_dialog_content = "Are you able to provide evidence of the potential for the Colossus to be fixed?",
  ui_story_5036_50360202_139_dialog_content = "I... I need more time!",
  ui_story_5036_50360202_140_dialog_content = "Time waits for no one.",
  ui_story_5036_50360202_141_dialog_content = "The longer you wait, the more costly this endeavor is.",
  ui_story_5036_50360202_142_dialog_content = "We shoot the Colossus down, complete the mission, and go our separate ways. Isn't that better?",
  ui_story_5036_50360202_143_dialog_content = "So you just want to go home?",
  ui_story_5036_50360202_144_dialog_content = "Don't misunderstand, I'm merely employing negotiation tactics, Lady Carleen.",
  ui_story_5036_50360202_145_dialog_content = "Eulogoz belongs to the Caelestites. I won't let anyone shoot it down!",
  ui_story_5036_50360202_146_dialog_content = "I can help clear the Eclipsites out!",
  ui_story_5036_50360202_147_dialog_content = "I'll also prove to you its true worth!",
  ui_story_5036_50360202_148_dialog_content = "Indeed. I'll help as well.",
  ui_story_5036_50360202_149_dialog_content = "What are you doing, Lady Carleen?",
  ui_story_5036_50360202_150_dialog_content = "Aha, looks like the Princess of Lumopolis is reluctant to see Eulogoz shot down as well!",
  ui_story_5036_50360202_151_dialog_content = "Darling, there's no time for reluctance in this world.",
  ui_story_5036_50360202_152_dialog_content = "If there is, it only means not enough money has been offered.",
  ui_story_5036_50360202_153_dialog_content = "Huh?",
  ui_story_5036_50360202_154_dialog_content = "Even though I don't mind girls fawning over me, this still gives me goosebumps.",
  ui_story_5036_50360202_155_dialog_content = "Lady Sheol?",
  ui_story_5036_50360202_156_dialog_content = "Ah, PlayerName, my VIP!",
  ui_story_5036_50360202_157_dialog_content = "You haven't been to the Cloudrover Guild to see me for a very long time.",
  ui_story_5036_50360202_158_dialog_content = "But that's no reason for you to come this far to sell me stuff...",
  ui_story_5036_50360202_159_dialog_content = "Hahaha, our adorable PlayerName has developed a sense of humor.",
  ui_story_5036_50360202_160_dialog_content = "But in a sense, you're right.",
  ui_story_5036_50360202_161_dialog_content = "This time, though, I've got a bit of a different proposal.",
  ui_story_5036_50360202_162_dialog_content = "Come here, darling!",
  ui_story_5036_50360202_163_dialog_content = "You talking to me?",
  ui_story_5036_50360202_164_dialog_content = "Fear not harm nor failure.",
  ui_story_5036_50360202_165_dialog_content = "Persistence will be rewarded by good fortune.",
  ui_story_5036_50360202_166_dialog_content = "Don't be discouraged or dejected.",
  ui_story_5036_50360202_167_dialog_content = "Just look Goldie's way!",
  ui_story_5036_50360202_168_dialog_content = "Visitors of the Colossus, nice to meet you all!",
  ui_story_5036_50360202_169_dialog_content = "G-Goldie?",
  ui_story_5036_50360202_170_dialog_content = "Hello, PlayerName! How have you been?",
  ui_story_5036_50360202_171_dialog_content = "What?",
  ui_story_5036_50360202_172_dialog_content = "What's Goldie doing here?",
  ui_story_5036_50360202_173_dialog_content = "Since it appears everyone knows each other, I can get the business talk started.",
  ui_story_5036_50360202_174_dialog_content = "I think you overestimate me, Lady Sheol.",
  ui_story_5036_50360202_175_dialog_content = "I could never afford hiring a celebrity to put on a show for me.",
  ui_story_5036_50360202_176_dialog_content = "Darling, the reason I rode in an expensive rental airship and came all this way with the hottest star in tow...",
  ui_story_5036_50360202_177_dialog_content = "certainly wasn't just for pitching a business venture to you alone.",
  ui_story_5036_50360202_178_dialog_content = "This might be a bit too sudden and it might sound shocking, hehe.",
  ui_story_5036_50360202_179_dialog_content = "But you see, we want to throw a special, one-of-a-kind concert on this Colossus that sends shockwaves throughout Astra!",
  ui_story_5036_50360202_180_dialog_content = "When it gets to Umbraton...",
  ui_story_5036_50360202_181_dialog_content = "I'll stand atop it and sing my blessings for everyone to hear!",
  ui_story_5036_50360202_182_dialog_content = "All of Umbraton and Lumopolis will be able see the show on the giant screen!",
  ui_story_5036_50360202_183_dialog_content = "Hmph, commoners never change... Always dreaming too big for your britches.",
  ui_story_5036_50360202_184_dialog_content = "You don't really think you can sing just because you have a mouth, right? And by the way, you look like you're wearing cake decorations.",
  ui_story_5036_50360202_185_dialog_content = "What kind of vulgar term is \"idol,\" anyway?",
  ui_story_5036_50360202_186_dialog_content = "Wow, this is why people shouldn't seclude themselves on tiny floating islands like you lot do in Lumopolis.",
  ui_story_5036_50360202_187_dialog_content = "You shouldn't speak when you don't even know what an idol is.",
  ui_story_5036_50360202_188_dialog_content = "Are you calling me ignorant?",
  ui_story_5036_50360202_189_dialog_content = "The truth always hurts.",
  ui_story_5036_50360202_190_dialog_content = "Siobhan, let's educated our judge here on the concept of an idol, shall we?",
  ui_story_5036_50360202_191_dialog_content = "Yes, Officer Gronru.",
  ui_story_5036_50360202_192_dialog_content = "Idols are a newly emerged occupation in Umbraton and the Rediesel Desert.",
  ui_story_5036_50360202_193_dialog_content = "They mainly engage in entertainment-related activities, such as singing, dancing, and hosting.",
  ui_story_5036_50360202_194_dialog_content = "Compared to traditional singers, dancers, and actors, they're much more willing to be closer to their fans.",
  ui_story_5036_50360202_195_dialog_content = "They garner support with their individual charm and, in return, spread positivity to their fans.",
  ui_story_5036_50360202_196_dialog_content = "Yeah, that's the gist of it.",
  ui_story_5036_50360202_197_dialog_content = "My Goldie is multitalented, though our current focus is on her singing career.",
  ui_story_5036_50360202_198_dialog_content = "I see...",
  ui_story_5036_50360202_199_dialog_content = "Uh, I mean, I'm not interested in commoner matters!",
  ui_story_5036_50360202_200_dialog_content = "I got to where I am today all thanks to my fans, the Goldilocks.",
  ui_story_5036_50360202_201_dialog_content = "I want them to see me performing for them on the biggest stage possible!",
  ui_story_5036_50360202_202_dialog_content = "Heh, I don't mind concerts...",
  ui_story_5036_50360202_203_dialog_content = "But isn't it too much to host one on the Wandering Colossus?",
  ui_story_5036_50360202_204_dialog_content = "Honey, didn't you say yourself that the screen and stereo systems were in perfect working order?",
  ui_story_5036_50360202_205_dialog_content = "Surely someone as passionate about Colossi as you would love to witness these systems running in person, wouldn't you?",
  ui_story_5036_50360202_206_dialog_content = "Well...",
  ui_story_5036_50360202_207_dialog_content = "Imagine, a massive crowd gathering by the Gold River bank. They only have to look up...",
  ui_story_5036_50360202_208_dialog_content = "to see the concert on an enormous screen.",
  ui_story_5036_50360202_209_dialog_content = "People riding on airships can even watch the show over the concert stage.",
  ui_story_5036_50360202_210_dialog_content = "That sounds like it'd be a huge fest for the entire continent...",
  ui_story_5036_50360202_211_dialog_content = "Yes, a grand festival for Astra! I like how you put that, PlayerName!",
  ui_story_5036_50360202_212_dialog_content = "I was surprised to hear you call this Colossus Eulogoz.",
  ui_story_5036_50360202_213_dialog_content = "Maybe it was built to broadcast songs.",
  ui_story_5036_50360202_214_dialog_content = "If it really must be destroyed...",
  ui_story_5036_50360202_215_dialog_content = "I'd love for it to deliver one final song before then!",
  ui_story_5036_50360202_216_dialog_content = "!!!",
  ui_story_5036_50360202_217_dialog_content = "What a pity.",
  ui_story_5036_50360202_218_dialog_content = "The Colossus is flying through an uninhabited region tomorrow, which is the best location to shoot it down.",
  ui_story_5036_50360202_219_dialog_content = "That won't leave you with any time for a concert.",
  ui_story_5036_50360202_220_dialog_content = "Let's not rush things, people.",
  ui_story_5036_50360202_221_dialog_content = "After it flies over Umbraton, if it keeps going along the Gold River...",
  ui_story_5036_50360202_222_dialog_content = "it'll reach an even bigger uninhabited region.",
  ui_story_5036_50360202_223_dialog_content = "You mean... the sea?",
  ui_story_5036_50360202_224_dialog_content = "Shoot down the Colossus over the sea?",
  ui_story_5036_50360202_225_dialog_content = "I think it's a good idea, Officer Gronru.",
  ui_story_5036_50360202_226_dialog_content = "A successful concert would demonstrate its value and save it from destruction.",
  ui_story_5036_50360202_227_dialog_content = "That'll also buy us more time to try and fix the Colossus.",
  ui_story_5036_50360202_228_dialog_content = "If the concert proves to be a failure, we can still shoot it down once it's out over the ocean.",
  ui_story_5036_50360202_229_dialog_content = "It's the safest way to do it, as it wouldn't harm anyone on land.",
  ui_story_5036_50360202_230_dialog_content = "Oh, I beg of you!",
  ui_story_5036_50360202_231_dialog_content = "Please postpone the destruction of this Colossus...",
  ui_story_5036_50360202_232_dialog_content = "Allow us to build a stage and host an unprecedented concert!",
  ui_story_5036_50360301_1_dialog_content = "<color=#e8d9bb>Six days until the concert</color>",
  ui_story_5036_50360301_2_dialog_content = "The left side is off. Move it up a bit.",
  ui_story_5036_50360301_3_dialog_content = "Like this?",
  ui_story_5036_50360301_4_dialog_content = "Now the right side is off.",
  ui_story_5036_50360301_5_dialog_content = "Mm, I think the poster looks fine crooked.",
  ui_story_5036_50360301_6_dialog_content = "What do you think, PlayerName?",
  ui_story_5036_50360301_7_dialog_content = "I-I'm not an expert, so why don't we ask Goldie?",
  ui_story_5036_50360301_8_dialog_content = "Woof!",
  ui_story_5036_50360301_9_dialog_content = "Ahh! Such a cutie! I want to pet Marshmallow every time I see it!",
  ui_story_5036_50360301_10_dialog_content = "Marshmallow loves being pet too!",
  ui_story_5036_50360301_11_dialog_content = "Woof, woof!",
  ui_story_5036_50360301_12_dialog_content = "All right, Marshmallow, I'll play with you later.",
  ui_story_5036_50360301_13_dialog_content = "So give us some time to talk, okay?",
  ui_story_5036_50360301_14_dialog_content = "Woof!",
  ui_story_5036_50360301_15_dialog_content = "What did you guys want to ask me so urgently?",
  ui_story_5036_50360301_16_dialog_content = "We're busy putting up posters, but we're not sure what the best way to do it is...",
  ui_story_5036_50360301_17_dialog_content = "What? You guys don't have to do all this.",
  ui_story_5036_50360301_18_dialog_content = "Yes, we do.",
  ui_story_5036_50360301_19_dialog_content = "If it wasn't for your concert idea, Eulogoz would probably be destroyed by now.",
  ui_story_5036_50360301_20_dialog_content = "We can't deal with any of the equipment, so posters are all we can do.",
  ui_story_5036_50360301_21_dialog_content = "Oh, you guys already helped me more than you know.",
  ui_story_5036_50360301_22_dialog_content = "Without you, I don't think Illumina and Lumopolis would ever have agreed to this.",
  ui_story_5036_50360301_23_dialog_content = "The Grand Marshal did authorize me to make decisions regarding the Wandering Colossus...",
  ui_story_5036_50360301_24_dialog_content = "but I still need a few more days to investigate before I can give you an answer.",
  ui_story_5036_50360301_25_dialog_content = "What else is there to investigate? This is a farce!",
  ui_story_5036_50360301_26_dialog_content = "Why would Lumopolis nobles even care about commoners' idols?",
  ui_story_5036_50360301_27_dialog_content = "I know that just me alone isn't enough, so this won't be my own solo concert.",
  ui_story_5036_50360301_28_dialog_content = "I plan to invite stars from everywhere to join me in this concert in the sky!",
  ui_story_5036_50360301_29_dialog_content = "Maybe in Lumopolis and Illumina, you have a different idea of what idols are,",
  ui_story_5036_50360301_30_dialog_content = "but that's all right. You can send your idols to participate too, whomever they may be!",
  ui_story_5036_50360301_31_dialog_content = "I support this!",
  ui_story_5036_50360301_32_dialog_content = "Huh?",
  ui_story_5036_50360301_33_dialog_content = "I support Goldie staging a concert on the Colossus!",
  ui_story_5036_50360301_34_dialog_content = "She's right. Eulogoz's purpose may have been to broadcast music.",
  ui_story_5036_50360301_35_dialog_content = "As a Caelestite, I want to see it fulfill its purpose.",
  ui_story_5036_50360301_36_dialog_content = "And I want to see people from different places put their biases aside and revel in music together!",
  ui_story_5036_50360301_37_dialog_content = "Maybe Eulogoz came back to help us understand",
  ui_story_5036_50360301_38_dialog_content = "that we're capable of accomplishing something together, regardless of where we're from or who we are!",
  ui_story_5036_50360301_39_dialog_content = "Please give Goldie and Eugoloz the time they need.",
  ui_story_5036_50360301_40_dialog_content = "And me as well. Maybe...",
  ui_story_5036_50360301_41_dialog_content = "Maybe I can find a way to save Eulogoz!",
  ui_story_5036_50360301_42_dialog_content = "Thinking back now, your speech was so epic, PlayerName!",
  ui_story_5036_50360301_43_dialog_content = "It made me so emotional I almost cried.",
  ui_story_5036_50360301_44_dialog_content = "No wonder Sheol always says that Lovegators outnumber the Goldilocks.",
  ui_story_5036_50360301_45_dialog_content = "Nah, I'm not all that... I guess I'm easily excitable and have a tendency to start rambling without thinking.",
  ui_story_5036_50360301_46_dialog_content = "Personally, I thought Lady Sheol was the coolest.",
  ui_story_5036_50360301_47_dialog_content = "She practically glowed when she smiled and said she would foot the bill for everyone working on the project!",
  ui_story_5036_50360301_48_dialog_content = "Businesspeople don't make losing deals.",
  ui_story_5036_50360301_49_dialog_content = "She was certain the concert would be profitable when she decided to invest in it.",
  ui_story_5036_50360301_50_dialog_content = "But how will she make money when everyone just has to stand by the Gold River and listen to it for free?",
  ui_story_5036_50360301_51_dialog_content = "Too bad she's already back in Umbraton to promote the concert.",
  ui_story_5036_50360301_52_dialog_content = "I've got to ask her how she's profiting!",
  ui_story_5036_50360301_53_dialog_content = "Vice, sometimes I think you should have been born in Umbraton.",
  ui_story_5036_50360301_54_dialog_content = "You're way more serious discussing Nightium than you ever were during your years as an exchange student in Lumopolis.",
  ui_story_5036_50360301_55_dialog_content = "I am? Well, blame a certain someone for that.",
  ui_story_5036_50360301_56_dialog_content = "Hey, why're you all looking at me?",
  ui_story_5036_50360301_57_dialog_content = "Heh, we can't hope to make sense of Sheol's business maneuvers.",
  ui_story_5036_50360301_58_dialog_content = "All we have to do is do our own jobs!",
  ui_story_5036_50360301_59_dialog_content = "And right now, my job is to prepare for the concert!",
  ui_story_5036_50360301_60_dialog_content = "...",
  ui_story_5036_50360301_61_dialog_content = "Something on your mind, PlayerName?",
  ui_story_5036_50360301_62_dialog_content = "Oh, I was just thinking, while the screen and speakers on Eulogoz are fine...",
  ui_story_5036_50360301_63_dialog_content = "Are those really enough for everyone on the ground to hear the music?",
  ui_story_5036_50360301_64_dialog_content = "Do you have so little faith in Caelestite technology?",
  ui_story_5036_50360301_65_dialog_content = "I have faith in it, of course! It's just that...",
  ui_story_5036_50360301_66_dialog_content = "Look, I know what everyone's worried about. Trust me, I want the concert to go smoothly more than anyone.",
  ui_story_5036_50360301_67_dialog_content = "I asked Siobhan about the equipment issues and learned how to control the volume.",
  ui_story_5036_50360301_68_dialog_content = "They'll definitely be able to hear my voice on the ground through the equipment!",
  ui_story_5036_50360301_69_dialog_content = "So you took care of it already? I shouldn't have expected any less of a professional idol.",
  ui_story_5036_50360301_70_dialog_content = "By the way, aren't you looking for a way to save Eulogoz?",
  ui_story_5036_50360301_71_dialog_content = "Any news on that front?",
  ui_story_5036_50360301_72_dialog_content = "Nothing at all.",
  ui_story_5036_50360301_73_dialog_content = "I really had no idea what I was getting myself into.",
  ui_story_5036_50360301_74_dialog_content = "Why did I think I could come up with something when even Illumina's Tech Officer couldn't?",
  ui_story_5036_50360301_75_dialog_content = "Don't be so negative, PlayerName!",
  ui_story_5036_50360301_76_dialog_content = "You want me to consult my <color=#FFB400>lucky bullet</color> for you?",
  ui_story_5036_50360301_77_dialog_content = "Your what?",
  ui_story_5036_50360301_78_dialog_content = "Lucky bullet, will PlayerName find a way to save Eulogoz?",
  ui_story_5036_50360301_79_dialog_content = "If so, land head first!",
  ui_story_5036_50360301_80_dialog_content = "PlayerName, come toss the bullet in the air!",
  ui_story_5036_50360301_81_dialog_content = "Toss it? Like this?",
  ui_story_5036_50360301_82_dialog_content = "<color=#e8d9bb>Whoosh...</color>",
  ui_story_5036_50360301_83_dialog_content = "There it goes...",
  ui_story_5036_50360301_84_dialog_content = "<color=#e8d9bb>Clink!</color>",
  ui_story_5036_50360301_85_dialog_content = "Perfect! Look, it landed head first!",
  ui_story_5036_50360301_86_dialog_content = "My lucky bullet is sure you will find a way!",
  ui_story_5036_50360301_87_dialog_content = "Really?",
  ui_story_5036_50360301_88_dialog_content = "When I run into trouble, the bullet always has an answer for me.",
  ui_story_5036_50360301_89_dialog_content = "I think it'll bring you good luck too!",
  ui_story_5036_50360301_90_dialog_content = "... All right. I won't give up!",
  ui_story_5036_50360301_91_dialog_content = "You always fill me with motivation, Goldie.",
  ui_story_5036_50360301_92_dialog_content = "I think I'm going to be a Goldilock myself!",
  ui_story_5036_50360301_93_dialog_content = "Haha, you should!",
  ui_story_5036_50360301_94_dialog_content = "I've been a diehard Lovegator for a long time already, just so you know.",
  ui_story_5036_50360301_95_dialog_content = "What?",
  ui_story_5036_50360301_96_dialog_content = "<color=#e8d9bb>Click!</color>",
  ui_story_5036_50360301_97_dialog_content = "Huh?",
  ui_story_5036_50360301_98_dialog_content = "P-Pardon me!",
  ui_story_5036_50360301_99_dialog_content = "I was moved by your newfound camaraderie and couldn't help but take a group photo for memory's sake...",
  ui_story_5036_50360301_100_dialog_content = "Wow, thanks Brandy!",
  ui_story_5036_50360301_101_dialog_content = "(Goldie... said my name...?)",
  ui_story_5036_50360301_102_dialog_content = "The press in Umbraton sure knows what they're doing if they were able to send you to cover the concert so fast.",
  ui_story_5036_50360301_103_dialog_content = "Actually, I came with PlayerName.",
  ui_story_5036_50360301_104_dialog_content = "Yeah, Brandy's doing a feature on me.",
  ui_story_5036_50360301_105_dialog_content = "Ah, so you were here for him?",
  ui_story_5036_50360301_106_dialog_content = "I think I'm a little jealous.",
  ui_story_5036_50360301_107_dialog_content = "Uh, um...",
  ui_story_5036_50360301_108_dialog_content = "Just kidding!",
  ui_story_5036_50360301_109_dialog_content = "I didn't think you'd remember me.",
  ui_story_5036_50360301_110_dialog_content = "Of course I do. I kept a clipping of that article you did on me!",
  ui_story_5036_50360301_111_dialog_content = "But that was so badly written, the editor even chewed me out for it.",
  ui_story_5036_50360301_112_dialog_content = "I don't want to hear you say that about yourself, Brandy.",
  ui_story_5036_50360301_113_dialog_content = "You're more diligent than anyone when it comes to interviews!",
  ui_story_5036_50360301_114_dialog_content = "You've got to believe in yourself and your judgment, no matter what others might say.",
  ui_story_5036_50360301_115_dialog_content = "Believe in myself...",
  ui_story_5036_50360301_116_dialog_content = "You always spread so much positivity that I gain the energy to keep on working.",
  ui_story_5036_50360301_117_dialog_content = "But I heard the senior reporters say you've been planning your show at the Star Theater for a long time.",
  ui_story_5036_50360301_118_dialog_content = "Won't that be canceled if you're doing a concert on the Wandering Colossus?",
  ui_story_5036_50360301_119_dialog_content = "About that...",
  ui_story_5036_50360301_120_dialog_content = "I simply can't miss a venue as grand as Eulogoz.",
  ui_story_5036_50360301_121_dialog_content = "There'll be plenty more opportunities for me on Umbraton stages in the future.",
  ui_story_5036_50360301_122_dialog_content = "I see.",
  ui_story_5036_50360301_123_dialog_content = "Haha! Everything worked out perfectly!",
  ui_story_5036_50360301_124_dialog_content = "The lucky bullet was right about me getting a great reporter!",
  ui_story_5036_50360301_125_dialog_content = "What?",
  ui_story_5036_50360301_126_dialog_content = "Sheol asked me to get a reporter to cover the concert, but I had no idea where to find one.",
  ui_story_5036_50360301_127_dialog_content = "If possible, I'd love for you to cover this project all the way to the end, Brandy!",
  ui_story_5036_50360301_128_dialog_content = "That is, if it's not too much to ask...",
  ui_story_5036_50360301_129_dialog_content = "You can think about it before giving me an answer.",
  ui_story_5036_50360301_130_dialog_content = "(That's the kind, considerate Goldie I know!)",
  ui_story_5036_50360301_131_dialog_content = "(That news about her having a mean streak was probably made up.)",
  ui_story_5036_50360301_132_dialog_content = "Let's not stand around.",
  ui_story_5036_50360301_133_dialog_content = "We still have posters to put up!",
  ui_story_5036_50360301_134_dialog_content = "They sure move fast.",
  ui_story_5036_50360301_135_dialog_content = "The corridor here is plastered with colorful posters too.",
  ui_story_5036_50360301_136_dialog_content = "I just don't get the deal with idols.",
  ui_story_5036_50360301_137_dialog_content = "They go on stage, smile, act cute, and get cheers and applause.",
  ui_story_5036_50360301_138_dialog_content = "Meanwhile, we work hard down here and get no praise at all.",
  ui_story_5036_50360301_139_dialog_content = "Right? I've never heard of idols in such gaudy, weird costumes before.",
  ui_story_5036_50360301_140_dialog_content = "Singing and dancing can only entertain, not save people!",
  ui_story_5036_50360301_141_dialog_content = "I never thought there'd be a day I see eye-to-eye with someone from Lumopolis.",
  ui_story_5036_50360301_142_dialog_content = "Well, we're the unlucky ones.",
  ui_story_5036_50360301_143_dialog_content = "They get to throw a concert and leave us to secure the perimeter and clear out Eclipsites!",
  ui_story_5036_50360301_144_dialog_content = "I don't know why, but the past couple of days I've been feeling more and more fatigued.",
  ui_story_5036_50360301_145_dialog_content = "Tell me about it.",
  ui_story_5036_50360301_146_dialog_content = "Ahem...",
  ui_story_5036_50360301_147_dialog_content = "!!!",
  ui_story_5036_50360301_148_dialog_content = "Salutations, Lieutenant Vice!",
  ui_story_5036_50360301_149_dialog_content = "Good day, Lady Carleen!",
  ui_story_5036_50360301_150_dialog_content = "At ease. You're doing a great job.",
  ui_story_5036_50360301_151_dialog_content = "Uh, we probably said a lot of stupid things, so please forgive us!",
  ui_story_5036_50360301_152_dialog_content = "Forgive us, Lieutenant Vice!",
  ui_story_5036_50360301_153_dialog_content = "Mocking civilians isn't what we do as knights.",
  ui_story_5036_50360301_154_dialog_content = "You ought to know what you must do now.",
  ui_story_5036_50360301_155_dialog_content = "My apologies, Miss Goldie!",
  ui_story_5036_50360301_156_dialog_content = "And you too.",
  ui_story_5036_50360301_157_dialog_content = "S-Sorry, Miss Goldie!",
  ui_story_5036_50360301_158_dialog_content = "I was not chivalrous in my speech. Please punish me with this sword!",
  ui_story_5036_50360301_159_dialog_content = "All right. I shall punish you two...",
  ui_story_5036_50360301_160_dialog_content = "by sending you to bed early. Have a sweet dream!",
  ui_story_5036_50360301_161_dialog_content = "Huh?",
  ui_story_5036_50360301_162_dialog_content = "Come on, who doesn't complain when they're at work?",
  ui_story_5036_50360301_163_dialog_content = "And truly, I'm the reason for everyone's increased workload.",
  ui_story_5036_50360301_164_dialog_content = "I should be the one apologizing!",
  ui_story_5036_50360301_165_dialog_content = "I've asked Sheol to hire mercenaries from Umbraton to help shoulder the burden.",
  ui_story_5036_50360301_166_dialog_content = "You'll have more downtime for yourselves!",
  ui_story_5036_50360301_167_dialog_content = "This...",
  ui_story_5036_50360301_168_dialog_content = "There are energy drinks at the end of the hallway. I figure you two haven't had a chance to grab some?",
  ui_story_5036_50360301_169_dialog_content = "Go try it out!",
  ui_story_5036_50360301_170_dialog_content = "I guarantee you'll feel reinvigorated after having some!",
  ui_story_5036_50360301_171_dialog_content = "...",
  ui_story_5036_50360301_172_dialog_content = "Why are you still here? You heard her.",
  ui_story_5036_50360301_173_dialog_content = "Your Highness...?",
  ui_story_5036_50360301_174_dialog_content = "Miss Goldie has handed out her punishment, so you may leave.",
  ui_story_5036_50360301_175_dialog_content = "Thank you, Your Highness! Thank you, Miss Goldie!",
  ui_story_5036_50360301_176_dialog_content = "Thank you, Lieutenant Vice! Thank you, Miss Goldie!",
  ui_story_5036_50360301_177_dialog_content = "There's a lot to consider when putting on a concert, indeed.",
  ui_story_5036_50360301_178_dialog_content = "Can't believe I forgot to take the soldiers into consideration...",
  ui_story_5036_50360301_179_dialog_content = "If you feel it's necessary, Goldie, I can request more Lumo Knights over.",
  ui_story_5036_50360301_180_dialog_content = "That's okay, I shouldn't trouble you more than I have!",
  ui_story_5036_50360301_181_dialog_content = "I already asked the White Flame Mercenaries to help me deliver supplies and construct the stage.",
  ui_story_5036_50360301_182_dialog_content = "I'll just add on to their agenda when they get here!",
  ui_story_5036_50360301_183_dialog_content = "It's not cheap to hire the White Flames for things like this.",
  ui_story_5036_50360301_184_dialog_content = "Will Sheol be responsible for the expenses?",
  ui_story_5036_50360301_185_dialog_content = "...",
  ui_story_5036_50360301_186_dialog_content = "Goldie?",
  ui_story_5036_50360301_187_dialog_content = "Huh?",
  ui_story_5036_50360301_188_dialog_content = "Oh, uh... yeah, Sheol is very resourceful. It shouldn't be a problem.",
  ui_story_5036_50360301_189_dialog_content = "Were you concerned about something, Goldie?",
  ui_story_5036_50360301_190_dialog_content = "Not really...",
  ui_story_5036_50360301_191_dialog_content = "It's just that the White Flames should be here by now, but they aren't…",
  ui_story_5036_50360301_192_dialog_content = "<color=#e8d9bb>*Chaotic footsteps*</color>",
  ui_story_5036_50360301_193_dialog_content = "I hear footsteps... Sounds like a group of people coming this way.",
  ui_story_5036_50360301_194_dialog_content = "Speak of the devil... That must be them.",
  ui_story_5036_50360301_195_dialog_content = "What a coincidence!",
  ui_story_5036_50360301_196_dialog_content = "Graaaaaagh!",
  ui_story_5036_50360301_197_dialog_content = "What? Oh, no!",
  ui_story_5036_50360301_198_dialog_content = "These aren't mercenaries!",
  ui_story_5036_50360301_199_dialog_content = "I didn't hire Eclipsites!",
  ui_story_5036_50360302_1_dialog_content = "Watch out behind you, Goldie!",
  ui_story_5036_50360302_2_dialog_content = "What...?",
  ui_story_5036_50360302_3_dialog_content = "Grah!",
  ui_story_5036_50360302_4_dialog_content = "Begone!",
  ui_story_5036_50360302_5_dialog_content = "The White Flame Mercenaries are here!",
  ui_story_5036_50360302_6_dialog_content = "Are you okay, Miss Goldie?",
  ui_story_5036_50360302_7_dialog_content = "I'm fine, thanks to your perfect timing.",
  ui_story_5036_50360302_8_dialog_content = "I wouldn't call it perfect...",
  ui_story_5036_50360302_9_dialog_content = "Getting the supplies for the stage cost more time than expected, so I'm sorry that we just got here now.",
  ui_story_5036_50360302_10_dialog_content = "Though I never thought there would be Eclipsites on the Wandering Colossus either.",
  ui_story_5036_50360302_11_dialog_content = "Well, I found that out after I got on myself.",
  ui_story_5036_50360302_12_dialog_content = "But Illumina and Lumopolis soldiers confined most of the Eclipsites to a secure area in the rear section.",
  ui_story_5036_50360302_13_dialog_content = "There are still some stragglers wandering around, but as you saw...",
  ui_story_5036_50360302_14_dialog_content = "They're not formidable.",
  ui_story_5036_50360302_15_dialog_content = "The soldiers have stepped up in their cleansing efforts.",
  ui_story_5036_50360302_16_dialog_content = "Now with your help...",
  ui_story_5036_50360302_17_dialog_content = "I'm sure these stragglers and those in the rear will be dealt with too.",
  ui_story_5036_50360302_18_dialog_content = "We'll do our best to complete Lady Sheol's assignments.",
  ui_story_5036_50360302_19_dialog_content = "You can count on us!",
  ui_story_5036_50360302_20_dialog_content = "Thanks, everyone!",
  ui_story_5036_50360302_21_dialog_content = "No sweat. Oh, we heard back in Umbraton that",
  ui_story_5036_50360302_22_dialog_content = "a ton of people have already signed up for the concert!",
  ui_story_5036_50360302_23_dialog_content = "News sure travels fast!",
  ui_story_5036_50360302_24_dialog_content = "Wow, people are way more excited about it than I imagined.",
  ui_story_5036_50360302_25_dialog_content = "Before the show officially starts, we're also running an <color=#FFB400>idol audition</color>.",
  ui_story_5036_50360302_26_dialog_content = "We're gonna pick out idols with strong stage presence.",
  ui_story_5036_50360302_27_dialog_content = "An idol audition? That sounds like an exciting event!",
  ui_story_5036_50360302_28_dialog_content = "The first round is tomorrow, so we'll need several of you for crowd control.",
  ui_story_5036_50360302_29_dialog_content = "No problem!",
  ui_story_5036_50360302_30_dialog_content = "Let's get busy, guys!",
  ui_story_5036_50360302_31_dialog_content = "Got it!",
  ui_story_5036_50360302_32_dialog_content = "You're a great motivator.",
  ui_story_5036_50360302_33_dialog_content = "An idol audition sounds like a lot of work, though.",
  ui_story_5036_50360302_34_dialog_content = "It's something I've always wanted to do. Not every day do I get the chance to fulfill one of my dreams.",
  ui_story_5036_50360302_35_dialog_content = "It doesn't feel like work to me at all!",
  ui_story_5036_50360302_36_dialog_content = "Have you always wanted to hold an audition?",
  ui_story_5036_50360302_37_dialog_content = "That's right. I love both the stage and the audience beneath it.",
  ui_story_5036_50360302_38_dialog_content = "I want to spread my passion to others!",
  ui_story_5036_50360302_39_dialog_content = "I want there to be more idols to move and inspire the audience.",
  ui_story_5036_50360302_40_dialog_content = "I have to support all those who aspire to be idols while I have the ability to.",
  ui_story_5036_50360302_41_dialog_content = "You really love your career.",
  ui_story_5036_50360302_42_dialog_content = "Speaking of which...",
  ui_story_5036_50360302_43_dialog_content = "Would you be interested in <color=#FFB400>joining the selection committee</color>?",
  ui_story_5036_50360302_44_dialog_content = "Who, me?",
  ui_story_5036_50360302_45_dialog_content = "Yeah! Being on the committee is actually pretty easy.",
  ui_story_5036_50360302_46_dialog_content = "You just have to watch the contestants' performances and decide who should make it onto the stage based on your preferences.",
  ui_story_5036_50360302_47_dialog_content = "I was saving the position for Sheol, but she seems really busy doing all the promotion stuff.",
  ui_story_5036_50360302_48_dialog_content = "After mulling it over, I decided that you're most suited for the task.",
  ui_story_5036_50360302_49_dialog_content = "But I'm not sure I can handle it.",
  ui_story_5036_50360302_50_dialog_content = "Hey! Carleen, Vice... Don't you two like to sing too?",
  ui_story_5036_50360302_51_dialog_content = "Interested in joining the committee?",
  ui_story_5036_50360302_52_dialog_content = "Uh...",
  ui_story_5036_50360302_53_dialog_content = "Well...",
  ui_story_5036_50360302_54_dialog_content = "Oh, you didn't know?",
  ui_story_5036_50360302_55_dialog_content = "Vice and Carleen both signed up for the audition!",
  ui_story_5036_50360302_56_dialog_content = "They what?!",
  ui_story_5036_50360302_57_dialog_content = "Why was I not aware of this?",
  ui_story_5036_50360302_58_dialog_content = "You can't fault us for that. We did tell you.",
  ui_story_5036_50360302_59_dialog_content = "But you were listening to something at the time and paid no attention to us.",
  ui_story_5036_50360302_60_dialog_content = "Vice and I discussed it. If the concert is a success, that should be enough to prove Eulogoz's worth.",
  ui_story_5036_50360302_61_dialog_content = "Then, we can persuade the Illumina higher-ups and my father from destroying it.",
  ui_story_5036_50360302_62_dialog_content = "Even if we can't find a way to keep the Colossus under control...",
  ui_story_5036_50360302_63_dialog_content = "At least Eulogoz could still be allowed to continue wandering like it does now.",
  ui_story_5036_50360302_64_dialog_content = "Maybe in a hundred years, it'll drift back to Astra's skies!",
  ui_story_5036_50360302_65_dialog_content = "You two really thought far ahead.",
  ui_story_5036_50360302_66_dialog_content = "Actually, we almost signed you up too, but then we figured...",
  ui_story_5036_50360302_67_dialog_content = "Nah, we shouldn't.",
  ui_story_5036_50360302_68_dialog_content = "I definitely have no confidence in my performance skills, but you don't have to be so blunt about it!",
  ui_story_5036_50360302_69_dialog_content = "You don't have to be good at performing arts to be on the selection committee.",
  ui_story_5036_50360302_70_dialog_content = "All you need is an eye for talent to qualify!",
  ui_story_5036_50360302_71_dialog_content = "Hmm...",
  ui_story_5036_50360302_72_dialog_content = "Sigh, guess this is the only option.",
  ui_story_5036_50360302_73_dialog_content = "It's hard to believe...",
  ui_story_5036_50360302_74_dialog_content = "that I'd be doing something like this at my age.",
  ui_story_5036_50360302_75_dialog_content = "Roar!",
  ui_story_5036_50360302_76_dialog_content = "Hush!",
  ui_story_5036_50360302_77_dialog_content = "<size=35>Roar?</size>",
  ui_story_5036_50360302_78_dialog_content = "It's late, little Drako.",
  ui_story_5036_50360302_79_dialog_content = "You'll scare people by being so loud.",
  ui_story_5036_50360302_80_dialog_content = "I don't want to stick out like a sore thumb right away.",
  ui_story_5036_50360302_81_dialog_content = "*Sniffle*",
  ui_story_5036_50360302_82_dialog_content = "Okay, you hurry back to Fia now.",
  ui_story_5036_50360302_83_dialog_content = "But remember...",
  ui_story_5036_50360302_84_dialog_content = "Do not reveal my whereabouts to her.",
  ui_story_5036_50360401_1_dialog_content = "It's me, chief editor!",
  ui_story_5036_50360401_2_dialog_content = "How do I know who you are if you don't tell me your name?",
  ui_story_5036_50360401_3_dialog_content = "... It's Brandy.",
  ui_story_5036_50360401_4_dialog_content = "Oh, I remember now.",
  ui_story_5036_50360401_5_dialog_content = "The intern who only writes boring articles.",
  ui_story_5036_50360401_6_dialog_content = "I thought you'd quit already.",
  ui_story_5036_50360401_7_dialog_content = "You said you'd give me one last chance.",
  ui_story_5036_50360401_8_dialog_content = "Ah, I seem to recall something like that... So, do you have good news for me?",
  ui_story_5036_50360401_9_dialog_content = "Yeah! Guess what?",
  ui_story_5036_50360401_10_dialog_content = "I'm on Eulogoz right now, the Wandering Colossus everyone's talking about!",
  ui_story_5036_50360401_11_dialog_content = "And?",
  ui_story_5036_50360401_12_dialog_content = "When it flies over Umbraton, there's gonna be a huge concert onboard!",
  ui_story_5036_50360401_13_dialog_content = "I have a tight schedule, so tell me something I don't know.",
  ui_story_5036_50360401_14_dialog_content = "Oh, and...",
  ui_story_5036_50360401_15_dialog_content = "I was chosen to be the official reporter for the concert and I'll also be hosting the idol auditions!",
  ui_story_5036_50360401_16_dialog_content = "You're proud of reporting official press releases?",
  ui_story_5036_50360401_17_dialog_content = "It seems you still don't get it.",
  ui_story_5036_50360401_18_dialog_content = "What I want is inside scoop that's hot enough to lure in views!",
  ui_story_5036_50360401_19_dialog_content = "What?",
  ui_story_5036_50360401_20_dialog_content = "... Inside scoop?",
  ui_story_5036_50360401_21_dialog_content = "<color=#e8d9bb>Five days until the concert</color>",
  ui_story_5036_50360401_22_dialog_content = "Sorry to keep you waiting, dear contestants!",
  ui_story_5036_50360401_23_dialog_content = "Welcome to the audition for the <color=#FFB400>'The Moment the Stars Shine Brightest' Sky Concert</color>.",
  ui_story_5036_50360401_24_dialog_content = "How did you feel boarding the Colossus in exclusive airships?",
  ui_story_5036_50360401_25_dialog_content = "Excited? Elated? Nervous? Thrilled?",
  ui_story_5036_50360401_26_dialog_content = "But there's more excitement and thrills to come.",
  ui_story_5036_50360401_27_dialog_content = "I hereby announce the start of the first round of auditions!",
  ui_story_5036_50360401_28_dialog_content = "Ohhh! Here we go!",
  ui_story_5036_50360401_29_dialog_content = "Please keep quiet for a moment while I explain the rules.",
  ui_story_5036_50360401_30_dialog_content = "As you can see, we have a panel of six judges.",
  ui_story_5036_50360401_31_dialog_content = "You're welcome to talk to me about your favorite sim games!",
  ui_story_5036_50360401_32_dialog_content = "I'll be judging your singing, dancing, visuals, figure, EQ, and IQ.",
  ui_story_5036_50360401_33_dialog_content = "You need to excel in just one of the six to get my vote.",
  ui_story_5036_50360401_34_dialog_content = "I'm looking for perfectly altruistic, wholesome, pure and proper performances worthy of nobles...",
  ui_story_5036_50360401_35_dialog_content = "Are you capable?",
  ui_story_5036_50360401_36_dialog_content = "Go, everyone.",
  ui_story_5036_50360401_37_dialog_content = "I hope to light up the skies with you!",
  ui_story_5036_50360401_38_dialog_content = "Hello, everybody. I'll pay close attention to your performances!",
  ui_story_5036_50360401_39_dialog_content = "The rules are simple, all you need is four votes from the judges...",
  ui_story_5036_50360401_40_dialog_content = "and you'll move on to the next round for a chance to perform on the concert stage.",
  ui_story_5036_50360401_41_dialog_content = "Those who receive unanimous votes automatically get to perform in the concert!",
  ui_story_5036_50360401_42_dialog_content = "If you don't advance, don't worry, because everyone gets three chances.",
  ui_story_5036_50360401_43_dialog_content = "Feel free to use the rooms on Eulogoz to rehearse.",
  ui_story_5036_50360401_44_dialog_content = "Now then, let's get the show rolling!",
  ui_story_5036_50360401_45_dialog_content = "Please come up and perform when your number is called!",
  ui_story_5036_50360401_46_dialog_content = "Number 1, the Illumina Choir!",
  ui_story_5036_50360401_47_dialog_content = "The auditions have started. You don't want to check it out?",
  ui_story_5036_50360401_48_dialog_content = "Nah, not now.",
  ui_story_5036_50360401_49_dialog_content = "I still haven't decided what I'm going to do.",
  ui_story_5036_50360401_50_dialog_content = "If I watch now, it'll only make me even more nervous.",
  ui_story_5036_50360401_51_dialog_content = "I haven't decided what to do either.",
  ui_story_5036_50360401_52_dialog_content = "We signed up mostly because we were worried there wouldn't be enough participants.",
  ui_story_5036_50360401_53_dialog_content = "But seeing how many people are here, I'm actually thinking...",
  ui_story_5036_50360401_54_dialog_content = "Maybe I'm not needed.",
  ui_story_5036_50360401_55_dialog_content = "What? I heard both Illumina and Lumopolis got reserved slots.",
  ui_story_5036_50360401_56_dialog_content = "Illumina chose the Choir, and I thought you would get the Lumopolis slot.",
  ui_story_5036_50360401_57_dialog_content = "That was our performance. Thank you!",
  ui_story_5036_50360401_58_dialog_content = "Your moves were well-synchronized and energetic, and you sang inspirational songs that truly exemplify Illumina's soldiers!",
  ui_story_5036_50360401_59_dialog_content = "I know your group always tours throughout Illumina, and your familiarity with the stage was evident.",
  ui_story_5036_50360401_60_dialog_content = "I loved your singing! Best of luck!",
  ui_story_5036_50360401_61_dialog_content = "Thank you.",
  ui_story_5036_50360401_62_dialog_content = "Now then, the Illumina Choir gets...",
  ui_story_5036_50360401_63_dialog_content = "All 6 votes!",
  ui_story_5036_50360401_64_dialog_content = "They weathered the pressure of auditioning first and earned the chance to perform in the concert! Congratulations!",
  ui_story_5036_50360401_65_dialog_content = "Thank you! We won't let the audience down!",
  ui_story_5036_50360401_66_dialog_content = "Okay, next up, we have the Lumopolis Choir, Keating!",
  ui_story_5036_50360401_67_dialog_content = "So that's how this works.",
  ui_story_5036_50360401_68_dialog_content = "It would be a shame to skip such a rare opportunity.",
  ui_story_5036_50360401_69_dialog_content = "That's exactly why it should be reserved for those who deserve it.",
  ui_story_5036_50360401_70_dialog_content = "What the heck?",
  ui_story_5036_50360401_71_dialog_content = "Hmm?",
  ui_story_5036_50360401_72_dialog_content = "So I'm the only one auditioning now?",
  ui_story_5036_50360401_73_dialog_content = "Oh wait, I know!",
  ui_story_5036_50360401_74_dialog_content = "They're gonna see the concert in Lumopolis too...",
  ui_story_5036_50360401_75_dialog_content = "Are you too shy to perform for your home crowd, Carleen?",
  ui_story_5036_50360401_76_dialog_content = "Not at all!",
  ui_story_5036_50360401_77_dialog_content = "Then prove it.",
  ui_story_5036_50360401_78_dialog_content = "Show everyone what you're capable of.",
  ui_story_5036_50360401_79_dialog_content = "This is ♪",
  ui_story_5036_50360401_80_dialog_content = "Our performance ♪",
  ui_story_5036_50360401_81_dialog_content = "Now please commence ♪",
  ui_story_5036_50360401_82_dialog_content = "Your performance ♪",
  ui_story_5036_50360401_83_dialog_content = "Unbelievable grace!",
  ui_story_5036_50360401_84_dialog_content = "No wonder you were picked by Lord Schwartz himself!",
  ui_story_5036_50360401_85_dialog_content = "Their voices are simply divine and have cleansed me inside and out.",
  ui_story_5036_50360401_86_dialog_content = "The commoners should cherish this.",
  ui_story_5036_50360401_87_dialog_content = "You were blessed by the God of Light to be able to hear such a sacred hymn.",
  ui_story_5036_50360401_88_dialog_content = "Your act ♪",
  ui_story_5036_50360401_89_dialog_content = "Is silly ♪",
  ui_story_5036_50360401_90_dialog_content = "Your words ♪",
  ui_story_5036_50360401_91_dialog_content = "Are empty flattery ♪",
  ui_story_5036_50360401_92_dialog_content = "Hear that? They're melodious even when they speak!",
  ui_story_5036_50360401_93_dialog_content = "You can't tell flattery from mockery.",
  ui_story_5036_50360401_94_dialog_content = "What's this...?",
  ui_story_5036_50360401_95_dialog_content = "Keating also gets 6 votes and heads straight into the concert! Congratulations!",
  ui_story_5036_50360401_96_dialog_content = "Both contestants? This isn't rigged, is it?",
  ui_story_5036_50360401_97_dialog_content = "Are you contestant no. 3, Barbara?",
  ui_story_5036_50360401_98_dialog_content = "That's me, Barbara!",
  ui_story_5036_50360401_99_dialog_content = "Ignore that noisy woman. I, Barbara, was truly born to be an idol!",
  ui_story_5036_50360401_100_dialog_content = "Ha, maybe you should make sure you can hit your notes before getting on stage!",
  ui_story_5036_50360401_101_dialog_content = "Why don't you spend less time criticizing me and more time learning to actually sing instead?",
  ui_story_5036_50360401_102_dialog_content = "It's time for you two to perform.",
  ui_story_5036_50360401_103_dialog_content = "I can't believe this.",
  ui_story_5036_50360401_104_dialog_content = "How did the Rediesel Wrench even end up with someone with as bad a taste in music as you?",
  ui_story_5036_50360401_105_dialog_content = "Oh wow, look who's talking...",
  ui_story_5036_50360401_106_dialog_content = "You really think anyone in the Rediesel Wrench likes your crappy voice?",
  ui_story_5036_50360401_107_dialog_content = "What? Say that again!",
  ui_story_5036_50360401_108_dialog_content = "I dare you!",
  ui_story_5036_50360401_109_dialog_content = "Hey, why is someone else onstage?",
  ui_story_5036_50360401_110_dialog_content = "I'm number 3!",
  ui_story_5036_50360401_111_dialog_content = "Sorry Barbara, and entry no. 4, Regina...",
  ui_story_5036_50360401_112_dialog_content = "The judges disqualified you for disorderly conduct.",
  ui_story_5036_50360401_113_dialog_content = "Please sign up again for the next round.",
  ui_story_5036_50360401_114_dialog_content = "What?!",
  ui_story_5036_50360401_115_dialog_content = "Oh, I see.",
  ui_story_5036_50360401_116_dialog_content = "W-What do you see?",
  ui_story_5036_50360401_117_dialog_content = "Are you feeling lonely because you're going to perform by yourself?",
  ui_story_5036_50360401_118_dialog_content = "Not so loud...",
  ui_story_5036_50360401_119_dialog_content = "Fine, I admit it.",
  ui_story_5036_50360401_120_dialog_content = "We always do everything together as a group, after all.",
  ui_story_5036_50360401_121_dialog_content = "It does feel a little weird suddenly going solo.",
  ui_story_5036_50360401_122_dialog_content = "Alright then.",
  ui_story_5036_50360401_123_dialog_content = "I guess I can help a lonesome dove.",
  ui_story_5036_50360401_124_dialog_content = "I'm not a lonesome dove!",
  ui_story_5036_50360401_125_dialog_content = "Hahahah...",
  ui_story_5036_50360401_126_dialog_content = "However, compared to standing up there alone...",
  ui_story_5036_50360401_127_dialog_content = "I do miss how it feels to be on stage with you.",
  ui_story_5036_50360401_128_dialog_content = "Huh?",
  ui_story_5036_50360401_129_dialog_content = "What's with the sudden nostalgia?",
  ui_story_5036_50360401_130_dialog_content = "Well, anyway, I just think the person I was back then would've been far more keen to perform.",
  ui_story_5036_50360401_131_dialog_content = "Actually, me too...",
  ui_story_5036_50360401_132_dialog_content = "What a shame.",
  ui_story_5036_50360401_133_dialog_content = "No contestant so far has been able to make it into the concert other than our first two.",
  ui_story_5036_50360401_134_dialog_content = "Now, let's welcome the final participant for today.",
  ui_story_5036_50360401_135_dialog_content = "What performance does he have in store for us?",
  ui_story_5036_50360401_136_dialog_content = "Hello, everyone.",
  ui_story_5036_50360401_137_dialog_content = "I am Vic. I'm a wondrous beast trainer.",
  ui_story_5036_50360401_138_dialog_content = "Vic?!",
  ui_story_5036_50360401_139_dialog_content = "PlayerName?",
  ui_story_5036_50360401_140_dialog_content = "I didn't expect to see a familiar face on the selection committee.",
  ui_story_5036_50360401_141_dialog_content = "I must clarify that I truly did not know PlayerName was going to be a judge.",
  ui_story_5036_50360401_142_dialog_content = "It's really you!",
  ui_story_5036_50360401_143_dialog_content = "I thought I was mistaken... Why did you sign up for this?",
  ui_story_5036_50360401_144_dialog_content = "Because I want to be an idol and perform on this one-of-a-kind stage.",
  ui_story_5036_50360401_145_dialog_content = "I never knew you wanted to be an idol.",
  ui_story_5036_50360401_146_dialog_content = "From what I know, you already made a name for yourself in the world of wondrous beast training.",
  ui_story_5036_50360401_147_dialog_content = "Who says extrozoologists can't be idols?",
  ui_story_5036_50360401_148_dialog_content = "Only I get to decide that!",
  ui_story_5036_50360401_149_dialog_content = "In this day and age, anyone can be an idol...",
  ui_story_5036_50360401_150_dialog_content = "and enjoy their 15 minutes of fame in the spotlight.",
  ui_story_5036_50360401_151_dialog_content = "\"In this day and age, anyone can be an idol,\" you say?",
  ui_story_5036_50360401_152_dialog_content = "Very well put!",
  ui_story_5036_50360401_153_dialog_content = "I appreciate your attitude and understanding about this business. I look forward to your act!",
  ui_story_5036_50360401_154_dialog_content = "Wow, this is the first contestant thus far to capture the attention of Miss Goldie herself!",
  ui_story_5036_50360401_155_dialog_content = "So what exciting performance will he bring us?",
  ui_story_5036_50360401_156_dialog_content = "Please begin, Vic!",
  ui_story_5036_50360401_157_dialog_content = "I shall recite something for you all. Ahem...",
  ui_story_5036_50360401_158_dialog_content = "Ah! Spring has come hither, and the earth comes alive once more!",
  ui_story_5036_50360401_159_dialog_content = "It is once again the season during which the wondrous beasts display their vigor.",
  ui_story_5036_50360401_160_dialog_content = "(I-I'm not even sure this qualifies as a performance...)",
  ui_story_5036_50360401_161_dialog_content = "(But it sounds like Vic is reciting his Encyclopedia Exotica?!)",
  ui_story_5036_50360401_162_dialog_content = "Alas! The gloriousness of life fills every inch of the land, be it the forests or the plains!",
  ui_story_5036_50360401_163_dialog_content = "But amidst this cacophony, there is one creature that is the exception.",
  ui_story_5036_50360401_164_dialog_content = "The <color=#FFB400>Ouroboros</color> is one of the <color=#FFB400> longest-living </color> wondrous beasts in Astra.",
  ui_story_5036_50360401_165_dialog_content = "When they reach maturity—",
  ui_story_5036_50360401_166_dialog_content = "Sorry, let me interrupt you for a second!",
  ui_story_5036_50360401_167_dialog_content = "The judges are wondering if you have anything else to show us?",
  ui_story_5036_50360401_168_dialog_content = "Well, no... I only prepared this dramatic narration for today.",
  ui_story_5036_50360401_169_dialog_content = "I see... What a pity.",
  ui_story_5036_50360401_170_dialog_content = "You did well in your recitation, but it's not quite what we're looking for.",
  ui_story_5036_50360401_171_dialog_content = "But don't be down on yourself!",
  ui_story_5036_50360401_172_dialog_content = "You do have a very good voice, and very nice visuals too.",
  ui_story_5036_50360401_173_dialog_content = "I'm sure you'll do well switching to singing or dancing.",
  ui_story_5036_50360401_174_dialog_content = "It wouldn't surprise me if you one day surpass even some of the experienced entertainers.",
  ui_story_5036_50360401_175_dialog_content = "I hope to see a different from you in a later round.",
  ui_story_5036_50360401_176_dialog_content = "I think you have great potential, so keep striving!",
  ui_story_5036_50360401_177_dialog_content = "Ah, I guess I'll try again.",
  ui_story_5036_50360401_178_dialog_content = "(Goldie's looking at Vic as if she just discovered a hidden gem...)",
  ui_story_5036_50360401_179_dialog_content = "(Does Vic really have what it takes to be an idol?)",
  ui_story_5036_50360401_180_dialog_content = "Thank you to all our candidates and judges! Today's auditions have come to an end.",
  ui_story_5036_50360401_181_dialog_content = "Make sure you tune in to future rounds of auditioning!",
  ui_story_5036_50360401_182_dialog_content = "We'll see you tomorrow!",
  ui_story_5036_50360401_183_dialog_content = "PlayerName, Goldie, is it over?",
  ui_story_5036_50360401_184_dialog_content = "Yeah. I thought it would be relaxing to watch the performances, but it actually took a lot out of me.",
  ui_story_5036_50360401_185_dialog_content = "By the way, how come you guys didn't show up?",
  ui_story_5036_50360401_186_dialog_content = "We wanted to rehearse some more before joining.",
  ui_story_5036_50360401_187_dialog_content = "You're rehearsing together?",
  ui_story_5036_50360401_188_dialog_content = "Yeah. We thought it would be more fun to enter as a duo.",
  ui_story_5036_50360401_189_dialog_content = "Don't look so shocked. You heard that correctly.",
  ui_story_5036_50360401_190_dialog_content = "Vice and I are going to be performing as a duo.",
  ui_story_5036_50360401_191_dialog_content = "That's a great idea!",
  ui_story_5036_50360401_192_dialog_content = "Do you have any idea what you're going to do yet?",
  ui_story_5036_50360401_193_dialog_content = "We'll be singing. We've got a few songs picked out already.",
  ui_story_5036_50360401_194_dialog_content = "But we have to rehearse before deciding which one to go with.",
  ui_story_5036_50360401_195_dialog_content = "Honestly, I don't know if we can make it...",
  ui_story_5036_50360401_196_dialog_content = "Don't worry. Let me tell you a secret.",
  ui_story_5036_50360401_197_dialog_content = "I actually haven't decided on what songs to sing yet either.",
  ui_story_5036_50360401_198_dialog_content = "You must have a big selection of your own songs to choose from, right?",
  ui_story_5036_50360401_199_dialog_content = "Yes, but I don't feel like there's one suitable for a stage on Eulogoz.",
  ui_story_5036_50360401_200_dialog_content = "It's okay, though. Maybe I'll figure it out in the next couple of days.",
  ui_story_5036_50360401_201_dialog_content = "You mean you're writing a new song just for Eulogoz?",
  ui_story_5036_50360401_202_dialog_content = "Shh, not so loud! But yeah, that's the idea.",
  ui_story_5036_50360401_203_dialog_content = "I'm not sure if I can do it, so please keep it a secret.",
  ui_story_5036_50360401_204_dialog_content = "Do you write all of your songs?",
  ui_story_5036_50360401_205_dialog_content = "That's impressive!",
  ui_story_5036_50360401_206_dialog_content = "Not all of them, no.",
  ui_story_5036_50360401_207_dialog_content = "It's just that a melody or beat pops into my mind occasionally.",
  ui_story_5036_50360401_208_dialog_content = "Then I try to write it down and make it into a song.",
  ui_story_5036_50360401_209_dialog_content = "But it's not all the time that I get the melody I want.",
  ui_story_5036_50360401_210_dialog_content = "A melody that pops into your mind...?",
  ui_story_5036_50360401_211_dialog_content = "♪ Oo-oo-oo-oo... ♪",
  ui_story_5036_50360401_212_dialog_content = "♪ La la la la... ♪",
  ui_story_5036_50360401_213_dialog_content = "So uh, ever since I got within close proximity to Eulogoz, I've been hearing tunes in my head.",
  ui_story_5036_50360401_214_dialog_content = "I'd even say it's not a melody as much as someone actually humming.",
  ui_story_5036_50360401_215_dialog_content = "Really?",
  ui_story_5036_50360401_216_dialog_content = "I heard that Caelestites were a music-loving race.",
  ui_story_5036_50360401_217_dialog_content = "Maybe you have a natural affinity for making music!",
  ui_story_5036_50360401_218_dialog_content = "Y-You think?",
  ui_story_5036_50360401_219_dialog_content = "Could Eugoloz be sending me inspiration?",
  ui_story_5036_50360401_220_dialog_content = "That's possible!",
  ui_story_5036_50360401_221_dialog_content = "It makes sense.",
  ui_story_5036_50360401_222_dialog_content = "Eulogoz belonged to the Caelestites.",
  ui_story_5036_50360401_223_dialog_content = "If I could sing a song composed by a Caelestite on Eulogoz, that would be very meaningful!",
  ui_story_5036_50360401_224_dialog_content = "PlayerName!",
  ui_story_5036_50360401_225_dialog_content = "If you don't mind, can you share the melody that's been popping up in your head?",
  ui_story_5036_50360401_226_dialog_content = "Of course I don't mind.",
  ui_story_5036_50360401_227_dialog_content = "Halt—!",
  ui_story_5036_50360401_228_dialog_content = "What's going on?",
  ui_story_5036_50360401_229_dialog_content = "Grah!",
  ui_story_5036_50360401_230_dialog_content = "Looks like we'll have to wait on that, PlayerName!",
  ui_story_5036_50360402_1_dialog_content = "So sorry to disturb you!",
  ui_story_5036_50360402_2_dialog_content = "A guard collapsed in the lockdown area while cleansing the Eclipsites, which let them out.",
  ui_story_5036_50360402_3_dialog_content = "Thankfully, the soldiers from Illumina and Lumopolis helped us out.",
  ui_story_5036_50360402_4_dialog_content = "What about the guard? Is he hurt?",
  ui_story_5036_50360402_5_dialog_content = "He's conscious and should be fine.",
  ui_story_5036_50360402_6_dialog_content = "Was it because dealing with the Eclipsites in the lockdown area was too taxing?",
  ui_story_5036_50360402_7_dialog_content = "We followed your advice and gave everyone plenty of rest, so things aren't too bad.",
  ui_story_5036_50360402_8_dialog_content = "He said he fainted because he didn't have anything to eat.",
  ui_story_5036_50360402_9_dialog_content = "Didn't we provide enough meals?",
  ui_story_5036_50360402_10_dialog_content = "Well, someone stole his portion, and he didn't have the time to get a replacement.",
  ui_story_5036_50360402_11_dialog_content = "Someone stole his food?",
  ui_story_5036_50360402_12_dialog_content = "No way, don't tell me they got me too!",
  ui_story_5036_50360402_13_dialog_content = "Are you hurt, soldier?",
  ui_story_5036_50360402_14_dialog_content = "I'm fine, Lieutenant Vice!",
  ui_story_5036_50360402_15_dialog_content = "It's just that the rations I had with me appear to be missing.",
  ui_story_5036_50360402_16_dialog_content = "You too?",
  ui_story_5036_50360402_17_dialog_content = "Yes. The guys around me all had the same thing happen to them.",
  ui_story_5036_50360402_18_dialog_content = "Our rations keep disappearing mysteriously.",
  ui_story_5036_50360402_19_dialog_content = "I thought carrying my rations on me would be safe, yet...",
  ui_story_5036_50360402_20_dialog_content = "Perhaps you guys lost them while fighting the Eclipsites?",
  ui_story_5036_50360402_21_dialog_content = "That's what we thought too, so we didn't report it.",
  ui_story_5036_50360402_22_dialog_content = "The <color=#FFB400>ghost thief</color>... It must be the ghost thief!",
  ui_story_5036_50360402_23_dialog_content = "Ghost thief?",
  ui_story_5036_50360402_24_dialog_content = "There's a ghost thief on the Colossus, Lady Carleen!",
  ui_story_5036_50360402_25_dialog_content = "The thief knocks you out when you least expect it.",
  ui_story_5036_50360402_26_dialog_content = "Then it takes all your valuables without being seen!",
  ui_story_5036_50360402_27_dialog_content = "That's how I lost my gemstone pocket watch.",
  ui_story_5036_50360402_28_dialog_content = "Stealing food and jewelry?",
  ui_story_5036_50360402_29_dialog_content = "That doesn't sound like something the Eclipsites would do.",
  ui_story_5036_50360402_30_dialog_content = "So we have a thief on our hands...",
  ui_story_5036_50360402_31_dialog_content = "You know, somehow, this sounds familiar.",
  ui_story_5036_50360402_32_dialog_content = "Where have I seen a similar situation before...",
  ui_story_5036_50360402_33_dialog_content = "Could a professional pickpocket have gotten on board the Wandering Colossus?",
  ui_story_5036_50360402_34_dialog_content = "The mercenaries have noticed this problem as well, Miss Goldie.",
  ui_story_5036_50360402_35_dialog_content = "Not just us, but even those who signed up for the audition griped about losing candy and drinks.",
  ui_story_5036_50360402_36_dialog_content = "Curses, why do criminals have to show up all the way up in the sky?!",
  ui_story_5036_50360402_37_dialog_content = "I'm worried that the thief will upset the audition candidates, Goldie.",
  ui_story_5036_50360402_38_dialog_content = "Carleen's right. The most pressing issue is to make sure the thief doesn't cause them to lose faith in those hosting the concert.",
  ui_story_5036_50360402_39_dialog_content = "Would you mind sending someone to buy another shipment of food and drink from Umbraton?",
  ui_story_5036_50360402_40_dialog_content = "We have to ensure all the contestants and soldiers on Eulogoz are fed.",
  ui_story_5036_50360402_41_dialog_content = "Considering the volume involved, I'll have to send more people.",
  ui_story_5036_50360402_42_dialog_content = "Please do, and include the cost in the bill.",
  ui_story_5036_50360402_43_dialog_content = "Got it!",
  ui_story_5036_50360402_44_dialog_content = "...",
  ui_story_5036_50360402_45_dialog_content = "Are you okay, Goldie?",
  ui_story_5036_50360402_46_dialog_content = "...",
  ui_story_5036_50360402_47_dialog_content = "Goldie?",
  ui_story_5036_50360402_48_dialog_content = "Hm? Huh... Yeah, I'm good, don't worry about me!",
  ui_story_5036_50360402_49_dialog_content = "Focus on your rehearsal and don't worry about this, Carleen, Vice.",
  ui_story_5036_50360402_50_dialog_content = "I'll absolutely...",
  ui_story_5036_50360402_51_dialog_content = "I'll absolutely not let anyone stop the concert from happening!",
  ui_story_5036_50360501_1_dialog_content = "Mercenaries...",
  ui_story_5036_50360501_2_dialog_content = "What did you do?!",
  ui_story_5036_50360501_3_dialog_content = "What a marvelous stage you've built!",
  ui_story_5036_50360501_4_dialog_content = "You completely cleaned Eugoloz's screen, and equipped it with multi-colored lighting!",
  ui_story_5036_50360501_5_dialog_content = "Believe me when I say this...",
  ui_story_5036_50360501_6_dialog_content = "This stage is more breathtaking than any I've ever seen in Umbraton!",
  ui_story_5036_50360501_7_dialog_content = "Thank you for the compliment, Miss Goldie.",
  ui_story_5036_50360501_8_dialog_content = "We just followed Ms. Sheol's instructions.",
  ui_story_5036_50360501_9_dialog_content = "No, you guys are different.",
  ui_story_5036_50360501_10_dialog_content = "Lady Sheol says most mercenaries do shoddy, careless work.",
  ui_story_5036_50360501_11_dialog_content = "Only the White Flames can be relied on to always be meticulous and dependable.",
  ui_story_5036_50360501_12_dialog_content = "It's a shame, though...",
  ui_story_5036_50360501_13_dialog_content = "that such a stunning venue will only be performed at once.",
  ui_story_5036_50360501_14_dialog_content = "If you would like, Miss Goldie...",
  ui_story_5036_50360501_15_dialog_content = "We can build the same stage for you later in Umbraton.",
  ui_story_5036_50360501_16_dialog_content = "Later?",
  ui_story_5036_50360501_17_dialog_content = "Assuming I'm still an idol by then...",
  ui_story_5036_50360501_18_dialog_content = "Huh?",
  ui_story_5036_50360501_19_dialog_content = "Never mind. Any news on the thief?",
  ui_story_5036_50360501_20_dialog_content = "None so far.",
  ui_story_5036_50360501_21_dialog_content = "The culprit's pretty cunning. We have no solid leads yet.",
  ui_story_5036_50360501_22_dialog_content = "All we know is that most things were stolen at nighttime.",
  ui_story_5036_50360501_23_dialog_content = "That's a start.",
  ui_story_5036_50360501_24_dialog_content = "I'll be patrolling with you at night.",
  ui_story_5036_50360501_25_dialog_content = "You'll patrol with us?",
  ui_story_5036_50360501_26_dialog_content = "Haha, you're the first person to reject the company of a famous idol.",
  ui_story_5036_50360501_27_dialog_content = "I wouldn't dare! I'm just concerned it would take time away from your songwriting.",
  ui_story_5036_50360501_28_dialog_content = "Oh, never underestimate what an idol can do!",
  ui_story_5036_50360501_29_dialog_content = "I have a lot of songs I can sing on stage.",
  ui_story_5036_50360501_30_dialog_content = "I'd love to write a new song to the Caelestite's melody...",
  ui_story_5036_50360501_31_dialog_content = "but PlayerName only gave me a few notes. I don't know where I can take that.",
  ui_story_5036_50360501_32_dialog_content = "Just a few notes?",
  ui_story_5036_50360501_33_dialog_content = "Are you curious?",
  ui_story_5036_50360501_34_dialog_content = "U-Uh, I wouldn't dare intrude...",
  ui_story_5036_50360501_35_dialog_content = "No? But I have the urge to sing it on this new stage.",
  ui_story_5036_50360501_36_dialog_content = "♪ La... ♪",
  ui_story_5036_50360501_37_dialog_content = "♪ La... La la la... ♪",
  ui_story_5036_50360501_38_dialog_content = "Grahhhhhh!",
  ui_story_5036_50360501_39_dialog_content = "The escaped Eclipsites... They're hiding under the stage!",
  ui_story_5036_50360501_40_dialog_content = "They came out as soon as Miss Goldie started singing...",
  ui_story_5036_50360501_41_dialog_content = "Don't tell me they're Goldilocks too?!",
  ui_story_5036_50360502_1_dialog_content = "I hear the stage will be completed tonight.",
  ui_story_5036_50360502_2_dialog_content = "I need to beat everyone there to get the shots from all angles!",
  ui_story_5036_50360502_3_dialog_content = "What I want is inside scoop that's hot enough to lure in views!",
  ui_story_5036_50360502_4_dialog_content = "Seriously, could the editor have made a more difficult demand?",
  ui_story_5036_50360502_5_dialog_content = "Where am I supposed to get inside scoop?",
  ui_story_5036_50360502_6_dialog_content = "The only thing I can do is be the first to report any news on Eulogoz.",
  ui_story_5036_50360502_7_dialog_content = "Hey, there's someone on the stage...",
  ui_story_5036_50360502_8_dialog_content = "If only the Eclipsites could become Goldilocks...",
  ui_story_5036_50360502_9_dialog_content = "You're into Eclipsites?",
  ui_story_5036_50360502_10_dialog_content = "Are you kidding me?!",
  ui_story_5036_50360502_11_dialog_content = "S-Sorry!",
  ui_story_5036_50360502_12_dialog_content = "Well, it was my fault for not clarifying.",
  ui_story_5036_50360502_13_dialog_content = "I was just thinking, it'd be great if the Eclipsites could understand my songs.",
  ui_story_5036_50360502_14_dialog_content = "If they could hear the love and peace in them, maybe that would influence them",
  ui_story_5036_50360502_15_dialog_content = "to stop their savage, murderous behavior.",
  ui_story_5036_50360502_16_dialog_content = "Heh... Did that come off pompous or what?",
  ui_story_5036_50360502_17_dialog_content = "Influence, savage, ... murderous?",
  ui_story_5036_50360502_18_dialog_content = "What's Goldie saying? It's hard to tell from this far away.",
  ui_story_5036_50360502_19_dialog_content = "Guess I have to get a little closer...",
  ui_story_5036_50360502_20_dialog_content = "<color=#e8d9bb>Bonk!</color>",
  ui_story_5036_50360502_21_dialog_content = "Oh come on! How could I be this unlucky?",
  ui_story_5036_50360502_22_dialog_content = "Of course I had to run into a wooden crate right at this moment!",
  ui_story_5036_50360502_23_dialog_content = "Did they hear me?",
  ui_story_5036_50360502_24_dialog_content = "Phew, guess they didn't.",
  ui_story_5036_50360502_25_dialog_content = "Who's there?",
  ui_story_5036_50360502_26_dialog_content = "Huh?",
  ui_story_5036_50360502_27_dialog_content = "Oops, I'm caught!",
  ui_story_5036_50360502_28_dialog_content = "It's okay. I'll just explain that I was just passing by. Miss Goldie would surely...",
  ui_story_5036_50360502_29_dialog_content = "believe me, right?",
  ui_story_5036_50360502_30_dialog_content = "<color=#e8d9bb>*Crash*</color>",
  ui_story_5036_50360502_31_dialog_content = "Stop right there!",
  ui_story_5036_50360502_32_dialog_content = "What? What the...?",
  ui_story_5036_50360502_33_dialog_content = "Goldie seems to be shouting in another direction?",
  ui_story_5036_50360502_34_dialog_content = "Is there someone else other than me hiding here?",
  ui_story_5036_50360502_35_dialog_content = "You're even more perceptive than our scout, Miss Goldie!",
  ui_story_5036_50360502_36_dialog_content = "I didn't think someone would be hiding beneath the floorboard.",
  ui_story_5036_50360502_37_dialog_content = "Too bad the perp ran off before I could lift it.",
  ui_story_5036_50360502_38_dialog_content = "Look, half-eaten rations.",
  ui_story_5036_50360502_39_dialog_content = "It's Illumina packaging.",
  ui_story_5036_50360502_40_dialog_content = "Illumina rations?",
  ui_story_5036_50360502_41_dialog_content = "But none of Illumina's soldiers were assigned to work near the stage.",
  ui_story_5036_50360502_42_dialog_content = "Yes. The guys around me all had the same thing happen to them.",
  ui_story_5036_50360502_43_dialog_content = "Our rations keep disappearing mysteriously.",
  ui_story_5036_50360502_44_dialog_content = "Could it be...",
  ui_story_5036_50360502_45_dialog_content = "<color=#e8d9bb>Whoosh—</color>",
  ui_story_5036_50360502_46_dialog_content = "Was that a rat?",
  ui_story_5036_50360502_47_dialog_content = "No! Not a rat.",
  ui_story_5036_50360502_48_dialog_content = "You see that thing running away, Marshmallow?",
  ui_story_5036_50360502_49_dialog_content = "Go after it!",
  ui_story_5036_50360502_50_dialog_content = "Woof, woof!",
  ui_story_5036_50360502_51_dialog_content = "Hai?",
  ui_story_5036_50360502_52_dialog_content = "Hai hai!",
  ui_story_5036_50360502_53_dialog_content = "Don't capture it, Marshmallow. Just follow it closely for now.",
  ui_story_5036_50360502_54_dialog_content = "Maybe it will lead us to <color=#FFB400>bigger fish</color>.",
  ui_story_5036_50360502_55_dialog_content = "Hai—!",
  ui_story_5036_50360502_56_dialog_content = "Huh? Sigh...",
  ui_story_5036_50360502_57_dialog_content = "You totally ignored me just a minute ago, Bica...",
  ui_story_5036_50360502_58_dialog_content = "Now you want to cuddle?",
  ui_story_5036_50360502_59_dialog_content = "Woof!",
  ui_story_5036_50360502_60_dialog_content = "Ahem. Say, shouldn't you keep a leash on that chubby dog of yours?",
  ui_story_5036_50360502_61_dialog_content = "My Bica is very sensitive and gets nervous easily, which then upsets its stomach—",
  ui_story_5036_50360502_62_dialog_content = "You're the Ghost Thief?",
  ui_story_5036_50360502_63_dialog_content = "Ghost? No way.",
  ui_story_5036_50360502_64_dialog_content = "Don't believe me? I'll bite myself to prove it. Ow!",
  ui_story_5036_50360502_65_dialog_content = "Man, that really hurt!",
  ui_story_5036_50360502_66_dialog_content = "See, I'm as living can be. I feel pain. Ghosts don't.",
  ui_story_5036_50360502_67_dialog_content = "(It's a chore talking to this guy.)",
  ui_story_5036_50360502_68_dialog_content = "(But why does he sound familiar?)",
  ui_story_5036_50360502_69_dialog_content = "I don't care if you're the ghost or not, but I will not tolerate anyone trying to ruin my concert!",
  ui_story_5036_50360502_70_dialog_content = "You better start explaining yourself!",
  ui_story_5036_50360502_71_dialog_content = "<color=#e8d9bb>Ding!</color>",
  ui_story_5036_50360502_72_dialog_content = "This thing in my hand isn't just ornamental!",
  ui_story_5036_50360502_73_dialog_content = "Okay, okay...",
  ui_story_5036_50360502_74_dialog_content = "Take it easy! I'm almost tripped over myself because of your threats.",
  ui_story_5036_50360502_75_dialog_content = "Your outfit looks lumpy. What are you hiding under there?",
  ui_story_5036_50360502_76_dialog_content = "Just a precious baby I just tamed. It's resting right now.",
  ui_story_5036_50360502_77_dialog_content = "Why don't I believe that one bit?",
  ui_story_5036_50360502_78_dialog_content = "Sigh. I can only say you lack understanding then.",
  ui_story_5036_50360502_79_dialog_content = "Read more books, browse more newspapers, do more charity work... That's all the advice I can give you.",
  ui_story_5036_50360502_80_dialog_content = "If there's nothing else, I'll take my leave now.",
  ui_story_5036_50360502_81_dialog_content = "Take your clothes off!",
  ui_story_5036_50360502_82_dialog_content = "Hah?! It might be dark, and you can't see anything...",
  ui_story_5036_50360502_83_dialog_content = "but I still have my modesty to protect!",
  ui_story_5036_50360502_84_dialog_content = "Get him, Marshmallow!",
  ui_story_5036_50360502_85_dialog_content = "Woof!",
  ui_story_5036_50360502_86_dialog_content = "Watch it...!",
  ui_story_5036_50360502_87_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5036_50360502_88_dialog_content = "I-I fell anyway...",
  ui_story_5036_50360502_89_dialog_content = "Hey, wasn't he one of the performers in the audition?",
  ui_story_5036_50360502_90_dialog_content = "So that's the pretense you used to sneak on board.",
  ui_story_5036_50360502_91_dialog_content = "Ouch, ouch, ouch...",
  ui_story_5036_50360502_92_dialog_content = "Him?!",
  ui_story_5036_50360502_93_dialog_content = "Hoot hoot!",
  ui_story_5036_50360502_94_dialog_content = "What the...? Did an owl just stumble out of his arms?",
  ui_story_5036_50360502_95_dialog_content = "It wasn't stolen goods? Was I being too paranoid?",
  ui_story_5036_50360502_96_dialog_content = "I told you I was innocent.",
  ui_story_5036_50360502_97_dialog_content = "<color=#e8d9bb>*Splash* Clang, clang...</color>",
  ui_story_5036_50360502_98_dialog_content = "A lot of jewelry just fell out from within the owl's feathers.",
  ui_story_5036_50360502_99_dialog_content = "See, I told you I wasn't a thief.",
  ui_story_5036_50360502_100_dialog_content = "Oh, Lutumi, you could've been anything! Why would you be a thief?",
  ui_story_5036_50360502_101_dialog_content = "Hoot...",
  ui_story_5036_50360502_102_dialog_content = "How are you still denying it? The evidence is literally scattered all around us!",
  ui_story_5036_50360502_103_dialog_content = "Relax!",
  ui_story_5036_50360502_104_dialog_content = "I'll show you no mercy!",
  ui_story_5036_50360502_105_dialog_content = "Ugh...",
  ui_story_5036_50360502_106_dialog_content = "Miss Goldie?!",
  ui_story_5036_50360502_107_dialog_content = "Don't worry, he's just temporarily knocked out.",
  ui_story_5036_50360502_108_dialog_content = "He's got a silver tongue, and neither of us has the time nor energy to deal with it now.",
  ui_story_5036_50360502_109_dialog_content = "Please take him into custody and interrogate him when you're done with the task at hand.",
  ui_story_5036_50360502_110_dialog_content = "<color=#e8d9bb>Click!</color>",
  ui_story_5036_50360502_111_dialog_content = "So...",
  ui_story_5036_50360502_112_dialog_content = "The rumor about Goldie's mean streak was true?",
  ui_story_5036_50360502_113_dialog_content = "With this picture, I'll be able to...",
  ui_story_5036_50360601_1_dialog_content = "What now?",
  ui_story_5036_50360601_2_dialog_content = "I got it! Inside scoop that will guarantee views!",
  ui_story_5036_50360601_3_dialog_content = "You better not be wasting my time.",
  ui_story_5036_50360601_4_dialog_content = "I promise you'll be happy with what I've got!",
  ui_story_5036_50360601_5_dialog_content = "Remember when you received a tip about Goldie having a mean streak?",
  ui_story_5036_50360601_6_dialog_content = "(Where am I?)",
  ui_story_5036_50360601_7_dialog_content = "(When did I get back to Eraveil? Last I remember, I was...)",
  ui_story_5036_50360601_8_dialog_content = "(Where was I again?)",
  ui_story_5036_50360601_9_dialog_content = "♪ La... La la la... ♪",
  ui_story_5036_50360601_10_dialog_content = "(I know that tune!)",
  ui_story_5036_50360601_11_dialog_content = "♪ Oo-oo-oo-oo... ♪",
  ui_story_5036_50360601_12_dialog_content = "(Who's humming?)",
  ui_story_5036_50360601_13_dialog_content = "<color=#e8d9bb>Whoosh!</color>",
  ui_story_5036_50360601_14_dialog_content = "(What just flew by, a Colossus?)",
  ui_story_5036_50360601_15_dialog_content = "(I should find out.)",
  ui_story_5036_50360601_16_dialog_content = "♪ La la la la... ♪",
  ui_story_5036_50360601_17_dialog_content = "♪ Oo-oo-oo-oo... ♪",
  ui_story_5036_50360601_18_dialog_content = "♪ La... La la... ♪",
  ui_story_5036_50360601_19_dialog_content = "(The girl over there, she's the one that's been singing.)",
  ui_story_5036_50360601_20_dialog_content = "There you are.",
  ui_story_5036_50360601_21_dialog_content = "(Is she talking to me?)",
  ui_story_5036_50360601_22_dialog_content = "Kree, kree!",
  ui_story_5036_50360601_23_dialog_content = "(Oh, she's talking to a creature that looks like a Colossus.)",
  ui_story_5036_50360601_24_dialog_content = "Here to listen to me sing? You're such a loyal fan!",
  ui_story_5036_50360601_25_dialog_content = "But I think it's time to put words into the music.",
  ui_story_5036_50360601_26_dialog_content = "(The way she's dressed and acting... She's definitely a Caelestite.)",
  ui_story_5036_50360601_27_dialog_content = "(I knew I'd find other Caelestites!)",
  ui_story_5036_50360601_28_dialog_content = "Hmm, I'm a bit thirsty.",
  ui_story_5036_50360601_29_dialog_content = "Let's go pick some wild fruit!",
  ui_story_5036_50360601_30_dialog_content = "Kree, kree!",
  ui_story_5036_50360601_31_dialog_content = "Hey, little girl!",
  ui_story_5036_50360601_32_dialog_content = "Wait up!",
  ui_story_5036_50360601_33_dialog_content = "Huh?",
  ui_story_5036_50360601_34_dialog_content = "<color=#e8d9bb>Knock, knock!</color>",
  ui_story_5036_50360601_35_dialog_content = "Little girl!",
  ui_story_5036_50360601_36_dialog_content = "Huh?",
  ui_story_5036_50360601_37_dialog_content = "Oh, it was just a dream...",
  ui_story_5036_50360601_38_dialog_content = "<color=#e8d9bb>Four days until the concert</color>",
  ui_story_5036_50360601_39_dialog_content = "<color=#e8d9bb>Pound, pound, pound!</color>",
  ui_story_5036_50360601_40_dialog_content = "Are you okay in there, PlayerName?",
  ui_story_5036_50360601_41_dialog_content = "Coming!",
  ui_story_5036_50360601_42_dialog_content = "You were dead asleep!",
  ui_story_5036_50360601_43_dialog_content = "Didn't you hear us pounding on the door?",
  ui_story_5036_50360601_44_dialog_content = "We were beginning to think Eclipsites had slipped into your room...",
  ui_story_5036_50360601_45_dialog_content = "Vice and I were this close to breaking the door down.",
  ui_story_5036_50360601_46_dialog_content = "Sorry, I just had this dream. It felt like I was still in it.",
  ui_story_5036_50360601_47_dialog_content = "Ah, another dream.",
  ui_story_5036_50360601_48_dialog_content = "Another?",
  ui_story_5036_50360601_49_dialog_content = "Yeah. Did you forget, Carleen?",
  ui_story_5036_50360601_50_dialog_content = "PlayerName gets weird dreams pretty often.",
  ui_story_5036_50360601_51_dialog_content = "I suddenly remembered that I also had a weird dream this morning.",
  ui_story_5036_50360601_52_dialog_content = "I think I dreamed of Eraveil.",
  ui_story_5036_50360601_53_dialog_content = "Except the person living there wasn't PlayerName, but a little girl I had never seen before.",
  ui_story_5036_50360601_54_dialog_content = "Me too! I had the same dream!",
  ui_story_5036_50360601_55_dialog_content = "Wow, we really have great chemistry these days.",
  ui_story_5036_50360601_56_dialog_content = "It must be all those rehearsals!",
  ui_story_5036_50360601_57_dialog_content = "But I dreamed the same thing.",
  ui_story_5036_50360601_58_dialog_content = "What?",
  ui_story_5036_50360601_59_dialog_content = "I saw a little girl singing in Eraveil.",
  ui_story_5036_50360601_60_dialog_content = "Her song was the tune that's been stuck in my head!",
  ui_story_5036_50360601_61_dialog_content = "The girl in my dream didn't sing. She was just tidying her home.",
  ui_story_5036_50360601_62_dialog_content = "The girl I dreamed about was reading in a room.",
  ui_story_5036_50360601_63_dialog_content = "So our dreams were all slightly different.",
  ui_story_5036_50360601_64_dialog_content = "I heard when several people experience the same thing, there's a chance they end up having similar dreams.",
  ui_story_5036_50360601_65_dialog_content = "Because of their shared experience, their subconscious gravitates toward the same thoughts, thus resulting in similar dreams.",
  ui_story_5036_50360601_66_dialog_content = "One dreams at night what one ponders during the day, as the saying goes.",
  ui_story_5036_50360601_67_dialog_content = "But our different personalities are reflected in the details in an identical dream.",
  ui_story_5036_50360601_68_dialog_content = "Is that all there is to it? I got excited over nothing.",
  ui_story_5036_50360601_69_dialog_content = "By the way, PlayerName, are you sure you wanna keep chatting with us?",
  ui_story_5036_50360601_70_dialog_content = "You need to be present at the second round of auditions today, no?",
  ui_story_5036_50360601_71_dialog_content = "Oops!! I totally forgot!",
  ui_story_5036_50360601_72_dialog_content = "♪ Oo-oo-oo-oo... ♪",
  ui_story_5036_50360601_73_dialog_content = "♪ La... La la... ♪",
  ui_story_5036_50360601_74_dialog_content = "That's the entirety of the melody in my head. Feels good to get it all out!",
  ui_story_5036_50360601_75_dialog_content = "*Yawns*",
  ui_story_5036_50360601_76_dialog_content = "W-Was I totally off tune or something?",
  ui_story_5036_50360601_77_dialog_content = "No. I didn't sleep well last night, so pardon me, PlayerName.",
  ui_story_5036_50360601_78_dialog_content = "Is it because you had one too many dreams?",
  ui_story_5036_50360601_79_dialog_content = "You've got quite the imagination, PlayerName.",
  ui_story_5036_50360601_80_dialog_content = "I checked the stage last night.",
  ui_story_5036_50360601_81_dialog_content = "And went to the lockdown area to take care of Eclipsites until the wee hours.",
  ui_story_5036_50360601_82_dialog_content = "Aren't the White Flame Mercenaries in charge of that?",
  ui_story_5036_50360601_83_dialog_content = "Yeah, but I couldn't stand being cooped up in my room.",
  ui_story_5036_50360601_84_dialog_content = "I figured that rather than worry about it, I might as well help out.",
  ui_story_5036_50360601_85_dialog_content = "No wonder you're the most popular idol in Umbraton. You work way too hard.",
  ui_story_5036_50360601_86_dialog_content = "You get involved in everything!",
  ui_story_5036_50360601_87_dialog_content = "Any small thing can make or break the concert.",
  ui_story_5036_50360601_88_dialog_content = "The show is of utmost importance to me. I can't let anything derail it.",
  ui_story_5036_50360601_89_dialog_content = "You seem to be the type that treats every performance like it'll be your last.",
  ui_story_5036_50360601_90_dialog_content = "R-Really? Ahaha...",
  ui_story_5036_50360601_91_dialog_content = "But we digress. How should I describe the melody you just shared with me?",
  ui_story_5036_50360601_92_dialog_content = "Gentle, soothing, therapeutic, uniquely Caelestite, and easy to sing!",
  ui_story_5036_50360601_93_dialog_content = "It's exactly the kind of music I'm looking for in all aspects!",
  ui_story_5036_50360601_94_dialog_content = "Are you sure you don't mind me performing it onstage?",
  ui_story_5036_50360601_95_dialog_content = "I never thought I'd be a composer, so knock yourself out!",
  ui_story_5036_50360601_96_dialog_content = "Having such a famous idol perform my song would be an honor.",
  ui_story_5036_50360601_97_dialog_content = "Let me know if you have any ideas for the lyrics!",
  ui_story_5036_50360601_98_dialog_content = "Now, there's something else I wanted to talk to you about.",
  ui_story_5036_50360601_99_dialog_content = "Do you remember the final entrant in yesterday's auditions?",
  ui_story_5036_50360601_100_dialog_content = "You mean Vic?",
  ui_story_5036_50360601_101_dialog_content = "Is he a friend of yours?",
  ui_story_5036_50360601_102_dialog_content = "I'm close to his apprentice, so I guess you could say that.",
  ui_story_5036_50360601_103_dialog_content = "But I didn't know he signed up, and I didn't vote for him either.",
  ui_story_5036_50360601_104_dialog_content = "You don't have to worry about favoritism from me!",
  ui_story_5036_50360601_105_dialog_content = "Does he have kleptomaniac tendencies?",
  ui_story_5036_50360601_106_dialog_content = "What? Why do you ask?",
  ui_story_5036_50360601_107_dialog_content = "Well, late last night...",
  ui_story_5036_50360601_108_dialog_content = "Help!",
  ui_story_5036_50360601_109_dialog_content = "Grahhhhhh!",
  ui_story_5036_50360601_110_dialog_content = "Stop running!",
  ui_story_5036_50360601_111_dialog_content = "Eclipsites chasing Vic, mercenaries chasing the Eclipsites? What's going on here?!",
  ui_story_5036_50360602_1_dialog_content = "The other judges are in their seats, Miss Goldie and PlayerName.",
  ui_story_5036_50360602_2_dialog_content = "If you don't mind...",
  ui_story_5036_50360602_3_dialog_content = "Help!",
  ui_story_5036_50360602_4_dialog_content = "You should join us for the second round of auditions.",
  ui_story_5036_50360602_5_dialog_content = "Graagh!!!!",
  ui_story_5036_50360602_6_dialog_content = "Take this!",
  ui_story_5036_50360602_7_dialog_content = "Everyone seems a little preoccupied at the moment...",
  ui_story_5036_50360602_8_dialog_content = "Help!",
  ui_story_5036_50360602_9_dialog_content = "You can stop yelling now. The Eclipsites are down.",
  ui_story_5036_50360602_10_dialog_content = "*Heavy panting*",
  ui_story_5036_50360602_11_dialog_content = "I was yelling so you wouldn't lock me in with them again!",
  ui_story_5036_50360602_12_dialog_content = "Lucky for me, Little Furball's claws were long enough to pry the lock off.",
  ui_story_5036_50360602_13_dialog_content = "Otherwise, I wouldn't even have gotten the chance to call for help!",
  ui_story_5036_50360602_14_dialog_content = "Sorry, we had no intention of putting you in harm's way whatsoever.",
  ui_story_5036_50360602_15_dialog_content = "But when we confined you in that room, there were no Eclipsites there.",
  ui_story_5036_50360602_16_dialog_content = "...",
  ui_story_5036_50360602_17_dialog_content = "They crawled out through the air vents, Miss Goldie.",
  ui_story_5036_50360602_18_dialog_content = "The vent in that room seems to be connected to the lockdown area.",
  ui_story_5036_50360602_19_dialog_content = "But isn't the air vent secured with a cover?",
  ui_story_5036_50360602_20_dialog_content = "Oh, I see.",
  ui_story_5036_50360602_21_dialog_content = "You were trying to escape through the vent, which drew the Eclipsites there!",
  ui_story_5036_50360602_22_dialog_content = "Uh... Hee hee.",
  ui_story_5036_50360602_23_dialog_content = "It was so hot in the room. I really needed some air.",
  ui_story_5036_50360602_24_dialog_content = "What's going on? Why did you lock Vic up?",
  ui_story_5036_50360602_25_dialog_content = "Sorry, PlayerName.",
  ui_story_5036_50360602_26_dialog_content = "But your friend Vic is the ghost thief who's been stealing for the past few days.",
  ui_story_5036_50360602_27_dialog_content = "Vic is the thief?",
  ui_story_5036_50360602_28_option_content = "Well, it's possible.",
  ui_story_5036_50360602_29_dialog_content = "He's a published extrozoologist, but that was many years ago.",
  ui_story_5036_50360602_30_dialog_content = "I could see him resorting to pilfering with no new book under his belt or any reliable income.",
  ui_story_5036_50360602_31_dialog_content = "But no matter how poor you are, you should still make money with your own two hands.",
  ui_story_5036_50360602_32_dialog_content = "You shouldn't put your hands in others' pockets and take their things!",
  ui_story_5036_50360602_33_option_content = "Impossible!",
  ui_story_5036_50360602_34_dialog_content = "He's a published extrozoologist with many students.",
  ui_story_5036_50360602_35_dialog_content = "No matter how poor he is, he wouldn't resort to petty theft!",
  ui_story_5036_50360602_36_dialog_content = "I know it's hard for you to accept.",
  ui_story_5036_50360602_37_dialog_content = "I can't believe it myself. I saw a lot of potential in him.",
  ui_story_5036_50360602_38_dialog_content = "But we discovered stolen food and jewelry in his pockets yesterday. The proof was right there.",
  ui_story_5036_50360602_39_dialog_content = "Listen to me explain...",
  ui_story_5036_50360602_40_dialog_content = "I heard enough of your convoluted excuses yesterday.",
  ui_story_5036_50360602_41_dialog_content = "Are you still trying to deny it with the amount of evidence available?",
  ui_story_5036_50360602_42_dialog_content = "Okay, okay, I confess to all the recent theft.",
  ui_story_5036_50360602_43_dialog_content = "So you really are the ghost thief?!",
  ui_story_5036_50360602_44_dialog_content = "Even though I'm responsible, there's a disclaimer!",
  ui_story_5036_50360602_45_dialog_content = "I, Vic, am a famous extrozoologist, but I have never been a thief.",
  ui_story_5036_50360602_46_dialog_content = "The thief everyone's discussing is actually a wondrous beast I brought with me.",
  ui_story_5036_50360602_47_dialog_content = "Hai...",
  ui_story_5036_50360602_48_dialog_content = "Hoot...",
  ui_story_5036_50360602_49_dialog_content = "Chirp, chirp!",
  ui_story_5036_50360602_50_dialog_content = "The little furry fellow on your shoulder seems to be agitated.",
  ui_story_5036_50360602_51_dialog_content = "Little Furball is saying: \"It was those two, not me!\"",
  ui_story_5036_50360602_52_dialog_content = "Chirp!",
  ui_story_5036_50360602_53_dialog_content = "Usually, I change up their meals every day.",
  ui_story_5036_50360602_54_dialog_content = "But I got too busy packing for myself and only brought one kind of food.",
  ui_story_5036_50360602_55_dialog_content = "These two went off on their own, probably because they were tired of eating the same thing.",
  ui_story_5036_50360602_56_dialog_content = "When I heard about the theft on the Colossus, I thought it might've been them.",
  ui_story_5036_50360602_57_dialog_content = "It took me forever to finally catch them both last night.",
  ui_story_5036_50360602_58_dialog_content = "Just before we caught you?",
  ui_story_5036_50360602_59_dialog_content = "Yeah. What a coincidence, huh?",
  ui_story_5036_50360602_60_dialog_content = "I understand that animals want to eat, but why steal jewelry?",
  ui_story_5036_50360602_61_dialog_content = "Was it the Lutumi Owl?",
  ui_story_5036_50360602_62_dialog_content = "That's right. The Lutumi Owl can emit an anesthetic gas. I brought it with me for self-defense purposes.",
  ui_story_5036_50360602_63_dialog_content = "But it loves to collect shiny objects, so if you lose track of it...",
  ui_story_5036_50360602_64_dialog_content = "It ends up becoming exactly the kind of thief that everyone's been gossiping about.",
  ui_story_5036_50360602_65_dialog_content = "However, they are only acting out of instinct. They harbor no malice toward us.",
  ui_story_5036_50360602_66_dialog_content = "I'm to blame for not keeping them in line.",
  ui_story_5036_50360602_67_dialog_content = "I promise to return all the jewelry and coins back to their owners!",
  ui_story_5036_50360602_68_dialog_content = "If necessary, I'll even pay for the trouble I've caused everyone.",
  ui_story_5036_50360602_69_dialog_content = "Just please don't punish the creatures! They didn't mean it.",
  ui_story_5036_50360602_70_dialog_content = "Hai, hai, hai.",
  ui_story_5036_50360602_71_dialog_content = "...",
  ui_story_5036_50360602_72_dialog_content = "Okay, but you must do what you promised.",
  ui_story_5036_50360602_73_dialog_content = "Return everything with an apology and compensation.",
  ui_story_5036_50360602_74_dialog_content = "So, how about not locking us in a small dark room anymore?",
  ui_story_5036_50360602_75_dialog_content = "It's really stuffy in there...",
  ui_story_5036_50360602_76_dialog_content = "I can do that.",
  ui_story_5036_50360602_77_dialog_content = "But you must promise me that you'll leave Eulogoz after you take care of everything.",
  ui_story_5036_50360602_78_dialog_content = "What? No, I can't leave. I still haven't achieved my dream of being an idol!",
  ui_story_5036_50360602_79_dialog_content = "Didn't you encourage me to keep auditioning yourself, Miss Goldie?",
  ui_story_5036_50360602_80_dialog_content = "You have talent as well as a glib tongue...",
  ui_story_5036_50360602_81_dialog_content = "But I somehow get the feeling that you didn't come here for an idol audition.",
  ui_story_5036_50360602_82_dialog_content = "!!!",
  ui_story_5036_50360602_83_dialog_content = "... All right, I suppose I'll come clean.",
  ui_story_5036_50360602_84_dialog_content = "I'm actually here seeking a wondrous beast called the Ouroboros.",
  ui_story_5036_50360602_85_dialog_content = "When the creature grows to a certain stage, it turns into an egg.",
  ui_story_5036_50360602_86_dialog_content = "It then breaks out after incubation, and the cycle repeats itself, enabling it to achieve immortality.",
  ui_story_5036_50360602_87_dialog_content = "There are immortal creatures in the world?!",
  ui_story_5036_50360602_88_dialog_content = "I've known since I was very young that my father and mother weren't my biological parents.",
  ui_story_5036_50360602_89_dialog_content = "I recently discovered that my bloodline seems connected to the Ouroboros. Therefore, I must find it!",
  ui_story_5036_50360602_89X1_dialog_content = "If I find an Ouroboros, I can find out more about my origins, and maybe I can even find my birth parents.",
  ui_story_5036_50360602_90_dialog_content = "Records on the species are scarce. The only certain thing about them is that they like hanging around Colossi.",
  ui_story_5036_50360602_91_dialog_content = "You're in a drunken stupor again, master! Snap out of it!",
  ui_story_5036_50360602_92_dialog_content = "I already scoured information on all the Colossi in Astra, including PlayerName's Soroz.",
  ui_story_5036_50360602_93_dialog_content = "No signs of any Ouroboros were ever found near any of them.",
  ui_story_5036_50360602_94_dialog_content = "Do the Ouroboros really exist?",
  ui_story_5036_50360602_96_dialog_content = "You're not messing around with me again, are you?!",
  ui_story_5036_50360602_97_dialog_content = "Hmph! Don't make me look for some stupid Ouroboros for you ever again!",
  ui_story_5036_50360602_98_dialog_content = "I combed through all the Colossi in Astra but failed to find any traces of an Ouroboros.",
  ui_story_5036_50360602_99_dialog_content = "The only place I haven't searched yet is this flying Colossus we're on.",
  ui_story_5036_50360602_100_dialog_content = "So have you found any traces of an Ouroboros on Eulogoz?",
  ui_story_5036_50360602_101_dialog_content = "No, but I have a hunch, a very strong hunch.",
  ui_story_5036_50360602_102_dialog_content = "There is definitely an Ouroboros on Eulogoz!",
  ui_story_5036_50360602_103_dialog_content = "Please allow me to stay and look for it!",
  ui_story_5036_50360602_104_dialog_content = "Please give someone who's never before experienced the warm hearth of a loving home, a chance to find his family!",
  ui_story_5036_50360602_105_dialog_content = "... Are you done?",
  ui_story_5036_50360602_106_dialog_content = "Yeah, I'm done.",
  ui_story_5036_50360602_107_dialog_content = "That story of yours is more incredulous than any low-budget film from Umbraton could offer.",
  ui_story_5036_50360602_108_dialog_content = "I should thank you for broadening my horizons.",
  ui_story_5036_50360602_109_dialog_content = "Ehehe, no problem. Thank you for understanding.",
  ui_story_5036_50360602_110_dialog_content = "I should've made it clear to everybody from the start.",
  ui_story_5036_50360602_111_dialog_content = "Alright, story time is over.",
  ui_story_5036_50360602_112_dialog_content = "Now could you please get off Eulogoz?",
  ui_story_5036_50360602_113_dialog_content = "What?",
  ui_story_5036_50360602_114_dialog_content = "This way, please. I'll escort you.",
  ui_story_5036_50360602_115_dialog_content = "Wait a minute! I'm not done yet!",
  ui_story_5036_50360602_116_dialog_content = "Just kidding! I was just joking around, hahaha.",
  ui_story_5036_50360602_116X1_dialog_content = "Adapting and improvising for any situation, livening up the atmosphere, and appealing to fans' emotions—those are all part of an idol's responsibilities.",
  ui_story_5036_50360602_116X2_dialog_content = "I wanted to show you what I was capable of so you know how sincerely I wish to participate in the auditions!",
  ui_story_5036_50360602_117_dialog_content = "You mean like, improv comedy?",
  ui_story_5036_50360602_118_dialog_content = "Didn't my spontaneous story make you laugh?",
  ui_story_5036_50360602_119_dialog_content = "Well...",
  ui_story_5036_50360602_120_dialog_content = "(Indeed, Vic captivated all my attention from the start.)",
  ui_story_5036_50360602_121_dialog_content = "(Lady Sheol did say I was missing something... Could it be the disarming sense of humor that Vic possesses?)",
  ui_story_5036_50360602_124_dialog_content = "I truly want to be an idol... Please let me stay and compete.",
  ui_story_5036_50360602_125_dialog_content = "You might not believe me, but don't you believe PlayerName?",
  ui_story_5036_50360602_126_dialog_content = "He's our VIP, of course I believe him wholeheartedly.",
  ui_story_5036_50360602_127_dialog_content = "There you have it then.",
  ui_story_5036_50360602_128_dialog_content = "Fia helped you out many times before, right, PlayerName?",
  ui_story_5036_50360602_129_dialog_content = "Er... yeah, you could say that.",
  ui_story_5036_50360602_130_dialog_content = "And by association, doesn't that mean I'm technically your benefactor?",
  ui_story_5036_50360602_131_dialog_content = "B-Benefactor?",
  ui_story_5036_50360602_132_dialog_content = "So, as a judge, you will vouch for me, right?",
  ui_story_5036_50360602_133_dialog_content = "...",
  ui_story_5036_50360602_134_dialog_content = "PlayerName vouches for me, Miss Goldie.",
  ui_story_5036_50360602_135_dialog_content = "Please don't kick me out on his behalf...",
  ui_story_5036_50360602_136_dialog_content = "Do you vouch for him, PlayerName?",
  ui_story_5036_50360602_137_dialog_content = "Uh, well...",
  ui_story_5036_50360602_138_dialog_content = "Come close, PlayerName. Listen...",
  ui_story_5036_50360602_139_dialog_content = "Don't tell me you didn't notice the powerful Lumina presence in the lockdown area on Eulogoz!",
  ui_story_5036_50360602_140_dialog_content = "What?!",
  ui_story_5036_50360602_141_dialog_content = "So Goldie was just trying to catch a thief last night...",
  ui_story_5036_50360602_142_dialog_content = "That means my photo was misleading...",
  ui_story_5036_50360602_143_dialog_content = "<color=#e8d9bb>Buzz!</color>",
  ui_story_5036_50360602_144_dialog_content = "When are you sending me the photo you mentioned, Brandy?",
  ui_story_5036_50360602_145_dialog_content = "I need to dig into the situation more!",
  ui_story_5036_50360602_146_dialog_content = "What more digging do you have to do?",
  ui_story_5036_50360602_147_dialog_content = "The truth doesn't matter, only captivating news is good news!",
  ui_story_5036_50360602_148_dialog_content = "But...",
  ui_story_5036_50360602_149_dialog_content = "Don't bother coming back if you don't send the photo!",
  ui_story_5036_50360602_150_dialog_content = "Editor! Editor!",
  ui_story_5036_50360701_1_dialog_content = "Your comments are getting more professional, PlayerName!",
  ui_story_5036_50360701_2_dialog_content = "You might be able to became an actual idol producer one day!",
  ui_story_5036_50360701_3_dialog_content = "Although...",
  ui_story_5036_50360701_4_dialog_content = "Are you still worried about Vic?",
  ui_story_5036_50360701_5_dialog_content = "Yeah, sorry!",
  ui_story_5036_50360701_6_dialog_content = "Even though you vouched for him, I'm still anxious.",
  ui_story_5036_50360701_7_dialog_content = "I put him in a nearby rehearsal room, but I don't know if he's practicing seriously.",
  ui_story_5036_50360701_8_dialog_content = "I wonder if he's being disruptive to others?",
  ui_story_5036_50360701_9_dialog_content = "You know what, I need to go check on him.",
  ui_story_5036_50360701_10_dialog_content = "Let me.",
  ui_story_5036_50360701_11_dialog_content = "He's staying on my word, so I should supervise him.",
  ui_story_5036_50360701_12_dialog_content = "And you've hardly had any rest since yesterday. You should take a break.",
  ui_story_5036_50360701_13_dialog_content = "True. I also have a song to write... Can't squander the melody you shared with me!",
  ui_story_5036_50360701_14_dialog_content = "I'll leave Vic to you!",
  ui_story_5036_50360701_15_dialog_content = "*Yawn* What did you say?",
  ui_story_5036_50360701_16_dialog_content = "How's it going today?",
  ui_story_5036_50360701_17_dialog_content = "Not bad.",
  ui_story_5036_50360701_18_dialog_content = "I slept great last night!",
  ui_story_5036_50360701_19_dialog_content = "I was asking about your rehearsal.",
  ui_story_5036_50360701_20_dialog_content = "Don't tell me you slept the whole day and never thought about it?",
  ui_story_5036_50360701_21_dialog_content = "Didn't I already make myself clear? All right, one more time.",
  ui_story_5036_50360701_22_dialog_content = "Signing up for the competition was an excuse, the story about Ouroboros isn't fake.",
  ui_story_5036_50360701_23_dialog_content = "I wanted to use this opportunity to get inside Eulogoz and find the creature.",
  ui_story_5036_50360701_24_dialog_content = "I know that, but I don't sense any powerful Lumina coming from the lockdown area.",
  ui_story_5036_50360701_25_dialog_content = "There's just a bunch of Eclipsites sleeping in there.",
  ui_story_5036_50360701_26_dialog_content = "An incubating Ouroboros doesn't release significant Lumina.",
  ui_story_5036_50360701_27_dialog_content = "So that means the creature is still in an egg!",
  ui_story_5036_50360701_28_dialog_content = "How are you so sure that there's one of those things on Eugoloz?",
  ui_story_5036_50360701_29_dialog_content = "Call it intuition. An extrozoologist's intuition.",
  ui_story_5036_50360701_30_dialog_content = "So basically you have no evidence whatsoever.",
  ui_story_5036_50360701_31_dialog_content = "I can somewhat understand why Fia's always in a mood around you now.",
  ui_story_5036_50360701_32_dialog_content = "You still can't convince them to let me into the lockdown area?",
  ui_story_5036_50360701_33_dialog_content = "H-How do you expect me to broach the subject?",
  ui_story_5036_50360701_34_dialog_content = "Goldie ordered the mercs to guard the area, so she clearly doesn't want anyone going in and causing trouble.",
  ui_story_5036_50360701_35_dialog_content = "Even if there's an Ouroboros on Eulogoz, you can at least wait till the concert's over before looking for it.",
  ui_story_5036_50360701_36_dialog_content = "You mean I can stay on Eulogoz until the show's over?",
  ui_story_5036_50360701_37_dialog_content = "That depends on whether you make it through the auditions.",
  ui_story_5036_50360701_38_dialog_content = "Contestants that fail to garner enough votes have to leave immediately. It's clearly stated in the rules.",
  ui_story_5036_50360701_39_dialog_content = "Oh, that? That's a piece of cake.",
  ui_story_5036_50360701_40_dialog_content = "Oh? Did you have a show in mind?",
  ui_story_5036_50360701_41_dialog_content = "What do you think about getting Little Furball to do backflips?",
  ui_story_5036_50360701_42_dialog_content = "An animal show? You'd be better off auditioning for a circus.",
  ui_story_5036_50360701_43_dialog_content = "Isn't this an idol singing competition?",
  ui_story_5036_50360701_44_dialog_content = "Did you stumble into the wrong place?",
  ui_story_5036_50360701_45_dialog_content = "Ooh, is there drama brewing here?",
  ui_story_5036_50360701_46_dialog_content = "Where there's drama, there's news. I'd better take good notes!",
  ui_story_5036_50360701_47_dialog_content = "Hey, quit starin' around at other people! Yeah, you!",
  ui_story_5036_50360701_48_dialog_content = "Do you know me?",
  ui_story_5036_50360701_49_dialog_content = "I do know you.",
  ui_story_5036_50360701_50_dialog_content = "Wow, I didn't expect to meet someone who read my work here!",
  ui_story_5036_50360701_51_dialog_content = "You're that ghost thief that was caught recently.",
  ui_story_5036_50360701_52_dialog_content = "Aren't thieves supposed to be arrested? What's he still doing in the audition?",
  ui_story_5036_50360701_53_dialog_content = "Not to mention he's taking up a slot!",
  ui_story_5036_50360701_54_dialog_content = "Listen, thief. I don't know whose palms you greased...",
  ui_story_5036_50360701_55_dialog_content = "But none of us will allow you to desecrate the stage or our dreams!",
  ui_story_5036_50360701_56_dialog_content = "If you're not planning on auditioning for real, then just leave!",
  ui_story_5036_50360701_57_dialog_content = "Take it easy, everyone...",
  ui_story_5036_50360701_58_dialog_content = "It was all a misunderstanding. I truly want to compete.",
  ui_story_5036_50360701_59_dialog_content = "Not only that, I've decided to make it all the way to the final stage.",
  ui_story_5036_50360701_60_dialog_content = "With your circus act?",
  ui_story_5036_50360701_61_dialog_content = "I was just kidding!",
  ui_story_5036_50360701_62_dialog_content = "Why would I sign up if I didn't have a performance prepared?",
  ui_story_5036_50360701_63_dialog_content = "Then show us what you've got.",
  ui_story_5036_50360701_64_dialog_content = "Yeah!",
  ui_story_5036_50360701_65_dialog_content = "Let's see what kind of show you're putting on!",
  ui_story_5036_50360701_66_dialog_content = "About that...",
  ui_story_5036_50360701_67_dialog_content = "Well, what are you waiting for?",
  ui_story_5036_50360701_68_dialog_content = "Come on! Show us!",
  ui_story_5036_50360701_69_dialog_content = "Okay, calm down! I'll do it!",
  ui_story_5036_50360701_70_dialog_content = "Ahem, ladies and gentlemen: the Drakolion dance.",
  ui_story_5036_50360701_71_dialog_content = "This dance is an imitation of a Drakolion in flight, looking for a mate. Take a good look!",
  ui_story_5036_50360701_72_dialog_content = "Hey!",
  ui_story_5036_50360701_73_dialog_content = "Ha!",
  ui_story_5036_50360701_74_dialog_content = "Is... that supposed to be a dance?",
  ui_story_5036_50360701_75_dialog_content = "It looks more like someone relearning to walk after breaking a leg.",
  ui_story_5036_50360701_76_dialog_content = "Watch this, a backflip in the air!",
  ui_story_5036_50360701_77_dialog_content = "Hiya!",
  ui_story_5036_50360701_78_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5036_50360701_79_dialog_content = "Oh gosh... Ow, ow, ow, ow, ow!",
  ui_story_5036_50360701_80_dialog_content = "Hahaha!",
  ui_story_5036_50360701_81_dialog_content = "Did you hurt your back instead?",
  ui_story_5036_50360701_82_dialog_content = "It takes special talent to dance like that!",
  ui_story_5036_50360701_83_dialog_content = "Extrozoologist Turned Idol Bullied on Eulogoz...",
  ui_story_5036_50360701_84_dialog_content = "Will the editor like this kind of story?",
  ui_story_5036_50360701_85_dialog_content = "Are you okay, Vic?",
  ui_story_5036_50360701_86_dialog_content = "I see only PlayerName cares about the elderly!",
  ui_story_5036_50360701_87_dialog_content = "My ass is stuck on something. Can you pull me up?",
  ui_story_5036_50360701_88_dialog_content = "Sure...",
  ui_story_5036_50360701_89_dialog_content = "Hey, is that... an air vent behind you?!",
  ui_story_5036_50360701_90_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5036_50360701_91_dialog_content = "What was that?",
  ui_story_5036_50360701_92_dialog_content = "Wow, I broke the vent open again, hahaha!",
  ui_story_5036_50360701_93_dialog_content = "Graagh!",
  ui_story_5036_50360701_94_dialog_content = "Why are there Eclipsites in this vent too?",
  ui_story_5036_50360701_95_dialog_content = "Run—!",
  ui_story_5036_50360702_1_dialog_content = "Graagh!",
  ui_story_5036_50360702_2_dialog_content = "Blossom!",
  ui_story_5036_50360702_3_dialog_content = "The way Goldie dealt with those Eclipsites... I need to hurry up and figure out a way to investigate that tip off about her.",
  ui_story_5036_50360702_4_dialog_content = "Oh no! I forgot to take pictures...",
  ui_story_5036_50360702_5_dialog_content = "Is anyone hurt?",
  ui_story_5036_50360702_6_dialog_content = "Everybody's okay, just a little spooked.",
  ui_story_5036_50360702_7_dialog_content = "Thank you for saving us, Miss Goldie.",
  ui_story_5036_50360702_8_dialog_content = "You're as pretty as you are in the posters... No, you're much prettier!",
  ui_story_5036_50360702_9_dialog_content = "Miss Goldie?!",
  ui_story_5036_50360702_10_dialog_content = "I've been a Goldilock ever since you debuted!",
  ui_story_5036_50360702_11_dialog_content = "Will you autograph right here, Miss Goldie?",
  ui_story_5036_50360702_12_dialog_content = "Goldie! Goldie! Goldie!",
  ui_story_5036_50360702_13_dialog_content = "Sorry about this. I'll send someone to seal the vent and provide everyone with food.",
  ui_story_5036_50360702_14_dialog_content = "It's all that thief's fault. None of this would've happened if his butt didn't break the screen off.",
  ui_story_5036_50360702_15_dialog_content = "And he sure is an awful dancer!",
  ui_story_5036_50360702_16_dialog_content = "Kick him out! Kick him out! Kick him out!",
  ui_story_5036_50360702_17_dialog_content = "But...",
  ui_story_5036_50360702_18_dialog_content = "I really want to get through the audition.",
  ui_story_5036_50360702_19_dialog_content = "Oh yeah?",
  ui_story_5036_50360702_20_dialog_content = "Do you have the perseverance to make it to the end?",
  ui_story_5036_50360702_21_dialog_content = "For Ouroboros...",
  ui_story_5036_50360702_22_dialog_content = "I must!",
  ui_story_5036_50360702_23_dialog_content = "I must make it to the end!",
  ui_story_5036_50360702_24_dialog_content = "(Such blind optimism and determination does make me nostalgic.)",
  ui_story_5036_50360702_25_dialog_content = "(Before I went through any training, I also vowed that one day I would stand on a bigger stage.)",
  ui_story_5036_50360702_26_dialog_content = "(Am I seeing things?)",
  ui_story_5036_50360702_27_dialog_content = "(Why do I see my younger self in Vic?)",
  ui_story_5036_50360702_28_dialog_content = "(Is it because we both believe in the power of faith?)",
  ui_story_5036_50360702_29_dialog_content = "I must persevere to the end!",
  ui_story_5036_50360702_30_dialog_content = "...",
  ui_story_5036_50360702_31_dialog_content = "All right, I'll believe you one last time.",
  ui_story_5036_50360702_32_dialog_content = "Kick him out! Kick him out! Kick him out!",
  ui_story_5036_50360702_33_dialog_content = "Listen to me...",
  ui_story_5036_50360702_34_dialog_content = "Due to a number of misunderstandings, we mistakenly took Vic to be the ghost thief.",
  ui_story_5036_50360702_35_dialog_content = "But everything was all cleared up. Vic already returned everything to their respective owners and made the appropriate amends.",
  ui_story_5036_50360702_36_dialog_content = "So, we agreed to let him continue auditioning.",
  ui_story_5036_50360702_37_dialog_content = "But his actions nevertheless disrupted proceedings.",
  ui_story_5036_50360702_38_dialog_content = "Therefore, we're giving him just one last chance.",
  ui_story_5036_50360702_39_dialog_content = "If he still cannot make it, we will make him leave.",
  ui_story_5036_50360702_40_dialog_content = "There's only a day or two left. He won't improve regardless of how much he practices.",
  ui_story_5036_50360702_41_dialog_content = "But, since Miss Goldie has spoken...",
  ui_story_5036_50360702_42_dialog_content = "I support her decision!",
  ui_story_5036_50360702_43_dialog_content = "If he passes with a dance like that...",
  ui_story_5036_50360702_44_dialog_content = "I can't help but doubt Miss Goldie and the event's integrity.",
  ui_story_5036_50360702_45_dialog_content = "Please believe me when I say I'll be fair!",
  ui_story_5036_50360702_46_dialog_content = "Goldie! Goldie! Goldie!",
  ui_story_5036_50360702_47_dialog_content = "Ahem, thank you, Miss Goldie.",
  ui_story_5036_50360702_48_dialog_content = "What are you still doing here?",
  ui_story_5036_50360702_49_dialog_content = "Huh?",
  ui_story_5036_50360702_50_dialog_content = "Find a room and start practicing.",
  ui_story_5036_50360702_51_dialog_content = "But it's so late now...",
  ui_story_5036_50360702_52_dialog_content = "I told you you had a very good voice and excellent visuals.",
  ui_story_5036_50360702_53_dialog_content = "You're already way ahead of the curve than most people.",
  ui_story_5036_50360702_54_dialog_content = "But if you really want to make it to the end...",
  ui_story_5036_50360702_55_dialog_content = "You must do what I say.",
  ui_story_5036_50360801_1_dialog_content = "<color=#e8d9bb>Three days until the concert</color>",
  ui_story_5036_50360801_2_dialog_content = "♪ Ah... Oh...",
  ui_story_5036_50360801_3_dialog_content = "Stop!",
  ui_story_5036_50360801_4_dialog_content = "Is that the song you're planning on singing?",
  ui_story_5036_50360801_5_dialog_content = "I told you I had something prepared, but none of you believed me!",
  ui_story_5036_50360801_6_dialog_content = "Is this song gonna work?",
  ui_story_5036_50360801_7_dialog_content = "I went out to a remote forest in Northland and observed rare auroragales singing for inspiration for the melody.",
  ui_story_5036_50360801_8_dialog_content = "Coupled with wild, naturistic lyrics written by an extrozoologist like me...",
  ui_story_5036_50360801_9_dialog_content = "There's no way it won't go over well!",
  ui_story_5036_50360801_10_dialog_content = "Ahem...",
  ui_story_5036_50360801_11_dialog_content = "The song is not the problem. Your singing still has lots of room for improvement.",
  ui_story_5036_50360801_12_dialog_content = "I think you're putting it too nicely.",
  ui_story_5036_50360801_13_dialog_content = "Indeed, VERY nicely.",
  ui_story_5036_50360801_14_dialog_content = "PlayerName is one thing, but why would you mock me as well, Miss Reporter?",
  ui_story_5036_50360801_15_dialog_content = "I-I'm just speaking the truth.",
  ui_story_5036_50360801_16_dialog_content = "Brandy is a kind, objective, professional reporter.",
  ui_story_5036_50360801_17_dialog_content = "If your singing didn't impress her, you should figure out what the problem is.",
  ui_story_5036_50360801_18_dialog_content = "Maybe her ears suffered injuries in the past? Is that why you couldn't make out how lovely my voice is, Miss Reporter?",
  ui_story_5036_50360801_19_dialog_content = "No, that's not where I'm going with this!",
  ui_story_5036_50360801_20_dialog_content = "Um, so, anyway...",
  ui_story_5036_50360801_21_dialog_content = "To sing a song right, first, you must learn to breathe correctly.",
  ui_story_5036_50360801_22_dialog_content = "I need to learn how to breathe?",
  ui_story_5036_50360801_23_dialog_content = "If you want to be selected, follow my instructions.",
  ui_story_5036_50360801_24_dialog_content = "Roger that, Master Goldie!",
  ui_story_5036_50360801_25_dialog_content = "Inhale and fill your belly with air like a balloon. Contract your belly when you exhale.",
  ui_story_5036_50360801_26_dialog_content = "This is the belly breathing technique.",
  ui_story_5036_50360801_27_dialog_content = "Practice it for about ten minutes.",
  ui_story_5036_50360801_28_dialog_content = "That sounds like when Little Furball curls up and goes to sleep.",
  ui_story_5036_50360801_29_dialog_content = "Inhale... Exhale...",
  ui_story_5036_50360801_30_dialog_content = "Not bad. Draw it out longer.",
  ui_story_5036_50360801_31_dialog_content = "Inhaaaale... Exhaaaale...",
  ui_story_5036_50360801_32_dialog_content = "Very good. Keep it up.",
  ui_story_5036_50360801_33_dialog_content = "Inhale... Exhale...",
  ui_story_5036_50360801_34_dialog_content = "Inhale... Exhale...",
  ui_story_5036_50360801_35_dialog_content = "Did Vic fall asleep?",
  ui_story_5036_50360801_36_dialog_content = "Zzz...",
  ui_story_5036_50360801_37_dialog_content = "Vic!",
  ui_story_5036_50360801_38_dialog_content = "Don't be mad, Fia! What...?",
  ui_story_5036_50360801_39_dialog_content = "Oh, it's Goldie. Wait just kidding, it's Master Goldie.",
  ui_story_5036_50360801_40_dialog_content = "You're supposed to practice breathing, not falling asleep.",
  ui_story_5036_50360801_41_dialog_content = "<color=#e8d9bb>Sometime later</color>",
  ui_story_5036_50360801_42_dialog_content = "Once you learn how to breathe, you can work your vocal technique.",
  ui_story_5036_50360801_43_dialog_content = "You have a good voice, Vic, but remember this!",
  ui_story_5036_50360801_44_dialog_content = "Singing without proper vocal techniques will do irreversible harm to your vocal cords.",
  ui_story_5036_50360801_45_dialog_content = "But how do I develop proper vocal technique, Master Goldie?",
  ui_story_5036_50360801_46_dialog_content = "Good question.",
  ui_story_5036_50360801_47_dialog_content = "I'll teach you my super special method... Lip trills!",
  ui_story_5036_50360801_48_dialog_content = "Look carefully! Press your lips together, then...",
  ui_story_5036_50360801_49_dialog_content = "Brrrrrrrrrrr...",
  ui_story_5036_50360801_50_dialog_content = "Brrrrrrrrrrr...",
  ui_story_5036_50360801_51_dialog_content = "Wow, that's very good. You're a fast learner!",
  ui_story_5036_50360801_52_dialog_content = "This isn't difficult for me to do at all!",
  ui_story_5036_50360801_53_dialog_content = "Sometimes, I make this sound out in the field to draw out mud rhinos in heat.",
  ui_story_5036_50360801_54_dialog_content = "Brrrrrrrrrrr...",
  ui_story_5036_50360801_55_dialog_content = "On a good day, I can attract more than a dozen at a time!",
  ui_story_5036_50360801_56_dialog_content = "I... I see...",
  ui_story_5036_50360801_57_dialog_content = "Fortunately, we're in the sky right now.",
  ui_story_5036_50360801_58_dialog_content = "Anyway, practicing this will not only add depth to your voice, but it'll solve breathing problems too.",
  ui_story_5036_50360801_59_dialog_content = "You have less than two days until the last audition round.",
  ui_story_5036_50360801_60_dialog_content = "If you're serious about practicing, a day is more than enough for you to train it to be muscle memory and improve your singing.",
  ui_story_5036_50360801_61_dialog_content = "Imitating mud rhino grunting with my lips will improve my singing?",
  ui_story_5036_50360801_62_dialog_content = "I should expand on that and mimic other wondrous beasts too!",
  ui_story_5036_50360801_63_dialog_content = "Hai, hai hai!",
  ui_story_5036_50360801_64_dialog_content = "Hai?",
  ui_story_5036_50360801_65_dialog_content = "Hoot, hoot hoot.",
  ui_story_5036_50360801_66_dialog_content = "Hoot?",
  ui_story_5036_50360801_67_dialog_content = "Chirp! Chirp, chirp!",
  ui_story_5036_50360801_68_dialog_content = "Chirp?",
  ui_story_5036_50360801_69_dialog_content = "A-All right, all right.",
  ui_story_5036_50360801_70_dialog_content = "Just the mud rhinos will do.",
  ui_story_5036_50360801_71_dialog_content = "Really? I guess I went a little too far.",
  ui_story_5036_50360801_72_dialog_content = "What you also really need to work on is your dancing.",
  ui_story_5036_50360801_73_dialog_content = "Singing is just one part. Dancing will round out your performance.",
  ui_story_5036_50360801_74_dialog_content = "We still need to choreograph a routine for your song.",
  ui_story_5036_50360801_75_dialog_content = "Before we do that, I need to see how coordinated you are.",
  ui_story_5036_50360801_76_dialog_content = "I'll do a few basic dance steps. Try your best to keep up.",
  ui_story_5036_50360801_77_dialog_content = "Can you handle the music, PlayerName?",
  ui_story_5036_50360801_78_dialog_content = "Yeah, I'll play the accompaniment!",
  ui_story_5036_50360801_79_dialog_content = "Okay, Vic, keep up with the beat!",
  ui_story_5036_50360801_80_dialog_content = "A-one, a-two, move your feet!",
  ui_story_5036_50360801_81_dialog_content = "Once to the left, once to the right!",
  ui_story_5036_50360801_82_dialog_content = "Uh, left... right... For some reason I suddenly can't tell left from right?!",
  ui_story_5036_50360801_83_dialog_content = "Now, raise your arms! Make circles in the air!",
  ui_story_5036_50360801_84_dialog_content = "Left hand out, pull back!",
  ui_story_5036_50360801_85_dialog_content = "Right hand out, pull back!",
  ui_story_5036_50360801_86_dialog_content = "Left foot... Uh, you're already on your right hand?!",
  ui_story_5036_50360801_87_dialog_content = "Don't stop moving your feet!",
  ui_story_5036_50360801_88_dialog_content = "I'm not seeing things, am I?",
  ui_story_5036_50360801_89_dialog_content = "Miss Goldie...",
  ui_story_5036_50360801_90_dialog_content = "Umbraton's most popular idol, Miss Goldie, is really dancing in front of me right now?!",
  ui_story_5036_50360801_91_dialog_content = "Not even the most diehard Goldilock has gotten to enjoy such a perk!",
  ui_story_5036_50360801_X91_dialog_content = "Stay calm, must stay calm... I haven't even found what I came here for yet...",
  ui_story_5036_50360801_92_dialog_content = "She looks even more graceful next to Vic!",
  ui_story_5036_50360801_93_dialog_content = "I have to get this on film!",
  ui_story_5036_50360801_94_dialog_content = "Arms out as if you're reaching out to your dreams… and then pull them into your chest!",
  ui_story_5036_50360801_95_dialog_content = "A-one, a-two, move your feet!",
  ui_story_5036_50360801_96_dialog_content = "Wave the left hand, wave the right hand!",
  ui_story_5036_50360801_97_dialog_content = "*Panting* Is it over yet?",
  ui_story_5036_50360801_98_dialog_content = "Lastly, we raise both hands!",
  ui_story_5036_50360801_99_dialog_content = "Spin once around!",
  ui_story_5036_50360801_100_dialog_content = "Spin... Spinning!",
  ui_story_5036_50360801_101_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5036_50360801_102_dialog_content = "Ow, ow... That hurt.",
  ui_story_5036_50360801_103_dialog_content = "How many times have you fallen already today?",
  ui_story_5036_50360801_104_dialog_content = "It's okay, I'm used to it!",
  ui_story_5036_50360801_105_dialog_content = "Hard to believe you're even clumsier than a toddler learning to walk.",
  ui_story_5036_50360801_106_dialog_content = "And you're breathing so hard after just a few simple maneuvers... Don't you exercise regularly?",
  ui_story_5036_50360801_107_dialog_content = "Does sleep count as exercise?",
  ui_story_5036_50360801_108_dialog_content = "This is going to be a problem. Coordination takes time to develop.",
  ui_story_5036_50360801_109_dialog_content = "<color=#e8d9bb>Some more time later...</color>",
  ui_story_5036_50360801_110_dialog_content = "Can you remember the steps?",
  ui_story_5036_50360801_111_dialog_content = "Yeah, it's just walking around while waving your hands!",
  ui_story_5036_50360801_112_dialog_content = "Even though these are the most basic, simple steps...",
  ui_story_5036_50360801_113_dialog_content = "I still need you to put your feelings into it.",
  ui_story_5036_50360801_114_dialog_content = "Dance with feelings? I don't quite understand that.",
  ui_story_5036_50360801_115_dialog_content = "Vic, what do you think an idol's greatest asset is?",
  ui_story_5036_50360801_116_dialog_content = "The ability to sing and dance?",
  ui_story_5036_50360801_117_dialog_content = "Correct and incorrect.",
  ui_story_5036_50360801_118_dialog_content = "Being able to sing and dance is pretty much required, no doubt.",
  ui_story_5036_50360801_119_dialog_content = "But they're just a means to deliver your emotions to your audience.",
  ui_story_5036_50360801_120_dialog_content = "The most important things for an idol are their unyielding determination and passion.",
  ui_story_5036_50360801_121_dialog_content = "You pass this on to the audience through song and dance.",
  ui_story_5036_50360801_122_dialog_content = "Ah...",
  ui_story_5036_50360801_123_dialog_content = "<size=35>Perhaps he's got that already...</size>",
  ui_story_5036_50360801_124_dialog_content = "Did you say something, Master?",
  ui_story_5036_50360801_125_dialog_content = "*Ahem* You must first impress yourself before you can move others.",
  ui_story_5036_50360801_126_dialog_content = "I've said all I can say. The rest is up to you.",
  ui_story_5036_50360801_127_dialog_content = "I won't show any favoritism during the audition.",
  ui_story_5036_50360801_128_dialog_content = "You only have a day and a half left.",
  ui_story_5036_50360801_129_dialog_content = "Another day and a half, and I can resume searching for the Ouroboros!",
  ui_story_5036_50360801_130_dialog_content = "*Coughs* Goldie!",
  ui_story_5036_50360801_131_dialog_content = "Thank you so much for coming through in the end.",
  ui_story_5036_50360801_132_dialog_content = "No problem. It's my job to offer advice to the contestants, anyway.",
  ui_story_5036_50360801_133_dialog_content = "To be honest, I thought you wouldn't help him after all the trouble he caused.",
  ui_story_5036_50360801_134_dialog_content = "He's definitely a troublemaker.",
  ui_story_5036_50360801_135_dialog_content = "But, his potential is also undeniable.",
  ui_story_5036_50360801_136_dialog_content = "If he can really set out on the path towards becoming an idol, it'll also serve as a sort of motivation for me.",
  ui_story_5036_50360801_137_dialog_content = "Hey, are you two saying nice things about me?",
  ui_story_5036_50360801_138_dialog_content = "Can I listen?",
  ui_story_5036_50360801_139_dialog_content = "Oh, I almost forgot the most important thing.",
  ui_story_5036_50360801_140_dialog_content = "To idols, physical fitness is the foundation for all that you do.",
  ui_story_5036_50360801_141_dialog_content = "I just happen to have the secret to that. Wanna know what it is?",
  ui_story_5036_50360801_142_dialog_content = "Hey, where did you get a cage full of Eclipsites?",
  ui_story_5036_50360801_143_dialog_content = "I captured them, of course!",
  ui_story_5036_50360801_144_dialog_content = "Grah!",
  ui_story_5036_50360801_145_dialog_content = "Your secret wouldn't happen to be fighting Eclipsites, would it?",
  ui_story_5036_50360801_146_dialog_content = "Set aside your wondrous buddies.",
  ui_story_5036_50360801_147_dialog_content = "You're on your own this time.",
  ui_story_5036_50360801_148_dialog_content = "What?",
  ui_story_5036_50360801_149_dialog_content = "Graagh!",
  ui_story_5036_50360801_150_dialog_content = "Stay away from me!",
  ui_story_5036_50360801_151_dialog_content = "I knew you could fight Eclipsites on your own!",
  ui_story_5036_50360801_152_dialog_content = "But it's too tiring!",
  ui_story_5036_50360801_153_dialog_content = "Don't stop now!",
  ui_story_5036_50360801_154_dialog_content = "Keep singing and dancing while you fight!",
  ui_story_5036_50360801_155_dialog_content = "What?!",
  ui_story_5036_50360801_156_dialog_content = "You're the true devil!",
  ui_story_5036_50360801_157_dialog_content = "Grahhhhhh!",
  ui_story_5036_50360802_1_dialog_content = "<color=#e8d9bb>Two days until the concert</color>",
  ui_story_5036_50360802_2_dialog_content = "Hands in the air, everyone! Let's...",
  ui_story_5036_50360802_3_dialog_content = "Do it again!",
  ui_story_5036_50360802_4_dialog_content = "I-Is that really the thief we saw a few days ago?",
  ui_story_5036_50360802_5_dialog_content = "It might be him, but maybe not?",
  ui_story_5036_50360802_6_dialog_content = "♪ Ah, spring has come hither, and everything has come alive again ! ♪",
  ui_story_5036_50360802_7_dialog_content = "♪ Animals rise from their burrows and dens ♪",
  ui_story_5036_50360802_8_dialog_content = "♪ In the woods and in the prairies ♪",
  ui_story_5036_50360802_9_dialog_content = "♪ The sweetness of life abounds ♪",
  ui_story_5036_50360802_10_dialog_content = "I have no clue what he's singing about...",
  ui_story_5036_50360802_11_dialog_content = "but the melody is somehow really catchy?",
  ui_story_5036_50360802_12_dialog_content = "♪ Look, what's that? ♪",
  ui_story_5036_50360802_13_dialog_content = "♪ A fuzzy Bica that loves to say \"Hai!\" ♪",
  ui_story_5036_50360802_14_dialog_content = "Hai hai hai!",
  ui_story_5036_50360802_15_dialog_content = "Hai hai hai!",
  ui_story_5036_50360802_16_dialog_content = "♪ Look, what's that? ♪",
  ui_story_5036_50360802_17_dialog_content = "♪ A Lutumi Owl's around the corner. Watch your pockets! ♪",
  ui_story_5036_50360802_18_dialog_content = "Hoot hoot!",
  ui_story_5036_50360802_19_dialog_content = "Hoot hoot hoot!",
  ui_story_5036_50360802_20_dialog_content = "Goldie, did you find someone to impersonate Vic?",
  ui_story_5036_50360802_21_dialog_content = "What do you mean?",
  ui_story_5036_50360802_22_dialog_content = "I mean, he's improved by leaps and bounds in just a day and a half!",
  ui_story_5036_50360802_23_dialog_content = "I don't even recognize this person before my eyes.",
  ui_story_5036_50360802_24_dialog_content = "He's like an entirely different person!",
  ui_story_5036_50360802_25_dialog_content = "Told you Vic had great idol potential.",
  ui_story_5036_50360802_26_dialog_content = "He was a diamond in the rough that needed some polish to shine.",
  ui_story_5036_50360802_27_dialog_content = "The joy of growth!",
  ui_story_5036_50360802_28_dialog_content = "Who here understands the joy of growth?",
  ui_story_5036_50360802_29_dialog_content = "Nearly perfect in singing, dancing, looks, figure, EQ, and IQ.",
  ui_story_5036_50360802_30_dialog_content = "At last, a well-rounded contestant!",
  ui_story_5036_50360802_31_dialog_content = "I can't believe I was mesmerized by that performance...",
  ui_story_5036_50360802_32_dialog_content = "Forgive me, God of Light!",
  ui_story_5036_50360802_33_dialog_content = "Yes, great improvement.",
  ui_story_5036_50360802_34_dialog_content = "♪ Brrrrrrrrr... ♪",
  ui_story_5036_50360802_35_dialog_content = "♪ Anyone seen the elusive Ouroboros egg♪",
  ui_story_5036_50360802_36_dialog_content = "♪ Brrrrrrrrrr... ♪",
  ui_story_5036_50360802_37_dialog_content = "♪ I won't stop until I find you ♪",
  ui_story_5036_50360802_38_dialog_content = "And that's the end. Thank you, everyone!",
  ui_story_5036_50360802_39_dialog_content = "Vic! Vic! Vic! Vic!",
  ui_story_5036_50360802_40_dialog_content = "As we can see, the whole venue was taken by that performance!",
  ui_story_5036_50360802_41_dialog_content = "Thank you, Vic, for such a great show!",
  ui_story_5036_50360802_42_dialog_content = "Let's see what our judges have to say.",
  ui_story_5036_50360802_43_dialog_content = "Miss Goldie, it's all yours!",
  ui_story_5036_50360802_44_dialog_content = "I have nothing to say.",
  ui_story_5036_50360802_45_dialog_content = "What? But I stayed up to practice for two nights straight! I still can't make it?",
  ui_story_5036_50360802_46_dialog_content = "I would've stayed in bed if I had known that.",
  ui_story_5036_50360802_47_dialog_content = "What I mean is your performance was too good for me to find any flaws.",
  ui_story_5036_50360802_48_dialog_content = "I believe our votes will speak for themselves.",
  ui_story_5036_50360802_49_dialog_content = "Alright! The results are in.",
  ui_story_5036_50360802_50_dialog_content = "Let's see if Vic can make it onto the concert stage!",
  ui_story_5036_50360802_51_dialog_content = "He received...",
  ui_story_5036_50360802_52_dialog_content = "I received...?",
  ui_story_5036_50360802_53_dialog_content = "<size=45>A unanimous vote!</size>",
  ui_story_5036_50360802_54_dialog_content = "Seriously? Even the rookie made it. The pressure's on for a certain someone.",
  ui_story_5036_50360802_55_dialog_content = "Should I sing a positive song to pump her up?",
  ui_story_5036_50360802_56_dialog_content = "Take your monotonous saccharin pop music somewhere else.",
  ui_story_5036_50360802_57_dialog_content = "Oh, but I'd be so sad and lonely if you didn't make it.",
  ui_story_5036_50360802_58_dialog_content = "You only made it in before me because you performed before me.",
  ui_story_5036_50360802_59_dialog_content = "Just you wait and see. The judges will regret picking you clowns after they see my performance!",
  ui_story_5036_50360802_60_dialog_content = "How do you feel, Vic?",
  ui_story_5036_50360802_61_dialog_content = "I can finally get some sleep...",
  ui_story_5036_50360802_62_dialog_content = "When I wake up, I...",
  ui_story_5036_50360802_63_dialog_content = "can go find... Ourobo...",
  ui_story_5036_50360802_64_dialog_content = "Vic?",
  ui_story_5036_50360802_65_dialog_content = "Are you okay, Vic?",
  ui_story_5036_50360802_66_dialog_content = "Zzz...",
  ui_story_5036_50360802_67_dialog_content = "Uh, Vic...",
  ui_story_5036_50360802_68_dialog_content = "Please don't fall asleep during the audition!",
  ui_story_5036_50360802_69_dialog_content = "Vic really fell into a remarkably deep sleep, it seems.",
  ui_story_5036_50360802_70_dialog_content = "I can't believe he slept the entire day, through all that noise!",
  ui_story_5036_50360802_71_dialog_content = "Yeah, he didn't even wake up when the mercs hauled him back to his room.",
  ui_story_5036_50360802_72_dialog_content = "We all witnessed his improvement.",
  ui_story_5036_50360802_73_dialog_content = "He must have been exhausted from practicing so hard over the past two days.",
  ui_story_5036_50360802_74_dialog_content = "I think you two practiced hard too.",
  ui_story_5036_50360802_75_dialog_content = "Or you wouldn't have also gotten a unanimous vote.",
  ui_story_5036_50360802_76_dialog_content = "Oh, we totally expected that!",
  ui_story_5036_50360802_77_dialog_content = "But yeah, I'm tired.",
  ui_story_5036_50360802_78_dialog_content = "We should turn in early today.",
  ui_story_5036_50360802_79_dialog_content = "There'll be a whole day of rehearsals tomorrow.",
  ui_story_5036_50360802_80_dialog_content = "I hope I don't have another dream tonight.",
  ui_story_5036_50360802_81_dialog_content = "Yes. Good night.",
  ui_story_5036_50360802_82_dialog_content = "Vice? Carleen?",
  ui_story_5036_50360802_83_dialog_content = "They left so fast...",
  ui_story_5036_50360802_84_dialog_content = "Well then...",
  ui_story_5036_50360802_85_dialog_content = "I should turn in too.",
  ui_story_5036_50360901_1_dialog_content = "Where am I...?",
  ui_story_5036_50360901_2_dialog_content = "On a Colossus, I think... Is that the Caelestite that was in my dream before?",
  ui_story_5036_50360901_3_dialog_content = "Am I dreaming again?",
  ui_story_5036_50360901_4_dialog_content = "You're Eulogoz, right?",
  ui_story_5036_50360901_5_dialog_content = "Yes. You're my new Navigator, I presume?",
  ui_story_5036_50360901_6_dialog_content = "That's right! My name is Chaminade. Nice to meet you.",
  ui_story_5036_50360901_7_dialog_content = "(The location's changed... This seems to be the bridge?)",
  ui_story_5036_50360901_8_dialog_content = "Why do you have so many screens and weird sound systems, Eulogoz?",
  ui_story_5036_50360901_9_dialog_content = "I asked my buddies, and they've never seen anything like it on other Colossi before.",
  ui_story_5036_50360901_10_dialog_content = "Even I do not know the answer to that question.",
  ui_story_5036_50360901_11_dialog_content = "Long ago memories escape me like singing in the wind.",
  ui_story_5036_50360901_12_dialog_content = "What a shame...",
  ui_story_5036_50360901_13_dialog_content = "But everyone loves you!",
  ui_story_5036_50360901_14_dialog_content = "Only you can make music reverberate throughout Eraveil.",
  ui_story_5036_50360901_15_dialog_content = "Thank you. I'm very happy to hear that.",
  ui_story_5036_50360901_16_dialog_content = "Let's go travel, Eulogoz!",
  ui_story_5036_50360901_17_dialog_content = "Hmm? Why so sudden?",
  ui_story_5036_50360901_18_dialog_content = "My teachers say that many in Astra still suffer from war and Eclipsites.",
  ui_story_5036_50360901_19_dialog_content = "Their lives are hopeless and difficult, so I want to sing for them!",
  ui_story_5036_50360901_20_dialog_content = "I know my singing can't defeat the Eclipsites or provide them anything of use...",
  ui_story_5036_50360901_21_dialog_content = "but at the very least, I can give them something to listen to other than gunfire.",
  ui_story_5036_50360901_22_dialog_content = "Places like that are too dangerous for you.",
  ui_story_5036_50360901_23_dialog_content = "I know, but if my singing can lend them a sliver of comfort and hope, any peril is worth it.",
  ui_story_5036_50360901_24_dialog_content = "Understood.",
  ui_story_5036_50360901_25_dialog_content = "Let us go now.",
  ui_story_5036_50360901_26_dialog_content = "Another dream? But it feels different... more like a memory.",
  ui_story_5036_50360901_27_dialog_content = "So the Caelestite girl's name is Chaminade.",
  ui_story_5036_50360901_28_dialog_content = "Unless that dream was me sensing the lingering traces of her presence on this Colossus.",
  ui_story_5036_50360901_29_dialog_content = "A singing Caelestite riding a Colossus, touring through Astra... She sounds a lot like Goldie.",
  ui_story_5036_50360901_30_dialog_content = "*Yawn* I sure dreamed a lot for just one hour of sleep.",
  ui_story_5036_50360901_31_dialog_content = "I won't be able to fall back asleep for a while... maybe I should get something to eat.",
  ui_story_5036_50360901_32_dialog_content = "<color=#e8d9bb>Knock, knock!</color>",
  ui_story_5036_50360901_33_dialog_content = "(Who's knocking this late at night?)",
  ui_story_5036_50360901_34_dialog_content = "Coming!",
  ui_story_5036_50360901_35_dialog_content = "Sorry, PlayerName, did I wake you up?",
  ui_story_5036_50360901_36_dialog_content = "No, I was up... What are you doing here, Goldie?",
  ui_story_5036_50360901_37_dialog_content = "I need your help. The entire concert's future hangs on it!",
  ui_story_5036_50360901_38_dialog_content = "That serious? Is the Eulogoz crashing?",
  ui_story_5036_50360901_39_dialog_content = "No, it's not that bad... Have you had a strange dream lately?",
  ui_story_5036_50360901_40_dialog_content = "A dream of a vast valley, and the sound of a girl singing.",
  ui_story_5036_50360901_41_dialog_content = "Yeah, I have. For whatever reason, I've been having that dream every single night.",
  ui_story_5036_50360901_42_dialog_content = "The valley is Eraveil, and the girl is a Caelestite.",
  ui_story_5036_50360901_43_dialog_content = "So she's a Caelestite?!",
  ui_story_5036_50360901_44_dialog_content = "Didn't the way she was dressed give it away?",
  ui_story_5036_50360901_45_dialog_content = "The dream's weird, but I haven't paid it too much attention since it's not a nightmare.",
  ui_story_5036_50360901_46_dialog_content = "Wait, didn't we talk about this before and chalked it up as a coincidence?",
  ui_story_5036_50360901_47_dialog_content = "That's what I thought too, but now, everyone on the Colossus has had the same dream!",
  ui_story_5036_50360901_48_dialog_content = "Everyone?!",
  ui_story_5036_50360901_49_dialog_content = "Yes. It's a coincidence when it's two or three people, but not when it's everybody!",
  ui_story_5036_50360901_50_dialog_content = "It's made everyone anxious.",
  ui_story_5036_50360901_51_dialog_content = "Contestants have come to me complaining that the dream's disrupting their sleep.",
  ui_story_5036_50360901_52_dialog_content = "They can't perform properly without adequate rest.",
  ui_story_5036_50360901_53_dialog_content = "So you want to get to the root of the problem to ensure proper rest for everyone?",
  ui_story_5036_50360901_54_dialog_content = "Yeah. I tried looking into it myself, but to no avail, since I don't have your psychic abilities.",
  ui_story_5036_50360901_55_dialog_content = "Can you help me, PlayerName?",
  ui_story_5036_50360901_56_dialog_content = "For the sake of the concert, most definitely!",
  ui_story_5036_50360901_57_dialog_content = "Thank you!",
  ui_story_5036_50360901_58_dialog_content = "But given the sheer size of Eulogoz, I can't cover the whole structure even with my telepathy.",
  ui_story_5036_50360901_59_dialog_content = "Where should we start?",
  ui_story_5036_50360901_60_dialog_content = "I don't know...",
  ui_story_5036_50360901_61_dialog_content = "I suggest starting from the rear section!",
  ui_story_5036_50360901_62_dialog_content = "Vic! Where did you come from?",
  ui_story_5036_50360901_63_dialog_content = "The concert is in two days! Shouldn't you be practicing?",
  ui_story_5036_50360901_64_dialog_content = "Come on, weren't you just stressing over the weird dream?",
  ui_story_5036_50360901_65_dialog_content = "You need to get quality sleep first to have the energy to practice.",
  ui_story_5036_50360901_66_dialog_content = "That's true, but hearing that from your mouth is fishy.",
  ui_story_5036_50360901_67_dialog_content = "Hahaha! You're just being paranoid.",
  ui_story_5036_50360901_68_dialog_content = "It's suspicious to see you being so proactive.",
  ui_story_5036_50360901_69_dialog_content = "I remember now! You've been wanting to search for the Ouroboros over there. You definitely have an ulterior motive!",
  ui_story_5036_50360901_70_dialog_content = "How could you say that? The more, the merrier. You have nothing to lose letting me tag along.",
  ui_story_5036_50360901_71_dialog_content = "Okay, but I'll be watching you in tomorrow's practice, so don't try to slack off.",
  ui_story_5036_50360901_72_dialog_content = "Extrozoologists don't lie.",
  ui_story_5036_50360901_73_dialog_content = "But for now, let's concentrate on dealing with the weird dream.",
  ui_story_5036_50360901_74_dialog_content = "(It's suspicious that Vic is so interested in this.)",
  ui_story_5036_50360901_75_dialog_content = "(What's he up to?)",
  ui_story_5036_50360901_76_dialog_content = "The rear section... Isn't that where the Eclipsites are contained?",
  ui_story_5036_50360901_77_dialog_content = "Is there any evidence that suggests we should start with such a dangerous place?",
  ui_story_5036_50360901_78_dialog_content = "None at all!",
  ui_story_5036_50360901_79_option_content = "Let's ignore him",
  ui_story_5036_50360901_80_dialog_content = "Oh, come on, PlayerName, we've worked together before. Don't be so heartless!",
  ui_story_5036_50360901_81_option_content = "...",
  ui_story_5036_50360901_82_dialog_content = "...",
  ui_story_5036_50360901_83_dialog_content = "Young people are so easily rattled because there's much they have not seen.",
  ui_story_5036_50360901_84_dialog_content = "I have no concrete evidence, but my suggestion wasn't baseless.",
  ui_story_5036_50360901_85_dialog_content = "The upper sections are all clear of Eclipsites, so everybody can move about freely.",
  ui_story_5036_50360901_86_dialog_content = "Naturally, that means those areas pretty much don't need to be investigated.",
  ui_story_5036_50360901_87_dialog_content = "True. Someone would've noticed something was wrong by now.",
  ui_story_5036_50360901_88_dialog_content = "So that leaves only the rear section.",
  ui_story_5036_50360901_89_dialog_content = "But there are a lot of Eclipsites there. It's too risky with only the three of us.",
  ui_story_5036_50360901_90_dialog_content = "I thought of that too. We just need Lutumi Owl to help out.",
  ui_story_5036_50360901_91_dialog_content = "Let it put the Eclipsites to sleep before we sneak in. That should minimize the need to fight.",
  ui_story_5036_50360901_92_dialog_content = "Is that how you stole all that stuff before?",
  ui_story_5036_50360901_93_dialog_content = "Of course... not!",
  ui_story_5036_50360901_94_dialog_content = "Anyways, the owl was the one that caused that whole misunderstanding.",
  ui_story_5036_50360901_95_dialog_content = "Now, we'll let it make up for the trouble. How's that?",
  ui_story_5036_50360901_96_dialog_content = "Let's discuss this matter after the concert.",
  ui_story_5036_50360901_97_dialog_content = "Vic does have a point, though. Let's start with the rear end of the Colossus.",
  ui_story_5036_50360901_98_dialog_content = "Okay, let's go.",
  ui_story_5036_50360901_99_dialog_content = "I was going to approach Goldie about her rumored mean streak...",
  ui_story_5036_50360901_100_dialog_content = "but now the three of them are doing something secretive!",
  ui_story_5036_50360901_101_dialog_content = "Luckily, I was too far away for PlayerName to sense me with his skill!",
  ui_story_5036_50360901_102_dialog_content = "They were too far away for me to hear them clearly though...",
  ui_story_5036_50360901_103_dialog_content = "Isn't that... where the rear section is?",
  ui_story_5036_50360901_104_dialog_content = "They're acting too suspicious for me to not follow!",
  ui_story_5036_50360901_105_dialog_content = "It's so dark here... It feels like Eclipsites will pop out any second.",
  ui_story_5036_50360901_106_dialog_content = "Relax and leave everything to Lutumi Owl. Look.",
  ui_story_5036_50360901_107_dialog_content = "Hoot hoot!",
  ui_story_5036_50360901_108_dialog_content = "(Eclipsian) L-Lady Forsakin?!",
  ui_story_5036_50360901_109_dialog_content = "Hoot hoot hoot!",
  ui_story_5036_50360901_110_dialog_content = "(Eclipsian) Thank you for the praise. I shall work harder!",
  ui_story_5036_50360901_111_dialog_content = "(Eclipsian) I can't believe I was complimented... So strange... so drowsy...",
  ui_story_5036_50360901_112_dialog_content = "(Eclipsian) Yawn...",
  ui_story_5036_50360901_113_dialog_content = "See? Easy peasy.",
  ui_story_5036_50360901_114_dialog_content = "Are you sure this doesn't count as exploiting the animal for its power?",
  ui_story_5036_50360901_115_dialog_content = "Lutumi Owl is my friend. It's helping me willingly. I'm certain of that.",
  ui_story_5036_50360901_116_dialog_content = "It's very dark in here...",
  ui_story_5036_50360901_117_dialog_content = "*Whimper* No! I've got to keep going!",
  ui_story_5036_50360901_118_dialog_content = "Are you okay, Goldie?",
  ui_story_5036_50360901_119_dialog_content = "Huh? I'm totally fine!",
  ui_story_5036_50360901_120_dialog_content = "Why would an idol not be okay? I'm just a little tired and need a break.",
  ui_story_5036_50360901_121_dialog_content = "Let me cuddle you, Marshmallow.",
  ui_story_5036_50360901_122_dialog_content = "Woof...",
  ui_story_5036_50360901_123_dialog_content = "So soft and fuzzy... Okay, I'm ready now!",
  ui_story_5036_50360901_124_dialog_content = "Let's continue!",
  ui_story_5036_50360901_125_dialog_content = "(Goldie is acting strange. Is she afraid of the dark?)",
  ui_story_5036_50360901_126_dialog_content = "We've been walking for so long... We should be close to the Colossus' tail by now.",
  ui_story_5036_50360901_X126_dialog_content = "Can you sense anything nearby, PlayerName?",
  ui_story_5036_50360901_127_dialog_content = "Let me see.",
  ui_story_5036_50360901_128_option_content = "Force Boost!",
  ui_story_5036_50360901_129_dialog_content = "(There's nothing but sleeping Eclipsites around.)",
  ui_story_5036_50360901_130_dialog_content = "(Except something just feels off... am I being paranoid?)",
  ui_story_5036_50360901_131_dialog_content = "(Hold on, this feels...)",
  ui_story_5036_50360901_132_dialog_content = "(It feels very similar to when I sensed the lingering emotions of Caelestites when I returned to Eraveil for the first time!)",
  ui_story_5036_50360901_133_dialog_content = "(Let me try to dig deeper.)",
  ui_story_5036_50360901_134_dialog_content = "Whoa! W-What's this, Eulogoz?",
  ui_story_5036_50360901_135_dialog_content = "Don't panic, Chaminade, it's not an Eclipsite.",
  ui_story_5036_50360901_136_dialog_content = "According to my data, it is an animal called the Ouroboros. It is very friendly to Aurorians and Caelestites.",
  ui_story_5036_50360901_137_dialog_content = "Thank goodness it's not an Eclipsite.",
  ui_story_5036_50360901_138_dialog_content = "Kree, kree!",
  ui_story_5036_50360901_139_dialog_content = "Hee, stop licking my face!",
  ui_story_5036_50360901_140_dialog_content = "Do you sense anything, PlayerName?",
  ui_story_5036_50360901_141_dialog_content = "Her name is Chaminade after all...",
  ui_story_5036_50360901_142_dialog_content = "Chaminade? Are you talking about that Caelestite girl?",
  ui_story_5036_50360901_143_dialog_content = "Yeah. I sensed lingering traces of her, and...",
  ui_story_5036_50360901_144_dialog_content = "the Ouroboros too!",
  ui_story_5036_50360901_145_dialog_content = "What?!",
  ui_story_5036_50360901_146_dialog_content = "You sensed the Ouroboros? Quick, tell me more!",
  ui_story_5036_50360901_147_dialog_content = "Stop shaking me and let go before I throw up!",
  ui_story_5036_50360901_148_dialog_content = "Talk first, then I'll let go.",
  ui_story_5036_50360901_149_dialog_content = "What I sensed was not an Ouroboros from the present but one from the past!",
  ui_story_5036_50360901_150_dialog_content = "The past?",
  ui_story_5036_50360901_151_dialog_content = "The former owner of this Colossus and the Caelestite girl everyon'e been dreaming of, her name was Chaminade.",
  ui_story_5036_50360901_152_dialog_content = "Once upon a time, she met an Ouroboros and let it stay onboard.",
  ui_story_5036_50360901_153_dialog_content = "But I surmise that happened at least a hundred years ago.",
  ui_story_5036_50360901_154_dialog_content = "The Ouroboros you're looking for is probably long gone by now.",
  ui_story_5036_50360901_155_dialog_content = "Oh...",
  ui_story_5036_50360901_156_dialog_content = "Say, how about letting go of me?",
  ui_story_5036_50360901_157_dialog_content = "Well, you didn't get a location, but it's still valuable information.",
  ui_story_5036_50360901_158_dialog_content = "Help me out young Caelestite, keep using those senses of yours!",
  ui_story_5036_50360901_159_dialog_content = "Consider this paying me back for all the danger my dear student Fia suffered for your sake!",
  ui_story_5036_50360901_160_dialog_content = "Paying YOU back?!",
  ui_story_5036_50360901_161_dialog_content = "Stop! Aren't we supposed to be solving the dream problem right now?",
  ui_story_5036_50360901_162_dialog_content = "When did our objective become about finding the Ouroboros?",
  ui_story_5036_50360901_163_dialog_content = "Oh yeah, I almost got sidetracked!",
  ui_story_5036_50360901_164_dialog_content = "Youngsters, you're looking at this the wrong way.",
  ui_story_5036_50360901_165_dialog_content = "Didn't you say the Caelestite with the Ouroboros was the girl in our dreams?",
  ui_story_5036_50360901_166_dialog_content = "Yes... And we should center our investigation around her, regardless.",
  ui_story_5036_50360901_167_dialog_content = "Well, I only ask that you keep an eye out for leads on the Ouroboros in the interim.",
  ui_story_5036_50360901_168_dialog_content = "Why do I feel like I'm giving you free labor?",
  ui_story_5036_50360901_169_dialog_content = "It's not free labor. Showing respect for your elders is a good virtue.",
  ui_story_5036_50360901_170_dialog_content = "You really think of anything, don't you...",
  ui_story_5036_50360901_171_dialog_content = "Why, thank you.",
  ui_story_5036_50360901_172_dialog_content = "We need PlayerName to investigate the dream.",
  ui_story_5036_50360901_173_dialog_content = "Would you mind sensing again somewhere else to see if you can find any more lingering traces?",
  ui_story_5036_50360901_174_dialog_content = "Maybe we can sort through them and uncover the source of the dreams.",
  ui_story_5036_50360901_175_dialog_content = "Sure, I'll give it a shot!",
  ui_story_5036_50360901_176_dialog_content = "I've never been here before.",
  ui_story_5036_50360901_177_dialog_content = "We're closer to the rear section than before, so we should be able to find something new.",
  ui_story_5036_50360901_178_dialog_content = "Goldie, Vic, do you guys feel something off about this place?",
  ui_story_5036_50360901_179_dialog_content = "It is a bit cold. Maybe because of Darkflow?",
  ui_story_5036_50360901_180_dialog_content = "No, I'm not sensing too much Darkflow. I just feel anxious for some reason.",
  ui_story_5036_50360901_181_dialog_content = "You're not afraid of the dark, are you?",
  ui_story_5036_50360901_182_dialog_content = "Of course I'm not!",
  ui_story_5036_50360901_183_dialog_content = "It's nothing to be ashamed about.",
  ui_story_5036_50360901_184_dialog_content = "Shira was afraid of the dark when she was young. The wind would scare her into tears at night!",
  ui_story_5036_50360901_185_dialog_content = "Other than preying on birds, a Drakolion can also... Achoo!",
  ui_story_5036_50360901_186_dialog_content = "... Can also sneeze?",
  ui_story_5036_50360901_187_dialog_content = "No, no... Achoo!",
  ui_story_5036_50360901_188_dialog_content = "I just needed to sneeze all of a sudden.",
  ui_story_5036_50360901_189_dialog_content = "Did you catch a cold?",
  ui_story_5036_50360901_190_dialog_content = "Nope. I'm guessing Vic is trash talking me somewhere.",
  ui_story_5036_50360901_191_dialog_content = "I'm going to grill him about it when he gets back.",
  ui_story_5036_50360901_192_dialog_content = "Are you lying again?",
  ui_story_5036_50360901_193_dialog_content = "No way. Ask Shira if you don't believe it.",
  ui_story_5036_50360901_194_dialog_content = "Never mind, I have better things to do.",
  ui_story_5036_50360901_X194_dialog_content = "There seems to be some emotions still lingering around here. I'll try to sense them.",
  ui_story_5036_50360901_195_option_content = "Mindlink!",
  ui_story_5036_50360901_196_dialog_content = "♪ Dewdrops, capturing the golden daybreak ♪",
  ui_story_5036_50360901_197_dialog_content = "♪ Shine ever so shyly ♪",
  ui_story_5036_50360901_198_dialog_content = "( It's the tune to start the Colossus!)",
  ui_story_5036_50360901_199_dialog_content = "Kree, kree... kree!",
  ui_story_5036_50360901_200_dialog_content = "Ouroboros? Weren't you sleeping? What are you doing here?",
  ui_story_5036_50360901_201_dialog_content = "Kree—♪ Kree—♪",
  ui_story_5036_50360901_202_dialog_content = "Are you singing?! The song I was just singing?!",
  ui_story_5036_50360901_203_dialog_content = "Do you understand my music?!",
  ui_story_5036_50360901_204_dialog_content = "Kree— ♪ Kree, kree, kree ♪",
  ui_story_5036_50360901_205_dialog_content = "Is that an affirmation?!",
  ui_story_5036_50360901_206_dialog_content = "How amazing, the creature could communicate using the melody Caelestites use to control Colossi.",
  ui_story_5036_50360901_207_dialog_content = "I sense something else...",
  ui_story_5036_50360901_208_dialog_content = "These memories are only coming to me in bits and fragments.",
  ui_story_5036_50360901_209_dialog_content = "What is it? Tell me!",
  ui_story_5036_50360901_210_dialog_content = "Do they mention anything about the strange dreams?",
  ui_story_5036_50360901_211_dialog_content = "No.",
  ui_story_5036_50360901_212_dialog_content = "I feel Chaminade's pleasant surprise as she discovers the Ouroboros's secret by chance.",
  ui_story_5036_50360901_213_dialog_content = "These creatures seem to be able of conveying emotions and communicating with people using the melodies for controlling the Colossi.",
  ui_story_5036_50360901_214_dialog_content = "That's completely new information pertaining to the Ouroboros!",
  ui_story_5036_50360901_215_dialog_content = "Excellent! I've got nothing to reward you with though.",
  ui_story_5036_50360901_216_dialog_content = "...",
  ui_story_5036_50360901_217_dialog_content = "You know, the ancient books do mention a mysterious connection between this species and the Colossi.",
  ui_story_5036_50360901_218_dialog_content = "We can't dismiss the possibility that perhaps they also possessed certain psychic abilities.",
  ui_story_5036_50360901_219_dialog_content = "For example... making people dream.",
  ui_story_5036_50360901_220_dialog_content = "You think so?!",
  ui_story_5036_50360901_221_dialog_content = "I'm really going to punish you this time if you're lying!",
  ui_story_5036_50360901_222_dialog_content = "I wouldn't dare!",
  ui_story_5036_50360901_223_dialog_content = "It's just a theory. I can't guarantee that I'm right.",
  ui_story_5036_50360901_224_dialog_content = "How dubious...",
  ui_story_5036_50360901_225_dialog_content = "What do you think, PlayerName?",
  ui_story_5036_50360901_226_option_content = "Believe Vic",
  ui_story_5036_50360901_227_dialog_content = "While Vic usually lies a lot and isn't very dependable...",
  ui_story_5036_50360901_228_dialog_content = "he really is an absolute authority on all things related to the wondrous beasts.",
  ui_story_5036_50360901_229_dialog_content = "It shouldn't be an issue to trust him in that area.",
  ui_story_5036_50360901_230_dialog_content = "Indeed, you should always listen to your elders.",
  ui_story_5036_50360901_231_dialog_content = "All right, I trust PlayerName's judgment.",
  ui_story_5036_50360901_232_option_content = "Don't believe Vic",
  ui_story_5036_50360901_233_dialog_content = "My advice is don't listen to him, because he hardly ever tells the truth.",
  ui_story_5036_50360901_234_dialog_content = "Oh, my poor old heart... *Sob*",
  ui_story_5036_50360901_235_dialog_content = "Just like that, you see? He cries that he's an old man one second, then tells you he's forever 18 the next.",
  ui_story_5036_50360901_236_dialog_content = "You whippersnappers don't get it. It's called being young at heart.",
  ui_story_5036_50360901_237_dialog_content = "Definitely not trustworthy.",
  ui_story_5036_50360901_238_dialog_content = "Sigh!",
  ui_story_5036_50360901_239_dialog_content = "However, we have no choice but to follow this only lead we have.",
  ui_story_5036_50360901_240_dialog_content = "So we can only keep going? Sigh, but still, I guess we can't give up so easily.",
  ui_story_5036_50360901_241_dialog_content = "Let's go see what else we can find.",
  ui_story_5036_50360901_242_dialog_content = "They keep stopping, what are they doing?",
  ui_story_5036_50360901_243_dialog_content = "Now that I realize it, this is the lockdown area, isn't it? So dark and scary...",
  ui_story_5036_50360901_244_dialog_content = "<color=#e8d9bb>Whoosh...</color>",
  ui_story_5036_50360901_245_dialog_content = "Eh?! W-Was that the wind? I probably should turn back and ask Goldie another day...",
  ui_story_5036_50360901_246_dialog_content = "No, Brandy, you're a truth-seeking reporter. You can't quit now!",
  ui_story_5036_50360901_247_dialog_content = "I have to keep up with them!",
  ui_story_5036_50360901_248_dialog_content = "How long have we been walking? Twenty minutes?",
  ui_story_5036_50360901_249_dialog_content = "The corridors here are labyrinthine. We're just going around and around.",
  ui_story_5036_50360901_250_dialog_content = "Shouldn't you lead, PlayerName, since you've lived on a Colossus for so long?",
  ui_story_5036_50360901_251_dialog_content = "I just know Soroz, not this one here.",
  ui_story_5036_50360901_252_dialog_content = "True. How about trying your psychic abilities?",
  ui_story_5036_50360901_253_dialog_content = "If the traces of that Caelestite are still around, that could guide us.",
  ui_story_5036_50360901_254_dialog_content = "That's an idea. Let me try.",
  ui_story_5036_50360901_255_option_content = "Mindlink!",
  ui_story_5036_50360901_256_dialog_content = "Oh no, Eulogoz!",
  ui_story_5036_50360901_257_dialog_content = "Look what happened to the Ouroboros!",
  ui_story_5036_50360901_258_dialog_content = "*Sob* What happened to it? Is it gone forever?",
  ui_story_5036_50360901_259_dialog_content = "Without it, we wouldn't have been able to evade all those Eclipsite attacks...",
  ui_story_5036_50360901_260_dialog_content = "Do not panic, Chaminade.",
  ui_story_5036_50360901_261_dialog_content = "The Ouroboros are creatures of longevity. They turn into eggs when they are old, re-incubate, and then they are reborn.",
  ui_story_5036_50360901_262_dialog_content = "It trusts you to protect it when it is at its weakest moment. That is why it chose to become an egg here.",
  ui_story_5036_50360901_263_dialog_content = "Just wait for a while, and it'll be able to travel alongside you again.",
  ui_story_5036_50360901_264_dialog_content = "Really?",
  ui_story_5036_50360901_265_dialog_content = "This is great! So the Ouroboros didn't die, and we can still be together.",
  ui_story_5036_50360901_266_dialog_content = "I shall protect it. How about this? Let's put the egg in the most secure room!",
  ui_story_5036_50360901_267_dialog_content = "No Eclipsites can get close then!",
  ui_story_5036_50360901_268_dialog_content = "I see it! Exceptionally clear this time!",
  ui_story_5036_50360901_269_dialog_content = "Chaminade said she put the egg in the most fortified room on the Colossus.",
  ui_story_5036_50360901_X269_dialog_content = "She ran in that direction.",
  ui_story_5036_50360901_270_dialog_content = "Let's go! We might find something new.",
  ui_story_5036_50360901_271_dialog_content = "It's been years, though. Any leads would've gone cold by now.",
  ui_story_5036_50360901_272_dialog_content = "Never mind, let's just go.",
  ui_story_5036_50361001_1_dialog_content = "We've been walking for a while. How come we haven't gotten to that room yet?",
  ui_story_5036_50361001_2_dialog_content = "Eulogoz is huge, but we should still be there by now.",
  ui_story_5036_50361001_3_dialog_content = "Unless we've actually been going around in circles all this time?",
  ui_story_5036_50361001_4_dialog_content = "No idea, but this is becoming more and more unbearable.",
  ui_story_5036_50361001_5_dialog_content = "This place is creepy and gives me goosebumps.",
  ui_story_5036_50361001_6_dialog_content = "I often lose my way and go around in circles in the wild.",
  ui_story_5036_50361001_7_dialog_content = "The thing to do is to leave a trail!",
  ui_story_5036_50361001_8_dialog_content = "Good idea. Anyone have something to write with?",
  ui_story_5036_50361001_9_dialog_content = "Nope!",
  ui_story_5036_50361001_10_dialog_content = "Neither do I, but I brought this.",
  ui_story_5036_50361001_11_dialog_content = "Posters for the concert? You brought these with you?",
  ui_story_5036_50361001_12_dialog_content = "Many fans come up and ask for autographs, but they don't always have something in hand for me to sign.",
  ui_story_5036_50361001_13_dialog_content = "I bring posters to sign for them so they aren't let down.",
  ui_story_5036_50361001_14_dialog_content = "Very thoughtful of you!",
  ui_story_5036_50361001_15_dialog_content = "Being considerate of fans is one of the most basic jobs of an idol!",
  ui_story_5036_50361001_16_dialog_content = "Posters, huh? Definitely a very noticeable tracker.",
  ui_story_5036_50361001_17_dialog_content = "Anyway, I'll put one up here. Let's move on!",
  ui_story_5036_50361001_18_dialog_content = "<color=#e8d9bb>Sometime later</color>",
  ui_story_5036_50361001_19_dialog_content = "It's been a while, but nothing around us seems to have changed.",
  ui_story_5036_50361001_20_dialog_content = "Hey, isn't that the poster Goldie put up?",
  ui_story_5036_50361001_21_dialog_content = "It is! We really are just wandering in circles!",
  ui_story_5036_50361001_22_dialog_content = "Wait, something's off with this poster...",
  ui_story_5036_50361001_23_dialog_content = "How come Goldie's hair is dark in this poster? And her expression doesn't look natural...",
  ui_story_5036_50361001_24_dialog_content = "H-How could this happen? Is someone pulling a prank?",
  ui_story_5036_50361001_25_dialog_content = "This is an uncharted area in the rear section. No one else should be here other than us three.",
  ui_story_5036_50361001_26_dialog_content = "Don't tell me...",
  ui_story_5036_50361001_27_option_content = "We're being followed?!",
  ui_story_5036_50361001_28_dialog_content = "An overzealous fan, maybe? Or a scoundrel bent on sabotaging the concert?",
  ui_story_5036_50361001_29_dialog_content = "Regardless, this is rather spooky...",
  ui_story_5036_50361001_30_dialog_content = "We should get out of here.",
  ui_story_5036_50361001_31_option_content = "Eclipsites?!",
  ui_story_5036_50361001_32_dialog_content = "But didn't the Lutumi Owl put them to sleep?",
  ui_story_5036_50361001_33_dialog_content = "They should still be out.",
  ui_story_5036_50361001_34_dialog_content = "This place just doesn't feel right. Let's hurry and get out of here.",
  ui_story_5036_50361001_35_dialog_content = "But which way?",
  ui_story_5036_50361001_36_dialog_content = "Just pick a direction and keep going straight!",
  ui_story_5036_50361001_37_dialog_content = "Let's go this way!",
  ui_story_5036_50361001_38_dialog_content = "Hey, slow down for this old man!",
  ui_story_5036_50361001_39_dialog_content = "Slow down!",
  ui_story_5036_50361001_40_dialog_content = "S-Something is weird about this poster.",
  ui_story_5036_50361001_41_dialog_content = "Hey, wait for me!",
  ui_story_5036_50361001_42_dialog_content = "*Panting* Hmm, this is different from the corridors we were in.",
  ui_story_5036_50361001_43_dialog_content = "Could this be the room that Chaminade spoke of?",
  ui_story_5036_50361001_44_dialog_content = "It does seem very solid, although the wall is still in tatters from years of neglect.",
  ui_story_5036_50361001_45_dialog_content = "It also feels even creepier here. I really don't want to stick around...",
  ui_story_5036_50361001_46_dialog_content = "I keep feeling like Eclipsites are gonna turn up any second.",
  ui_story_5036_50361001_47_dialog_content = "*Rustling sounds*",
  ui_story_5036_50361001_48_dialog_content = "Who's there?!",
  ui_story_5036_50361001_49_dialog_content = "Show yourself!",
  ui_story_5036_50361001_50_dialog_content = "It's me! Don't hit me!",
  ui_story_5036_50361001_51_dialog_content = "I'm not talking about you!",
  ui_story_5036_50361001_52_dialog_content = "Huh?",
  ui_story_5036_50361001_53_dialog_content = "Brandy? What are you doing here? Hold on, watch out!",
  ui_story_5036_50361001_54_dialog_content = "Graaaaaah!",
  ui_story_5036_50361001_55_dialog_content = "Duck!",
  ui_story_5036_50361001_56_dialog_content = "Goldie?!",
  ui_story_5036_50361001_57_dialog_content = "(Goldie just saved my life!)",
  ui_story_5036_50361001_58_dialog_content = "I won't let you harm anyone in my presence!",
  ui_story_5036_50361001_59_dialog_content = "Get ready for what's coming for you!",
  ui_story_5036_50361001_60_dialog_content = "Woof!",
  ui_story_5036_50361002_1_dialog_content = "Whoa, that was close!",
  ui_story_5036_50361002_2_dialog_content = "It's okay now. I killed the last Eclipsite.",
  ui_story_5036_50361002_3_dialog_content = "Are you all right? You're not hurt, are you?",
  ui_story_5036_50361002_4_dialog_content = "I'm fine other than my legs feeling like jelly...",
  ui_story_5036_50361002_5_dialog_content = "No wonder I felt someone was watching all this time... You've been following us.",
  ui_story_5036_50361002_6_dialog_content = "What are you doing here?",
  ui_story_5036_50361002_7_dialog_content = "Don't you know stalking is illegal, Brandy? You get punished for that!",
  ui_story_5036_50361002_8_dialog_content = "I... I wasn't stalking!",
  ui_story_5036_50361002_9_dialog_content = "I'm here to uncover the truth!",
  ui_story_5036_50361002_10_dialog_content = "The truth? You're looking into the strange dreams too?",
  ui_story_5036_50361002_11_dialog_content = "No, not that. It was something else. I wanted to investigate in secret, but now that you know, I'll just ask you directly.",
  ui_story_5036_50361002_12_dialog_content = "Goldie, do you remember the owner of Star Theater?",
  ui_story_5036_50361002_13_dialog_content = "Let me think... That does ring a bell.",
  ui_story_5036_50361002_14_dialog_content = "Did Goldie beat him up too?",
  ui_story_5036_50361002_15_dialog_content = "Quit interrupting, Vic.",
  ui_story_5036_50361002_16_dialog_content = "We did work together briefly, but things ended on a sour note.",
  ui_story_5036_50361002_17_dialog_content = "So you left on bad terms? Why didn't you find another venue instead of going through all the trouble of boarding the Wandering Colossus just to hold a concert?",
  ui_story_5036_50361002_18_dialog_content = "Since then, other theater owners have all refused my offers to rent their venues.",
  ui_story_5036_50361002_19_dialog_content = "Do you know why?",
  ui_story_5036_50361002_20_dialog_content = "It's a long story.",
  ui_story_5036_50361002_21_dialog_content = "That theater owner once sent in a tip to The Daily Scoop's editor, claiming that you assaulted him.",
  ui_story_5036_50361002_X21_dialog_content = "What does that mean? Are you prone to violent outbursts?",
  ui_story_5036_50361002_22_dialog_content = "He even showed the editor the wounds on his face. His face and nose were so swollen and bruised... It looked really painful.",
  ui_story_5036_50361002_23_dialog_content = "I didn't hurt him in the least! On the contrary, he was the one hurting innocent little children!",
  ui_story_5036_50361002_24_dialog_content = "I still don't want to believe that you did it, but... I'm a reporter, so I must rely on evidence.",
  ui_story_5036_50361002_25_dialog_content = "Do you have anything to prove your innocence or prove any wrongdoing on his part?",
  ui_story_5036_50361002_26_dialog_content = "I'm telling the truth! Here, the full story should clear things up.",
  ui_story_5036_50361002_27_dialog_content = "It all started about ten days ago. At the time, I was looking for a venue to hold my next concert.",
  ui_story_5036_50361002_28_dialog_content = "After giving it a lot of thought, I decided that Star Theater was the best choice, so I approached the owner about it.",
  ui_story_5036_50361002_29_dialog_content = "I scheduled a rehearsal before my show to get accustomed to the venue.",
  ui_story_5036_50361002_30_dialog_content = "♪ La—la la la ♪",
  ui_story_5036_50361002_31_dialog_content = "<color=#e8d9bb>Slap—!</color>",
  ui_story_5036_50361002_32_dialog_content = "Ahhhhh!",
  ui_story_5036_50361002_33_dialog_content = "Help!",
  ui_story_5036_50361002_34_dialog_content = "Huh? What was that just now?",
  ui_story_5036_50361002_35_dialog_content = "Does it look like you punks belong here, huh? Scram! Beat it, all of you!",
  ui_story_5036_50361002_36_dialog_content = "Damn filthy rats, keep out of my theater!",
  ui_story_5036_50361002_37_dialog_content = "Ah!",
  ui_story_5036_50361002_38_dialog_content = "Don't you hit my brother!",
  ui_story_5036_50361002_39_dialog_content = "What's going on here?",
  ui_story_5036_50361002_40_dialog_content = "Well, if it isn't Goldie herself! There's nothing to see here, no cause for your concern.",
  ui_story_5036_50361002_41_dialog_content = "It was just a couple of penniless brats trying to catch a free show. I'll throw them out in a second.",
  ui_story_5036_50361002_42_dialog_content = "This isn't an official concert, it's just a rehearsal. What's wrong with us coming here to listen to Goldie sing?",
  ui_story_5036_50361002_43_dialog_content = "Listening ain't free, punk. Pay up, or get lost.",
  ui_story_5036_50361002_44_dialog_content = "But if you're still feeling uppity, let me put you back in your place!",
  ui_story_5036_50361002_45_dialog_content = "Agh!",
  ui_story_5036_50361002_X45_dialog_content = "Help!",
  ui_story_5036_50361002_46_dialog_content = "Stop!",
  ui_story_5036_50361002_47_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5036_50361002_48_dialog_content = "Ugh! *Coughs*",
  ui_story_5036_50361002_49_dialog_content = "How dare you touch me? Don't you know who I am? I own the Star Theater!",
  ui_story_5036_50361002_50_dialog_content = "I don't care if you're the owner! I won't let you hurt a couple of innocent children!",
  ui_story_5036_50361002_51_dialog_content = "Do you even realize what you're doing?",
  ui_story_5036_50361002_52_dialog_content = "*Coughs*",
  ui_story_5036_50361002_53_dialog_content = "Unfortunately, I won't be letting you perform in my theater anymore, Miss Goldie.",
  ui_story_5036_50361002_54_dialog_content = "... What a shame.",
  ui_story_5036_50361002_55_dialog_content = "So you jumped out to defend those kids and just accidentally knocked him to the ground?",
  ui_story_5036_50361002_56_dialog_content = "That's totally different from what everyone is saying!",
  ui_story_5036_50361002_57_dialog_content = "Those are all just baseless rumors!",
  ui_story_5036_50361002_58_dialog_content = "And another thing! When he fell to the ground, he landed on his butt, not his face!",
  ui_story_5036_50361002_59_dialog_content = "If you don't believe me, go ask those two kids about it! They'll tell you everything that happened that day.",
  ui_story_5036_50361002_60_dialog_content = "(Goldie has always been a good and just person. I don't think she would act violently for no good reason.)",
  ui_story_5036_50361002_61_dialog_content = "Why didn't you tell everyone all of this in the first place?",
  ui_story_5036_50361002_62_dialog_content = "I'm an idol, I can't afford to expose my vulnerabilities.",
  ui_story_5036_50361002_63_dialog_content = "To ruin my reputation, a number of theater owners have been colluding with one another to keep me from renting a venue for my concert.",
  ui_story_5036_50361002_64_dialog_content = "They know I promised my fans a concert here in Umbraton, and are trying to make me go back on my word.",
  ui_story_5036_50361002_65_dialog_content = "My fans will be so disappointed if I'm not able to keep my promise to them...",
  ui_story_5036_50361002_X65_dialog_content = "I may as well kiss my idol career goodbye if I do that!",
  ui_story_5036_50361002_X66_dialog_content = "That's why, no matter what, I have to hold that concert as scheduled.",
  ui_story_5036_50361002_X67_dialog_content = "I have to prove to my fans that I would never betray all the love and support they've given me!",
  ui_story_5036_50361002_66_dialog_content = "How could those people do that to you?!",
  ui_story_5036_50361002_67_dialog_content = "The only thing I can do now is to hold a one-of-a-kind concert for everyone to be able to experience the real me for themselves.",
  ui_story_5036_50361002_68_dialog_content = "As I get more popular, more and more people will be willing to listen to me and believe me!",
  ui_story_5036_50361002_69_dialog_content = "So when that incident went down, I chose to lay low and keep things to myself. I didn't want anyone to see me in a vulnerable position.",
  ui_story_5036_50361002_70_dialog_content = "(So that's what Goldie was thinking all along...)",
  ui_story_5036_50361002_71_dialog_content = "(The look in her eyes tells me that she isn't lying. Plus she even saved me from the Eclipsites.)",
  ui_story_5036_50361002_72_dialog_content = "Phew... I almost believed the rumors and took you to be some sort of bad person...",
  ui_story_5036_50361002_73_dialog_content = "I'll clarify this matter with the two kids later.",
  ui_story_5036_50361002_X73_dialog_content = "If you're telling the truth, I'll write an article about it right away. We'll clear your good name and get rid of all the rumors!",
  ui_story_5036_50361002_74_dialog_content = "I couldn't ask for anything more!",
  ui_story_5036_50361002_75_dialog_content = "Let's save the sentimental fluff for after we're done here. We still have other matters to attend to.",
  ui_story_5036_50361002_76_dialog_content = "That's right! Where are we off to next, PlayerName?",
  ui_story_5036_50361002_77_dialog_content = "I can sense that we're getting close to the place where Chaminade hid the egg.",
  ui_story_5036_50361002_78_dialog_content = "Let me try one more time.",
  ui_story_5036_50361002_79_option_content = "Mind link!",
  ui_story_5036_50361002_80_dialog_content = "Graah—!",
  ui_story_5036_50361002_81_dialog_content = "<color=#e8d9bb>Thud—!</color>",
  ui_story_5036_50361002_82_dialog_content = "Ah—!",
  ui_story_5036_50361002_83_dialog_content = "They're trying to break in... What should I do?",
  ui_story_5036_50361002_84_dialog_content = "Even the strongest room on the Colossus can't hold back all of these Eclipsites?",
  ui_story_5036_50361002_85_dialog_content = "Eulogoz? Eulogoz!",
  ui_story_5036_50361002_86_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5036_50361002_87_dialog_content = "No... Could Eulogoz already be...?",
  ui_story_5036_50361002_88_dialog_content = "No! I can't give up! I still have to protect the Ouroboros!",
  ui_story_5036_50361002_89_dialog_content = "I need to hide it somewhere safe first!",
  ui_story_5036_50361002_90_dialog_content = "No one should be able to find it inside this secret wall compartment.",
  ui_story_5036_50361002_91_dialog_content = "Stay here and don't move a muscle, okay?",
  ui_story_5036_50361002_92_dialog_content = "I-I'll protect you no matter what!",
  ui_story_5036_50361002_93_dialog_content = "<color=#e8d9bb>Wham!!!</color>",
  ui_story_5036_50361002_94_dialog_content = "<color=#e8d9bb>Boom—!</color>",
  ui_story_5036_50361002_95_dialog_content = "Graaah...",
  ui_story_5036_50361002_96_dialog_content = "Eclipsites...",
  ui_story_5036_50361002_97_dialog_content = "Come at me... Come at me, all of you!",
  ui_story_5036_50361002_98_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5036_50361002_99_dialog_content = "It hurts...",
  ui_story_5036_50361002_100_dialog_content = "My body... It feels so cold...",
  ui_story_5036_50361002_101_dialog_content = "Eulogoz... Ouroboros... Are you two still there?",
  ui_story_5036_50361002_102_dialog_content = "I... I just want to go home...",
  ui_story_5036_50361002_103_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5036_50361002_104_dialog_content = "Kree—!",
  ui_story_5036_50361101_1_dialog_content = "...",
  ui_story_5036_50361101_2_dialog_content = "PlayerName?",
  ui_story_5036_50361101_3_dialog_content = "...",
  ui_story_5036_50361101_4_dialog_content = "PlayerName! Are you okay? What did you see?",
  ui_story_5036_50361101_5_dialog_content = "I... I saw Chaminade's final memory.",
  ui_story_5036_50361101_6_dialog_content = "After the Ouroboros turned into an egg, she and Eulogoz were attacked by Eclipsites.",
  ui_story_5036_50361101_7_dialog_content = "To protect the Ouroboros' egg, she hid it in a secret compartment in the wall.",
  ui_story_5036_50361101_8_dialog_content = "After that, Chaminade drew the Eclipsites away from the room all by herself... And then...",
  ui_story_5036_50361101_9_dialog_content = "... That's enough. We understand.",
  ui_story_5036_50361101_10_dialog_content = "That poor girl fought to the bitter end to protect the Ouroboros' egg.",
  ui_story_5036_50361101_11_dialog_content = "She did well, even if it seems a bit much.",
  ui_story_5036_50361101_12_dialog_content = "Now's not the time to talk like that, Vic.",
  ui_story_5036_50361101_13_dialog_content = "What do you mean? Look inside the crack in this wall, if you don't believe me.",
  ui_story_5036_50361101_14_dialog_content = "Is there something in there?",
  ui_story_5036_50361101_15_dialog_content = "Ahhh!",
  ui_story_5036_50361101_16_dialog_content = "What do you see?",
  ui_story_5036_50361101_17_dialog_content = "What is this? It looks nothing like the pattern on the wall.",
  ui_story_5036_50361101_18_dialog_content = "It isn't made of metal or Colossus Patches. It looks more like... an eggshell.",
  ui_story_5036_50361101_19_dialog_content = "Could it belong to the Ouroboros?",
  ui_story_5036_50361101_20_dialog_content = "So it's still here, after all. But how did it get so big? It even cracked open the wall!",
  ui_story_5036_50361101_21_dialog_content = "Shouldn't it be just a little bigger than a watermelon? Even that little girl could carry it.",
  ui_story_5036_50361101_22_dialog_content = "An \"Ouroboros egg\"?! I thought Vic was just joking about that! How is this actually happening?",
  ui_story_5036_50361101_23_dialog_content = "What exactly is going on here, Vic?",
  ui_story_5036_50361101_24_dialog_content = "I have no idea...",
  ui_story_5036_50361101_25_dialog_content = "What? Aren't you supposed to be the world's leading extrozoologist?",
  ui_story_5036_50361101_26_dialog_content = "It's precisely because I'm an extrozoologist that I refuse to make any rash assumptions.",
  ui_story_5036_50361101_27_dialog_content = "The only thing I can ascertain for now is that this egg is well past its incubation period but still hasn't hatched.",
  ui_story_5036_50361101_28_dialog_content = "Not only that, the Ouroboros inside the egg is still very much alive. It keeps growing, and the egg grows with it.",
  ui_story_5036_50361101_29_dialog_content = "As for everything else, I have absolutely no clue!",
  ui_story_5036_50361101_30_dialog_content = "Ouroboros are an exceedingly rare species, so information on it is scarce at best.",
  ui_story_5036_50361101_31_dialog_content = "It's a total mystery, to put it simply.",
  ui_story_5036_50361101_32_dialog_content = "All this time, I thought Vic was just making things up. I had no idea he was being serious.",
  ui_story_5036_50361101_33_dialog_content = "Do you think this egg is the source of everyone's strange dreams?",
  ui_story_5036_50361101_34_dialog_content = "It's possible!",
  ui_story_5036_50361101_35_dialog_content = "You really think so?",
  ui_story_5036_50361101_36_dialog_content = "I don't have any proof, so it's just a guess.",
  ui_story_5036_50361101_37_dialog_content = "I've always been curious to know how the Ouroboros survives its incubation period as an egg.",
  ui_story_5036_50361101_38_dialog_content = "How is an egg supposed to fight off predators or run away from them?",
  ui_story_5036_50361101_39_dialog_content = "But now, I've come up with a new hypothesis! I believe that the Ouroboros may possess a unique psychic ability while in its egg state.",
  ui_story_5036_50361101_40_dialog_content = "One that can cause other creatures to experience strange dreams or hallucinations! By making them sense danger, the Ouroboros can keep them at a safe distance.",
  ui_story_5036_50361101_41_dialog_content = "It protects itself in this way to ward off dangers.",
  ui_story_5036_50361101_42_dialog_content = "So you're saying the strange dreams we've been having, and that strange sense of discomfort...",
  ui_story_5036_50361101_43_dialog_content = "Or even that weird poster from earlier. All of that was the Ouroboros' doing?!",
  ui_story_5036_50361101_44_dialog_content = "Indeed. Or rather, that's the most reasonable explanation I can think of!",
  ui_story_5036_50361101_45_dialog_content = "So our next move is obvious, right? We need to find a way to move this egg somewhere far away!",
  ui_story_5036_50361101_46_option_content = "This egg?",
  ui_story_5036_50361101_47_option_content = "Move it?",
  ui_story_5036_50361101_48_dialog_content = "Yep!",
  ui_story_5036_50361101_49_dialog_content = "If we don't get this egg out of here, the Ouroboros' power will only keep affecting everyone.",
  ui_story_5036_50361101_50_dialog_content = "And at this rate, it will definitely impact my concert!",
  ui_story_5036_50361101_51_dialog_content = "I disagree.",
  ui_story_5036_50361101_52_dialog_content = "What?!",
  ui_story_5036_50361101_53_dialog_content = "The egg is colossal, and it's stuck in the wall.",
  ui_story_5036_50361101_54_dialog_content = "Even if you manage to extricate it, how do you intend to transport it someplace else safely?",
  ui_story_5036_50361101_55_dialog_content = "I'll hire the White Flame Mercenaries to dig it out and take it away on an airship!",
  ui_story_5036_50361101_56_dialog_content = "These walls aren't exactly made of sticks and stones, you know? By the time you finish digging it out, the concert will have been over for a long time.",
  ui_story_5036_50361101_57_dialog_content = "I...",
  ui_story_5036_50361101_58_dialog_content = "Not to mention, this may very well be the one and only Ouroboros egg left in the entire world, given how rare exotics are.",
  ui_story_5036_50361101_59_dialog_content = "If something were to happen to it during the extrication, the Ouroboros' life could be put at risk.",
  ui_story_5036_50361101_60_dialog_content = "If that happens, will you be ready to shoulder the blame for causing the extinction of an entire species of wondrous beasts?",
  ui_story_5036_50361101_61_dialog_content = "I...",
  ui_story_5036_50361101_62_dialog_content = "Why not take my advice and call off this concert?",
  ui_story_5036_50361101_63_dialog_content = "You can hold a concert anywhere else at any time. It would only be this once, so let's just wait for the Ouroboros to hatch, and—",
  ui_story_5036_50361101_64_dialog_content = "No way!",
  ui_story_5036_50361101_65_dialog_content = "This concert is <color=#FFB400>especially important</color> to me! I can't give up on it just like that!",
  ui_story_5036_50361101_66_dialog_content = "I can compromise in any other situation, but not this one!",
  ui_story_5036_50361101_67_dialog_content = "It's true, this concert is something Goldie promised to her fans...",
  ui_story_5036_50361101_68_dialog_content = "(\"Especially important\"? Goldie looks really distressed right now. What is going on?)",
  ui_story_5036_50361101_69_dialog_content = "Ah, then it looks like we have a slight dilemma on our hands.",
  ui_story_5036_50361101_70_dialog_content = "...",
  ui_story_5036_50361101_71_dialog_content = "(Neither of them is willing to back down. I have to do something about this.)",
  ui_story_5036_50361101_72_dialog_content = "Is there really no other way?",
  ui_story_5036_50361101_73_dialog_content = "Maybe we can get rid of the egg's psychic influence without moving it?",
  ui_story_5036_50361101_74_dialog_content = "That's right! You're the expert extrozoologist, Vic. Can't you think of a better way?",
  ui_story_5036_50361101_75_dialog_content = "Sigh. As usual, you brats sure love making an old man suffer. They just get worse generation after generation...",
  ui_story_5036_50361101_76_dialog_content = "Ah well, guess it can't be helped. My apprentices are always begging me to save their sorry butts. This is no different, I suppose.",
  ui_story_5036_50361101_77_dialog_content = "Interesting choice of words, Vic. I wonder what Shira and Fia would think of them.",
  ui_story_5036_50361101_78_dialog_content = "Sorry, what? Did I say something? I can't seem to remember!",
  ui_story_5036_50361101_79_dialog_content = "Oh, stop acting, Vic. Let's get on with this.",
  ui_story_5036_50361101_80_dialog_content = "Ahem. There is another method, but it's a little troublesome, and I can't guarantee it'll work.",
  ui_story_5036_50361101_81_dialog_content = "Just tell us already! I'll do anything, so long as it gives me a chance to hold this concert!",
  ui_story_5036_50361101_82_dialog_content = "Tell me about the vision you saw a few minutes ago, PlayerName. Did Chaminade seem to be negatively affected by the Ouroboros egg in any way?",
  ui_story_5036_50361101_83_dialog_content = "Huh? Now that I think about it... No, she really didn't seem bothered by it at all.",
  ui_story_5036_50361101_84_dialog_content = "I see. Therein lies the answer, my friends!",
  ui_story_5036_50361101_85_dialog_content = "The Ouroboros' psychic abilities appear to be a self-defense mechanism that it only uses when it senses danger nearby.",
  ui_story_5036_50361101_86_dialog_content = "If we can remove the source of that danger from the Colossus, it should feel safe enough to dispel its psychic influence!",
  ui_story_5036_50361101_87_dialog_content = "So you're saying we just have to clear out the Eclipsites on the Colossus?",
  ui_story_5036_50361101_88_dialog_content = "That's one way of putting it, yes.",
  ui_story_5036_50361101_89_dialog_content = "Is that all? That's not a problem for us!",
  ui_story_5036_50361101_90_dialog_content = "N-Now wait just a minute!",
  ui_story_5036_50361101_91_dialog_content = "This Colossus is, well, colossal! How are we supposed to take out every single Eclipsite with just the four of us?! It's impossible!",
  ui_story_5036_50361101_92_dialog_content = "You have a point...",
  ui_story_5036_50361101_93_dialog_content = "Plus there's a chance that this won't even work, right?",
  ui_story_5036_50361101_94_dialog_content = "Correct. But we won't find out unless we try!",
  ui_story_5036_50361101_95_dialog_content = "What if we try eliminating the Eclipsites in the immediate vicinity, and then seal up all the cracks in the walls? That way, they won't have any way of getting near the egg!",
  ui_story_5036_50361101_96_dialog_content = "Hmm, that might produce a similar result, yes.",
  ui_story_5036_50361101_97_dialog_content = "Let's give it a go!",
  ui_story_5036_50361101_98_dialog_content = "Alright, let's move out!",
  ui_story_5036_50361101_99_dialog_content = "For the concert!",
  ui_story_5036_50361102_1_dialog_content = "Come give me a hand over here, PlayerName.",
  ui_story_5036_50361102_2_dialog_content = "Let's push this rock over there and block off that crack in the wall.",
  ui_story_5036_50361102_3_dialog_content = "Roger!",
  ui_story_5036_50361102_4_dialog_content = "Hrrrnnnng—!",
  ui_story_5036_50361102_5_dialog_content = "Phew! That ought to be the last crack, right?",
  ui_story_5036_50361102_6_dialog_content = "Looks like it! Excellent work, everyone.",
  ui_story_5036_50361102_7_dialog_content = "Another successful venture under my flawless leadership!",
  ui_story_5036_50361102_8_dialog_content = "If you can call sitting around and cheering for us \"leadership,\" then sure...",
  ui_story_5036_50361102_9_dialog_content = "Did you really expect that an old geezer like me to keep up with a bunch of spring chickens like you?",
  ui_story_5036_50361102_10_dialog_content = "The gloomy atmosphere appears to be weakening...",
  ui_story_5036_50361102_11_dialog_content = "You're right. Even though I can still faintly sense it, it feels a lot better now than before.",
  ui_story_5036_50361102_12_dialog_content = "Then it looks like my hypothesis was correct!",
  ui_story_5036_50361102_13_dialog_content = "So what do we do now? Should we keep clearing out the Eclipsites?",
  ui_story_5036_50361102_14_dialog_content = "I think we've done more than enough at this point. The only thing left to do now...",
  ui_story_5036_50361102_15_dialog_content = "is to go crawl back into bed to see if we have any more strange dreams!",
  ui_story_5036_50361102_16_dialog_content = "You just want to go to bed, don't you?!",
  ui_story_5036_50361102_17_dialog_content = "Sorry, but since there's so little info on the Ouroboros, trial and error is our only choice.",
  ui_story_5036_50361102_18_dialog_content = "He has a point.",
  ui_story_5036_50361102_19_dialog_content = "It's gotten really late, and everyone looks exhausted.",
  ui_story_5036_50361102_20_dialog_content = "Let's go back and get some rest, and see if our efforts paid off.",
  ui_story_5036_50361102_21_dialog_content = "And if they haven't, I'll think of something else.",
  ui_story_5036_50361102_22_dialog_content = "I think all your hard work will definitely pay off, Goldie!",
  ui_story_5036_50361102_23_dialog_content = "Heehee! Thanks for saying so!",
  ui_story_5036_50361102_24_dialog_content = "Alright then, let's head back for some much-needed sleep. We'll meet up again in the morning!",
  ui_story_5036_50361102_25_dialog_content = "<color=#e8d9bb>The next morning, one day before the concert</color>",
  ui_story_5036_50361102_26_dialog_content = "Yaaaawn... I haven't gotten a good night's sleep like that in a long time!",
  ui_story_5036_50361102_27_dialog_content = "I was so beat after last night, I passed out as soon as I got to my room. I was too tired to even dream!",
  ui_story_5036_50361102_28_dialog_content = "Morning, my defeated rival!",
  ui_story_5036_50361102_29_dialog_content = "If you just woke up, that means I won the wake-up game today! Awesome!",
  ui_story_5036_50361102_30_dialog_content = "Hey, Gronru. Did you sleep well last night?",
  ui_story_5036_50361102_31_dialog_content = "I got some real S-tier snoozing done last night!",
  ui_story_5036_50361102_32_dialog_content = "Nothing compared to the last few nights, where I kept dreaming about that Caelestite girl.",
  ui_story_5036_50361102_33_dialog_content = "Really? That's wonderful news!",
  ui_story_5036_50361102_34_dialog_content = "You think so? I don't. Having weird dreams like that is kind of like unlocking a hidden achievement in a game!",
  ui_story_5036_50361102_35_dialog_content = "Uh, yeah, sure... Anyway, I'm glad that you were able to get some decent rest.",
  ui_story_5036_50361102_36_dialog_content = "Thanks! I'm off to watch the rehearsal, catch you later!",
  ui_story_5036_50361102_37_dialog_content = "Alright, see you!",
  ui_story_5036_50361102_38_dialog_content = "This is great! It looks like all our hard work last night wasn't in vain!",
  ui_story_5036_50361102_39_dialog_content = "I should go tell Goldie right away, so she can finally relax a little.",
  ui_story_5036_50361102_40_dialog_content = "Right now, she should be... in the training room, I think?",
  ui_story_5036_50361102_41_dialog_content = "Oh, hey PlayerName!",
  ui_story_5036_50361102_42_dialog_content = "You're up already? We were out so late last night I thought you might want to get a little extra sleep today.",
  ui_story_5036_50361102_43_dialog_content = "Not at all! I feel completely refreshed now!",
  ui_story_5036_50361102_44_dialog_content = "Also, it looks like our hard work paid off. I just talked to Gronru, and she said she didn't have any weird dreams last night!",
  ui_story_5036_50361102_45_dialog_content = "That's good! I also asked a few contestants, and they all said they slept fine last night too!",
  ui_story_5036_50361102_46_dialog_content = "This is perfect!",
  ui_story_5036_50361102_47_dialog_content = "It really is... perfect.",
  ui_story_5036_50361102_48_option_content = "Goldie? Are you okay?",
  ui_story_5036_50361102_49_dialog_content = "Why do you look so fatigued?",
  ui_story_5036_50361102_50_dialog_content = "Huh? Do I?",
  ui_story_5036_50361102_51_dialog_content = "I don't feel exhausted at all! Idols are bursting with tons of energy, after all!",
  ui_story_5036_50361102_52_option_content = "Why do you look so exhausted?",
  ui_story_5036_50361102_53_dialog_content = "Huh? Do I?",
  ui_story_5036_50361102_54_dialog_content = "I think you might be seeing things. I feel perfectly fine right now!",
  ui_story_5036_50361102_55_dialog_content = "(I swear I'm not seeing things. That expression just now... Could it be?)",
  ui_story_5036_50361102_56_dialog_content = "You're forcing yourself to keep your spirits up, aren't you?",
  ui_story_5036_50361102_57_dialog_content = "...!",
  ui_story_5036_50361102_58_dialog_content = "It's not hard to tell. After all, you were out just as late as we were last night.",
  ui_story_5036_50361102_59_dialog_content = "What's more, you had to arrange for training and auditioning today, right? It doesn't look like you got any rest at all last night.",
  ui_story_5036_50361102_60_dialog_content = "It's fine, I promise! I'm an idol, remember? And idols—",
  ui_story_5036_50361102_61_option_content = "—are people, too, right?",
  ui_story_5036_50361102_62_dialog_content = "You're still people. You need your rest too.",
  ui_story_5036_50361102_63_dialog_content = "I may not know the full story behind this concert or why it's so important to you...",
  ui_story_5036_50361102_64_dialog_content = "But I do know that you should set your work aside for a bit and get some rest right now, Goldie.",
  ui_story_5036_50361102_65_dialog_content = "Sigh.",
  ui_story_5036_50361102_66_dialog_content = "I suppose it wouldn't hurt to tell you the truth, PlayerName. After all, you've done so much to help me already.",
  ui_story_5036_50361102_67_dialog_content = "Huh? Did you just say \"the truth\"?",
  ui_story_5036_50361102_X67_dialog_content = "I'm not just fulfilling my promise to my fans with this concert... I'm fulfilling my promise to Lady Sheol, as well.",
  ui_story_5036_50361102_68_dialog_content = "To be completely honest with you, I sort of made a pact with Sheol.",
  ui_story_5036_50361102_69_dialog_content = "A pact? With Sheol?!",
  ui_story_5036_50361102_70_dialog_content = "She recognized the potential of the idol industry, as well as my own abilities. So she decided to invest in my career.",
  ui_story_5036_50361102_71_dialog_content = "She's my biggest source of financial backing, but at the same time, I have to do everything in my power to comply with her demands.",
  ui_story_5036_50361102_72_dialog_content = "One of which was to host a concert here in Umbraton within a certain period of time, and that concert—",
  ui_story_5036_50361102_73_dialog_content = "It has to enlighten everyone in Umbraton and Lumopolis about the concept of an idol, and spread my name throughout the region.",
  ui_story_5036_50361102_74_dialog_content = "Don't you think Sheol is taking advantage of you? Is that goal even possible?!",
  ui_story_5036_50361102_75_dialog_content = "I admit that it won't be easy for someone with my level of popularity. But nothing is impossible as long as I plan everything perfectly.",
  ui_story_5036_50361102_76_dialog_content = "But then you know, all that stuff happened, so I couldn't rent a venue.",
  ui_story_5036_50361102_77_dialog_content = "But just when all hope appeared to be lost, the Wandering Colossus suddenly appeared in the sky! Its arrival was so fortuitous!",
  ui_story_5036_50361102_78_dialog_content = "According to my pact with Sheol, tomorrow is the last day I can hold my concert. It's my final chance, so I have to give it my all.",
  ui_story_5036_50361102_79_dialog_content = "If I fail, I'll have to repay Sheol for all her expenditures. I'll be under a mountain of debt.",
  ui_story_5036_50361102_80_dialog_content = "My career as an idol will also be over.",
  ui_story_5036_50361102_81_dialog_content = "I had no idea you were working under this much pressure, Goldie. Isn't it all too much?",
  ui_story_5036_50361102_82_dialog_content = "I don't think so. It's my duty, after all.",
  ui_story_5036_50361102_83_dialog_content = "As an idol, my entire reason for being is to bring hope and happiness to my loyal fans through song and dance.",
  ui_story_5036_50361102_84_dialog_content = "Without their love and support, I could never call myself an idol.",
  ui_story_5036_50361102_85_dialog_content = "After all the love they've shown me, what kind of person would I be if I didn't repay them by working as hard as I could?",
  ui_story_5036_50361102_86_dialog_content = "I'll risk it all if it means my concert will help my voice reach even more people!",
  ui_story_5036_50361102_87_dialog_content = "I know you can do it, Goldie!",
  ui_story_5036_50361102_88_dialog_content = "But you're not alone. You have me, too!",
  ui_story_5036_50361102_89_dialog_content = "If there's anything I can do to help, all you have to do is ask.",
  ui_story_5036_50361102_90_dialog_content = "Thank you, PlayerName!",
  ui_story_5036_50361102_91_dialog_content = "Let's do our best to protect Eulogoz and make this concert the greatest the world has ever seen!",
  ui_story_5036_50361201_1_dialog_content = "<color=#e8d9bb>The next day, fifteen minutes before the start of the concert</color>",
  ui_story_5036_50361201_2_dialog_content = "The concert's about to start! Everybody ready?",
  ui_story_5036_50361201_3_dialog_content = "Ready!",
  ui_story_5036_50361201_4_dialog_content = "Is the show finally starting? It's the moment we've all been waiting for!",
  ui_story_5036_50361201_5_dialog_content = "(Honestly, making me waste my valuable time consorting with these commoners.)",
  ui_story_5036_50361201_6_dialog_content = "Expression, revealing.",
  ui_story_5036_50361201_7_dialog_content = "Presence of rude and demeaning thoughts is clearly visible on your face.",
  ui_story_5036_50361201_8_dialog_content = "Oh, shut up.",
  ui_story_5036_50361201_9_dialog_content = "Awesome! The game is about to start!",
  ui_story_5036_50361201_10_dialog_content = "Ready to help me cheer them on, Sio?",
  ui_story_5036_50361201_11_dialog_content = "R-Ready...",
  ui_story_5036_50361201_12_dialog_content = "Why haven't we started yet? I'm dying to knock the socks off this crowd with my rock music!",
  ui_story_5036_50361201_13_dialog_content = "Get real, you moron! This is an idol concert, not a rock concert! The most important thing here is the idol!",
  ui_story_5036_50361201_14_dialog_content = "Which is why I, Barbara the Diesel Sweety, was made for this!",
  ui_story_5036_50361201_15_dialog_content = "Who would want to listen to kiddy music like yours? The crowd doesn't want to hear that junk!",
  ui_story_5036_50361201_16_dialog_content = "What was that?!",
  ui_story_5036_50361201_17_dialog_content = "Those two are just as lively as ever. I hope they don't cause any problems for us.",
  ui_story_5036_50361201_18_dialog_content = "Agreed. After all, they have to perform the opening act together!",
  ui_story_5036_50361201_19_dialog_content = "Yeah, I know what you... Wait, WHAT?! Opening act? Together?!",
  ui_story_5036_50361201_20_dialog_content = "Are you sure that's okay?!",
  ui_story_5036_50361201_21_dialog_content = "I won't lie, I'm a little worried about it too. But if I let them perform separately, they'll just fight over who gets to go first.",
  ui_story_5036_50361201_22_dialog_content = "By making them go onstage at the same time, at least the concert will proceed somewhat smoothly.",
  ui_story_5036_50361201_23_dialog_content = "Besides, they both swore they would put on a killer opening act for the concert!",
  ui_story_5036_50361201_24_dialog_content = "Oh, it'll be \"killer,\" alright... Just not sure what it's gonna skill...",
  ui_story_5036_50361201_25_dialog_content = "Have a little faith in them! I know they bicker all the time, but there's no denying their skills or their dedication to their performances.",
  ui_story_5036_50361201_26_dialog_content = "Fine, I just hope they can share the stage long enough to get through their act.",
  ui_story_5036_50361201_27_dialog_content = "After all, Eulogoz has everything riding on this concert, too.",
  ui_story_5036_50361201_28_dialog_content = "You really care about Eulogoz, don't you?",
  ui_story_5036_50361201_29_dialog_content = "That's because it's the only fully-operational Colossus in the world, aside from Soroz and Lepidoz.",
  ui_story_5036_50361201_30_dialog_content = "The Caelestites share a close bond with every single Colossus. They're proof that my people once existed.",
  ui_story_5036_50361201_31_dialog_content = "I want to do my best to preserve them as much as possible. I know the other Caelestites would have liked that...",
  ui_story_5036_50361201_32_dialog_content = "Not to mention that if we fix Eulogoz, Soroz will finally have another companion. It wouldn't feel so lonely.",
  ui_story_5036_50361201_33_dialog_content = "Don't worry, PlayerName. I'll do my best for your sake, as well as theirs!",
  ui_story_5036_50361201_34_dialog_content = "We'll help, too!",
  ui_story_5036_50361201_35_dialog_content = "If anything truly goes awry, I'll be there to maintain order.",
  ui_story_5036_50361201_36_dialog_content = "As always, Carleen's got everything under control!",
  ui_story_5036_50361201_37_dialog_content = "Wow, you two look totally ready for this concert.",
  ui_story_5036_50361201_38_dialog_content = "Of course! We even prepared a secret weapon just for the occasion!",
  ui_story_5036_50361201_39_dialog_content = "Which song are you going to do together?",
  ui_story_5036_50361201_40_dialog_content = "We were originally going to sing a song from our student days, but when we rehearsed it, something felt missing.",
  ui_story_5036_50361201_41_dialog_content = "It didn't fully capture everything about our travels, hardships, or moments of joy.",
  ui_story_5036_50361201_42_dialog_content = "That's right! And when I asked her about it, I realized we both felt the same way!",
  ui_story_5036_50361201_43_dialog_content = "That's why we decided to write an entirely new song for the show!",
  ui_story_5036_50361201_44_dialog_content = "Wow, I can't wait to hear it!",
  ui_story_5036_50361201_45_dialog_content = "Regina, Barbara, Carleen, Vice, Vic...",
  ui_story_5036_50361201_46_dialog_content = "Wait, where's Vic?",
  ui_story_5036_50361201_47_dialog_content = "Vic? Now that you mention it, I noticed his room was empty when I passed it on the way here.",
  ui_story_5036_50361201_48_dialog_content = "I thought he came early?",
  ui_story_5036_50361201_49_dialog_content = "You haven't seen him either then?",
  ui_story_5036_50361201_50_dialog_content = "Oh for heaven's sake, the concert's about to start! Where could he have run off to?",
  ui_story_5036_50361201_51_dialog_content = "Maybe he went back to check on the Ouroboros egg?",
  ui_story_5036_50361201_52_dialog_content = "Sometimes, he cares a lot more about wondrous beasts than he does other people, and there's also his tendency to fall asleep randomly.",
  ui_story_5036_50361201_53_dialog_content = "There's a good chance he overslept over there.",
  ui_story_5036_50361201_54_dialog_content = "But don't worry, I'll bring him back.",
  ui_story_5036_50361201_55_dialog_content = "By yourself? Are you sure?",
  ui_story_5036_50361201_56_dialog_content = "I'll be fine. Just leave it to me!",
  ui_story_5036_50361201_57_dialog_content = "They filled us in. It's in the lockdown area, isn't it?",
  ui_story_5036_50361201_58_dialog_content = "That place is too dangerous! I'm going with you!",
  ui_story_5036_50361201_59_dialog_content = "Count me in as well.",
  ui_story_5036_50361201_60_dialog_content = "It's pretty far from the stage. Going there and back would definitely take a while.",
  ui_story_5036_50361201_61_dialog_content = "If you two still plan on performing, you'd better just stay here and get ready.",
  ui_story_5036_50361201_62_dialog_content = "But how can you handle those Eclipsites on your own?",
  ui_story_5036_50361201_63_dialog_content = "You don't have to worry about that, Carleen. Goldie, Vic, and I already got rid of every Eclipsite between here and there.",
  ui_story_5036_50361201_64_dialog_content = "I should be fine if I go by myself.",
  ui_story_5036_50361201_65_dialog_content = "If you say so, just be quick about it And be careful!",
  ui_story_5036_50361201_66_dialog_content = "I will, don't worry.",
  ui_story_5036_50361201_67_dialog_content = "Alright, folks! It's time to get our concert started!",
  ui_story_5036_50361201_68_dialog_content = "If Vic doesn't make it back in time, you two will have to go onstage a little earlier than scheduled, got it?",
  ui_story_5036_50361201_69_dialog_content = "Yup! Got it!",
  ui_story_5036_50361201_70_dialog_content = "Understood.",
  ui_story_5036_50361201_71_dialog_content = "It still hasn't started?",
  ui_story_5036_50361201_72_dialog_content = "I think they're about to! Look over there!",
  ui_story_5036_50361201_73_dialog_content = "The moment has finally come, everyone! Sorry to have kept you all waiting!",
  ui_story_5036_50361201_74_dialog_content = "\"The Moment the Stars Shine Brightest\" Sky Concert, is finally about to begin!",
  ui_story_5036_50361201_75_dialog_content = "Woooooo!!!",
  ui_story_5036_50361201_76_dialog_content = "<color=#e8d9bb>Meanwhile</color>",
  ui_story_5036_50361201_77_dialog_content = "Hmm? What could that be?",
  ui_story_5036_50361201_78_dialog_content = "Something shiny is passing through the clouds... Is that a Colossus?!",
  ui_story_5036_50361201_79_dialog_content = "There seems to be music coming from it. That voice said something about a Sky Concert, right?",
  ui_story_5036_50361201_80_dialog_content = "Allow me to clarify, Miss. As you may or may not know, that is the Wandering Colossus that recently arrived from Eternal Night.",
  ui_story_5036_50361201_81_dialog_content = "It would seem that an idol named Goldie is hosting a concert aboard it.",
  ui_story_5036_50361201_82_dialog_content = "Every paper in Umbraton is abuzz with news of this concert.",
  ui_story_5036_50361201_83_dialog_content = "Is that so? How very amusing.",
  ui_story_5036_50361201_84_dialog_content = "Come, let us find a good viewing angle and see what the commotion is all about!",
  ui_story_5036_50361201_85_dialog_content = "As you wish, milady.",
  ui_story_5036_50361201_86_dialog_content = "Look up there, sis! It's a Colossus!",
  ui_story_5036_50361201_87_dialog_content = "Wow! A real Colossus!",
  ui_story_5036_50361201_88_dialog_content = "Wait, on top of the Colossus, is that a screen? It looks like it's playing something...",
  ui_story_5036_50361201_89_dialog_content = "Hey! Isn't that the girl who protected us from the theater owner that day?!",
  ui_story_5036_50361201_90_dialog_content = "It IS her! So she found a place to hold her concert after all! And on a Colossus, no less!",
  ui_story_5036_50361201_91_dialog_content = "Even though we don't have tickets, we can see and hear everything as clear as day. She's incredible, huh sis?",
  ui_story_5036_50361201_92_dialog_content = "It's flying over there! Come on, let's catch up to it!",
  ui_story_5036_50361201_93_dialog_content = "We'll follow the river and cheer her on all the way!",
  ui_story_5036_50361201_94_dialog_content = "I can feel everyone's enthusiasm already!",
  ui_story_5036_50361201_95_dialog_content = "For our opening act, we have two hot idols from an even hotter place—the Rediesel Desert, bringing you a passionate and fiery performance!",
  ui_story_5036_50361201_96_dialog_content = "Let's give it up for Regina and Barbara!",
  ui_story_5036_50361201_97_dialog_content = "♪ Incinerate, burn it all to the ground—♪",
  ui_story_5036_50361201_98_dialog_content = "♪ I offer you all of my love—♪",
  ui_story_5036_50361201_99_dialog_content = "<size=40>♪ Burst! Blast! Break it down to pieces! ♪</size>",
  ui_story_5036_50361201_100_dialog_content = "<size=45>♪ Hear the beating of my heart, which longs to see you again ♪</size>",
  ui_story_5036_50361201_101_dialog_content = "(Dammit, why's her voice so loud?!)",
  ui_story_5036_50361201_102_dialog_content = "(I won't let her beat me!!!)",
  ui_story_5036_50361201_103_dialog_content = "<size=40>♪ This, is my—♪</size>",
  ui_story_5036_50361201_104_dialog_content = "<size=45>♪ My only wish, to be your—♪</size>",
  ui_story_5036_50361201_105_dialog_content = "<size=50>♪ Rock 'n' Roll!!! ♪</size>",
  ui_story_5036_50361201_106_dialog_content = "<size=50>♪ Idol!!! ♪</size>",
  ui_story_5036_50361201_107_dialog_content = "What the hell is this noise?! It's so loud, and I can't make out anything they're saying!",
  ui_story_5036_50361201_108_dialog_content = "Ugh, it feels like my ears are about to explode. Turn their mics off!",
  ui_story_5036_50361201_109_dialog_content = "Are you kidding me?! They promised not to fight onstage!",
  ui_story_5036_50361201_110_dialog_content = "This won't do... If things carry on like this, the performance will be a disaster. I have to get them back on track!",
  ui_story_5036_50361201_111_dialog_content = "♪ Feel my heart, how it's beating and burning, just like the desert sun—♪",
  ui_story_5036_50361201_112_dialog_content = "(Wait, what's the host doing on the stage? And why's she singing?!)",
  ui_story_5036_50361201_113_dialog_content = "(This wasn't part of the rehearsal!)",
  ui_story_5036_50361201_114_dialog_content = "(I hope they get the message. Come on, lady luck, don't fail me now!)",
  ui_story_5036_50361201_115_dialog_content = "♪ All I want, is for you to hear me and feel how I feel! And that's—♪",
  ui_story_5036_50361201_116_dialog_content = "♪ That's—♪",
  ui_story_5036_50361201_117_dialog_content = "♪ That's—♪",
  ui_story_5036_50361201_118_dialog_content = "<size=45>♪ Love—!!!♪</size>",
  ui_story_5036_50361201_119_dialog_content = "♪ Love that never burns away! ♪",
  ui_story_5036_50361201_120_dialog_content = "♪ Love that's always here to stay! ♪",
  ui_story_5036_50361201_121_dialog_content = "<size=50>♪ Love like the Rediesel's endless sands—♪</size>",
  ui_story_5036_50361201_122_dialog_content = "(It worked! Those two are finally back in sync!)",
  ui_story_5036_50361201_123_dialog_content = "(Now to make my exit.)",
  ui_story_5036_50361201_124_dialog_content = "♪ With my righteous rock that can't be stopped— ♪",
  ui_story_5036_50361201_125_dialog_content = "♪ I'll reach out a hand and touch your heart— ♪",
  ui_story_5036_50361201_126_dialog_content = "<size=50>♪ Let our song ring out to the skies above—♪</size>",
  ui_story_5036_50361201_127_dialog_content = "Huh? Hey, they're starting to sound pretty good!",
  ui_story_5036_50361201_128_dialog_content = "Goldie's poses are incredible! I better take as many pictures as I can!",
  ui_story_5036_50361201_129_dialog_content = "Despite how different their melodies are, the two of them are singing in perfect harmony. Just look at the crowd that's gathered!",
  ui_story_5036_50361201_130_dialog_content = "Astounding! I don't believe Lumopolis has ever hosted a concert such as this!",
  ui_story_5036_50361201_131_dialog_content = "It appears the Colossus is flying away now, Miss.",
  ui_story_5036_50361201_132_dialog_content = "Quick! To my private airship!",
  ui_story_5036_50361201_133_dialog_content = "?!?",
  ui_story_5036_50361201_134_dialog_content = "How could I possibly miss out on such an amazing concert? Hurry!",
  ui_story_5036_50361201_135_dialog_content = "Holding a concert on a Colossus for the world to see. I don't think anyone's ever done it before!",
  ui_story_5036_50361201_136_dialog_content = "More and more people are gathering.",
  ui_story_5036_50361201_137_dialog_content = "Even the merchants are starting to rent their ships for people to view the concert from the Gold River.",
  ui_story_5036_50361201_138_dialog_content = "Heheheh. It seems I was right to invest in this girl's dream, after all.",
  ui_story_5036_50361201_139_dialog_content = "Are Vic and PlayerName back yet?",
  ui_story_5036_50361201_140_dialog_content = "Not yet.",
  ui_story_5036_50361201_141_dialog_content = "I'm beginning to worry about those two...",
  ui_story_5036_50361201_142_dialog_content = "Looks like we don't have a choice but to let you two get on the stage first.",
  ui_story_5036_50361201_143_dialog_content = "On it!",
  ui_story_5036_50361201_144_dialog_content = "Let's give a round of applause to Regina and Barbara for their wonderful performance!",
  ui_story_5036_50361201_145_dialog_content = "The show's starting to heat up. My heart is practically beating out of my chest!",
  ui_story_5036_50361201_146_dialog_content = "Next up, we have two of the brightest stars in all of Astra ready to make their grand debut!",
  ui_story_5036_50361201_147_dialog_content = "An unlikely duo: one is a knight of Lumopolis, and the other is an officer of the Illumina Federation!",
  ui_story_5036_50361201_148_dialog_content = "But despite their differing factions, they've become the closest friends and have gone on countless adventures together with the legendary Caelestite!",
  ui_story_5036_50361201_149_dialog_content = "Today, they would like to share their song with all of you, a song that captures the beauty and excitement of all their travels together!",
  ui_story_5036_50361201_150_dialog_content = "Put your hands together for Carleen and Vice—!",
  ui_story_5036_50361201_151_dialog_content = "Wow, just look at all those people. If only PlayerName was here...",
  ui_story_5036_50361201_152_dialog_content = "Don't be nervous. We'll be fine.",
  ui_story_5036_50361201_153_dialog_content = "You're right! Let's go, Carleen!",
  ui_story_5036_50361201_154_dialog_content = "♪ An unimaginable journey ♪",
  ui_story_5036_50361201_155_dialog_content = "♪ A road not found on any map ♪",
  ui_story_5036_50361201_156_dialog_content = "♪ Tell me, what could lie ahead? ♪",
  ui_story_5036_50361201_157_dialog_content = "♪ A sense of wonder ♪",
  ui_story_5036_50361201_158_dialog_content = "♪ We've walked side by side, since the day we met ♪",
  ui_story_5036_50361201_159_dialog_content = "♪ No matter the distance, we'll always meet again! ♪",
  ui_story_5036_50361201_160_dialog_content = "♪ My dearest companion ♪",
  ui_story_5036_50361201_161_dialog_content = "♪ From strangers to friends! ♪",
  ui_story_5036_50361201_162_dialog_content = "♪ A lifelong companion, a light without end! ♪",
  ui_story_5036_50361201_163_dialog_content = "♪ We sail through the sky as two comets entwined ♪",
  ui_story_5036_50361201_164_dialog_content = "Thank goodness Gronru had the foresight to set up a signal transmitter before the concert began. Now we can all enjoy the music, even from over here.",
  ui_story_5036_50361201_165_dialog_content = "I have to say, this new form of entertainment is quite worthy of consideration.",
  ui_story_5036_50361201_166_dialog_content = "Perhaps we can even run similar trials in the Undercities someday. What do you say, Grand Marshal?",
  ui_story_5036_50361201_167_dialog_content = "Very well. I'll allow it.",
  ui_story_5036_50361201_168_dialog_content = "R-Really? Great!",
  ui_story_5036_50361201_169_dialog_content = "Why do you look so surprised?",
  ui_story_5036_50361201_170_dialog_content = "I was just worried that you wouldn't approve of this kind of entertainment, that's all.",
  ui_story_5036_50361201_171_dialog_content = "Hahaha! Of course, I do have my consideration about this sort of thing... but listen closely to the music.",
  ui_story_5036_50361201_172_dialog_content = "I may not have much talent when it comes to singing, but even I can tell that right now, in this very moment, Vice is brimming with happiness.",
  ui_story_5036_50361201_173_dialog_content = "It's just the kind of feeling we need, isn't it?",
  ui_story_5036_50361201_174_dialog_content = "I can just barely hear Lady Carleen and Vice singing, even from over here...",
  ui_story_5036_50361201_175_dialog_content = "They sound amazing! That's Lady Carleen for you!",
  ui_story_5036_50361201_176_dialog_content = "Raphael, stay here and guard this place with extra vigilance.",
  ui_story_5036_50361201_177_dialog_content = "Also, have someone prepare an airship for me, and keep it secrete.",
  ui_story_5036_50361201_178_dialog_content = "Huh? Are you heading out now, my lord?",
  ui_story_5036_50361201_179_dialog_content = "It is still unclear whether or not that Colossus poses a threat. As City Lord, it is my duty to investigate the matter and ensure our city's safety personally.",
  ui_story_5036_50361201_180_dialog_content = "U-Understood!",
  ui_story_5036_50361201_181_dialog_content = "Sigh...",
  ui_story_5036_50361201_182_dialog_content = "When will Lord Schwartz just admit that he cares for Lady Carleen?",
  ui_story_5036_50361201_183_dialog_content = "<color=#e8d9bb>Meanwhile, inside the Wandering Colossus</color>",
  ui_story_5036_50361201_184_dialog_content = "That singing sounds like Vice and Carleen!",
  ui_story_5036_50361201_185_dialog_content = "Is it already time for their performance? Crap, I should pick up the pace!",
  ui_story_5036_50361201_186_dialog_content = "I should be there already, though...",
  ui_story_5036_50361201_187_dialog_content = "Nothing like a performance from two of the world's greatest adventurers!",
  ui_story_5036_50361201_188_dialog_content = "It just shows that idols can come from all walks of life!",
  ui_story_5036_50361201_189_dialog_content = "For some fans, the best idols are ones that bring out other people's true strength!",
  ui_story_5036_50361201_190_dialog_content = "Next up to take the stage is a charismatic choir from Illumina!",
  ui_story_5036_50361201_191_dialog_content = "They are here to sing an inspiring military anthem—!",
  ui_story_5036_50361201_192_dialog_content = "Woooooo!!!",
  ui_story_5036_50361201_193_dialog_content = "Phew! Thanks again for the help, ladies!",
  ui_story_5036_50361201_194_dialog_content = "Don't mention it! I'm just glad everything went well!",
  ui_story_5036_50361201_195_dialog_content = "I'm starting to worry about PlayerName and Vic though. They've been gone for a while.",
  ui_story_5036_50361201_196_dialog_content = "Indeed. The Colossus may be large, but it shouldn't take this much time to find someone.",
  ui_story_5036_50361201_197_dialog_content = "Hmm...",
  ui_story_5036_50361201_198_dialog_content = "Come on, Carleen. We should go look for them.",
  ui_story_5036_50361201_199_dialog_content = "I agree. Now that our performance is over, our top priority is ensuring those two are safe.",
  ui_story_5036_50361201_200_dialog_content = "Sure, but be careful out there, and remember to come back so you can take a bow!",
  ui_story_5036_50361201_201_dialog_content = "Got it!",
  ui_story_5036_50361201_202_dialog_content = "Let's go.",
  ui_story_5036_50361201_203_dialog_content = "<color=#e8d9bb>Sometime later</color>",
  ui_story_5036_50361201_204_dialog_content = "The Illumina Choir finished their song, and the Lumopolis Choir is nearly done with theirs too...",
  ui_story_5036_50361201_205_dialog_content = "Where on earth are PlayerName and the others? Could something have happened to them?",
  ui_story_5036_50361201_206_dialog_content = "They're starting to worry me, but I can't just leave. My final performance is coming up soon!",
  ui_story_5036_50361201_207_dialog_content = "I have to make sure everyone hears my song.",
  ui_story_5036_50361201_208_dialog_content = "Otherwise, all of our hard work will have been for nothing.",
  ui_story_5036_50361201_209_dialog_content = "I'll go look for them as soon as I'm done.",
  ui_story_5036_50361201_210_dialog_content = "We're getting closer to the grand finale, everyone! Are we still having a good time?!",
  ui_story_5036_50361201_211_dialog_content = "Yeah—!",
  ui_story_5036_50361201_212_dialog_content = "Fantastic! Thanks for keeping the energy up all concert long, folks!",
  ui_story_5036_50361201_213_dialog_content = "Now then, for the show's final act, allow me to send you all off with a song of my very own!",
  ui_story_5036_50361201_214_dialog_content = "Wooo!!! It's finally Goldie's turn to sing!!!",
  ui_story_5036_50361201_215_dialog_content = "This next song is a very special one. It was used by the Caelestites to communicate with the Colossi.",
  ui_story_5036_50361201_216_dialog_content = "By using its unique melody, the Caelestites would pilot their majestic Colossi all across the world!",
  ui_story_5036_50361201_217_dialog_content = "Today, in honor of this Colossus' long-awaited return, this melody will ring out once more!",
  ui_story_5036_50361201_218_dialog_content = "Wooooo—!!!",
  ui_story_5036_50361201_219_dialog_content = "(This is it. This is the moment we've all been waiting for.)",
  ui_story_5036_50361201_220_dialog_content = "Wherever Goldie goes, the Goldilocks follow!",
  ui_story_5036_50361201_221_dialog_content = "(Let this song be my way of repaying my fans and PlayerName for all of their endless support!)",
  ui_story_5036_50361201_222_dialog_content = "♪ Starlight, shining bright in the sky ♪",
  ui_story_5036_50361201_223_dialog_content = "♪ A little bird spreads her wings to fly ♪",
  ui_story_5036_50361201_224_dialog_content = "♪ A long and dangerous voyage lies before her eyes ♪",
  ui_story_5036_50361201_225_dialog_content = "♪ So light up her path all through the night! ♪",
  ui_story_5036_50361201_226_dialog_content = "Goldie! Goldie!",
  ui_story_5036_50361201_227_dialog_content = "Ah... I can hear Miss Goldie's singing...",
  ui_story_5036_50361201_228_dialog_content = "No matter how hard things have been. This makes it all worth it!",
  ui_story_5036_50361201_229_dialog_content = "♪ A chance to see you, a chance for love to grow! ♪",
  ui_story_5036_50361201_230_dialog_content = "♪ Fill my heart with courage, and tell me where to go! ♪",
  ui_story_5036_50361201_231_dialog_content = "(Urgh... Wh-Why do I feel so sleepy...?)",
  ui_story_5036_50361201_232_dialog_content = "(Wait, what am I thinking?! I'm in the middle of a song right now!!)",
  ui_story_5036_50361201_233_dialog_content = "♪ Let's go, let's go, take me away! ♪",
  ui_story_5036_50361201_234_dialog_content = "♪ To a place where I can see you every day! ♪",
  ui_story_5036_50361201_235_dialog_content = "(What's going on...? My head is spinning...)",
  ui_story_5036_50361201_236_dialog_content = "Kree—!",
  ui_story_5036_50361201_237_dialog_content = "(That sound... Where did that sound come from?)",
  ui_story_5036_50361201_238_dialog_content = "(I'm so tired... But I can't go to sleep just yet! The concert... It's still not over...)",
  ui_story_5036_50361301_1_dialog_content = "<color=#e8d9bb>Meanwhile, in the lockdown area</color>",
  ui_story_5036_50361301_2_dialog_content = "What's going on? It feels like I'm going in circles again.",
  ui_story_5036_50361301_3_dialog_content = "I still remember the way to the egg, so why haven't I gotten there yet?",
  ui_story_5036_50361301_4_dialog_content = "Could the Ouroboros have activated its psychic powers again?",
  ui_story_5036_50361301_5_dialog_content = "Are we there yet? The concert is probably almost over by now...",
  ui_story_5036_50361301_6_dialog_content = "Ah! There it is! After all this time, I finally made it!",
  ui_story_5036_50361301_7_dialog_content = "Hmm? What are you doing here, PlayerName?",
  ui_story_5036_50361301_8_dialog_content = "Don't tell me the concert was so boring that you came here to take a nap too?",
  ui_story_5036_50361301_9_dialog_content = "What kind of jerk do you take me for?!",
  ui_story_5036_50361301_10_dialog_content = "More importantly, what are YOU doing here?! Everyone's still waiting on your performance!",
  ui_story_5036_50361301_11_dialog_content = "My performance? Oh, you mean the whole singing thing, right?",
  ui_story_5036_50361301_12_dialog_content = "Sorry, but I can't do it.",
  ui_story_5036_50361301_13_dialog_content = "What do you mean?! You have a gift, and Goldie spent all that time and effort training you! How could you choose to bail at a time like this?!",
  ui_story_5036_50361301_14_dialog_content = "Hahahaha! You're absolutely right, I do have a gift. But I really can't do it.",
  ui_story_5036_50361301_15_dialog_content = "Have you seen the way they train?",
  ui_story_5036_50361301_16_dialog_content = "To perform on stage, they require weeks of training, as well as an endless supply of energy and enthusiasm. And I'm sorely lacking in both departments, kiddo.",
  ui_story_5036_50361301_17_dialog_content = "Besides, I have no interest in concerts or idols. My old bones just aren't cut out for that kind of kiddie stuff.",
  ui_story_5036_50361301_18_dialog_content = "And even if I got up on that stage, I'd only be holding you youngsters back.",
  ui_story_5036_50361301_19_dialog_content = "So instead of making things difficult for everyone, I decided to use my few skills to good use! Like watching over this egg and making sure it doesn't ruin the concert!",
  ui_story_5036_50361301_20_dialog_content = "For someone who says they don't care about the concert, you sure are showing a lot of concern.",
  ui_story_5036_50361301_21_dialog_content = "Haha! I just don't want to be in a position of owing a bunch of kids a favor.",
  ui_story_5036_50361301_22_dialog_content = "I think it's a little late for that...",
  ui_story_5036_50361301_23_dialog_content = "Ahem, if you're talking about my apprentices, it's all a part of their training.",
  ui_story_5036_50361301_24_dialog_content = "But enough about that, you sensed it on the way here too, didn't you? The Ouroboros egg activated its powers yet again.",
  ui_story_5036_50361301_25_dialog_content = "Yeah. It felt like I was walking around for hours before I got here.",
  ui_story_5036_50361301_26_dialog_content = "This can only mean that the Ouroboros detects danger again, and is trying to defend itself.",
  ui_story_5036_50361301_27_dialog_content = "But what about the Eclipsites we took out, or the cracks we secured?",
  ui_story_5036_50361301_28_dialog_content = "Could it be because the other Aurorians are too far away?",
  ui_story_5036_50361301_29_dialog_content = "With the concert in full swing, every Aurorian is gathered up towards the front of the Colossus, the furthest place from our current position.",
  ui_story_5036_50361301_30_dialog_content = "If something were to happen here, we would be the only ones left to defend it. The others couldn't possibly make it here in time.",
  ui_story_5036_50361301_31_dialog_content = "So you think the Ouroboros is scared because of this?",
  ui_story_5036_50361301_32_dialog_content = "It's possible!",
  ui_story_5036_50361301_33_dialog_content = "What a cowardly creature this Ouroboros turned out to be. After all these years aboard an Eclipsite-infested Colossus, it's still scared!",
  ui_story_5036_50361301_34_dialog_content = "I don't think it's scared of them so much as it's scared to be alone again, Vic.",
  ui_story_5036_50361301_35_dialog_content = "I spent the first seventeen years of my life aboard a Colossus. Even though I was all by myself, I never felt lonely because I had Soroz to keep me company.",
  ui_story_5036_50361301_36_dialog_content = "But now that I've made so many friends. I know that I could never part with them.",
  ui_story_5036_50361301_37_dialog_content = "You make a good point.",
  ui_story_5036_50361301_38_dialog_content = "Anyways, what did you mean just now by the egg \"ruining the concert\"?",
  ui_story_5036_50361301_39_dialog_content = "It's already well underway. What could the Ouroboros egg possibly do to it now?",
  ui_story_5036_50361301_40_dialog_content = "A keen observer as always.",
  ui_story_5036_50361301_41_dialog_content = "As I said before, some unknown factor has prevented this egg from hatching, which is why it grew to monumental proportions.",
  ui_story_5036_50361301_42_dialog_content = "But for that very same reason, I have no idea when it will hatch, either.",
  ui_story_5036_50361301_43_dialog_content = "Given the current size of the egg, if the Ouroboros were to hatch right now... I'm afraid it would have an enormous impact on the entire Colossus.",
  ui_story_5036_50361301_44_dialog_content = "Huh...?!",
  ui_story_5036_50361301_45_dialog_content = "Doesn't that mean this egg is just as dangerous as a ticking time bomb, isn't it?!",
  ui_story_5036_50361301_46_dialog_content = "Precisely!",
  ui_story_5036_50361301_47_dialog_content = "Which is why I decided to watch over it, you see? Not just for the sake of the concert, but for the sake of our very lives as well.",
  ui_story_5036_50361301_48_dialog_content = "And the fact that you were able to come to such a conclusion means that you have the aptitude for a career in extrozoology, PlayerName!",
  ui_story_5036_50361301_49_dialog_content = "What do you say? Care to work under me as my newest apprentice?",
  ui_story_5036_50361301_50_option_content = "Sure!",
  ui_story_5036_50361301_51_dialog_content = "I have to admit, wondrous beasts are pretty interesting. Not to mention, a lot of them are also endangered.",
  ui_story_5036_50361301_52_dialog_content = "Protecting them would be a very meaningful career choice.",
  ui_story_5036_50361301_53_dialog_content = "A very valid viewpoint, PlayerName. Or should I say, my little apprentice?",
  ui_story_5036_50361301_54_dialog_content = "But I'm telling you right now, I'm not gonna let you boss me around or send me on errands for free.",
  ui_story_5036_50361301_55_dialog_content = "*Sob* Is that any way to see your master?",
  ui_story_5036_50361301_56_option_content = "I think I'll pass.",
  ui_story_5036_50361301_57_dialog_content = "Researching wondrous beasts is great and all, but after meeting Fia and Shira, I know all about life as one of your apprentices...",
  ui_story_5036_50361301_58_dialog_content = "Being sent out on investigations without any money, taking care of wondrous beasts, taking care of their master...",
  ui_story_5036_50361301_59_dialog_content = "What kind of life is that?!",
  ui_story_5036_50361301_60_dialog_content = "Everything we do for the wondrous beasts is out of love and respect for them, which is why we don't ask for anything in exchange!",
  ui_story_5036_50361301_61_dialog_content = "But if you feel so strongly against it, I won't try to change your mind.",
  ui_story_5036_50361301_62_dialog_content = "I've wasted so much time here. I wonder how the concert's getting along.",
  ui_story_5036_50361301_63_dialog_content = "I'll go back and let them know everything's okay, so they don't keep worrying about us.",
  ui_story_5036_50361301_64_dialog_content = "Sure! In that case, I'll stay here and—",
  ui_story_5036_50361301_65_dialog_content = "Kree—!",
  ui_story_5036_50361301_66_dialog_content = "What was that sound?",
  ui_story_5036_50361301_67_dialog_content = "Sound? What sound? You sure you're not hearing things?",
  ui_story_5036_50361301_68_dialog_content = "Hey, Carleen? Did you just hear a weird noise?",
  ui_story_5036_50361301_69_dialog_content = "It sounded like an animal cry.",
  ui_story_5036_50361301_70_dialog_content = "Ngh...",
  ui_story_5036_50361301_71_dialog_content = "Carleen! Are you okay?! What's...",
  ui_story_5036_50361301_72_dialog_content = "What's happening...? So sleepy...",
  ui_story_5036_50361301_73_dialog_content = "It sounded like... the Ouroboros...",
  ui_story_5036_50361301_74_dialog_content = "(Huh? Why am I... so... sleepy...?)",
  ui_story_5036_50361301_75_dialog_content = "PlayerName? What's the matter? Snap out of it!",
  ui_story_5036_50361301_76_dialog_content = "Looks like I have no choice but to use my last resort. Bica! Go inside PlayerName's pocket and eat up all his Nightium!",
  ui_story_5036_50361301_77_dialog_content = "Hai!",
  ui_story_5036_50361301_78_dialog_content = "Wh-What?! No, please! Anything but that!",
  ui_story_5036_50361301_79_dialog_content = "Do you know how long I worked to save all this?!",
  ui_story_5036_50361301_80_dialog_content = "Oh goodie, you're awake.",
  ui_story_5036_50361301_81_dialog_content = "Did you stay up late last night or something? You were about to pass out.",
  ui_story_5036_50361301_82_dialog_content = "Huh? Not at all, I actually went to bed pretty early last night.",
  ui_story_5036_50361301_83_dialog_content = "Weird... I could've sworn I heard the Ouroboros just now, and then I suddenly felt extremely sleepy...",
  ui_story_5036_50361301_84_dialog_content = "You heard the Ouroboros? Why didn't I hear it?",
  ui_story_5036_50361301_85_dialog_content = "I'm serious! If you don't believe me, just keep listening; it might cry out again!",
  ui_story_5036_50361301_86_dialog_content = "If you say so, I'll keep an ear out.",
  ui_story_5036_50361301_87_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5036_50361301_88_dialog_content = "I don't hear a thing, much less an Ouroboros! You must have heard wrong.",
  ui_story_5036_50361301_89_dialog_content = "But...",
  ui_story_5036_50361301_90_dialog_content = "<color=#e8d9bb>Thump—</color>",
  ui_story_5036_50361301_91_dialog_content = "I heard something again! Only this time, it didn't sound like the Ouroboros' cry.",
  ui_story_5036_50361301_92_dialog_content = "That sound, could it be?!",
  ui_story_5036_50361301_93_dialog_content = "So you hear it too, right?",
  ui_story_5036_50361301_94_dialog_content = "<color=#e8d9bb>Thump—Thump—</color>",
  ui_story_5036_50361301_95_dialog_content = "Oh, I hear it, alright. I hear it loud and clear.",
  ui_story_5036_50361301_96_dialog_content = "It's... a heartbeat.",
  ui_story_5036_50361301_97_dialog_content = "It's coming from inside the egg.",
  ui_story_5036_50361301_98_dialog_content = "Huh? Y-You mean it's finally hatching?!",
  ui_story_5036_50361301_99_dialog_content = "This fella's got the worst timing, wouldn't you agree?",
  ui_story_5036_50361301_100_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5036_50361301_101_dialog_content = "What now?!",
  ui_story_5036_50361301_102_dialog_content = "Look out, PlayerName!",
  ui_story_5036_50361301_103_dialog_content = "Something's trying to break through the wall we sealed up last night!",
  ui_story_5036_50361301_104_dialog_content = "<color=#e8d9bb>Boom—!!</color>",
  ui_story_5036_50361301_105_dialog_content = "Graaaaaah—!",
  ui_story_5036_50361301_106_dialog_content = "It's Eclipsites, Vic!",
  ui_story_5036_50361301_107_dialog_content = "Save us, Little Furball!",
  ui_story_5036_50361302_1_dialog_content = "Why are there so many Eclipsites here?!",
  ui_story_5036_50361302_2_dialog_content = "I thought we got rid of all of them last night!",
  ui_story_5036_50361302_3_dialog_content = "It would seem these Eclipsites came from even further away.",
  ui_story_5036_50361302_4_dialog_content = "Judging by how agitated they've become, I guess it has something to do with the Ouroboros hatching.",
  ui_story_5036_50361302_5_dialog_content = "Whatever it is, we have to tell Goldie and the others right away!",
  ui_story_5036_50361302_6_dialog_content = "If the Ouroboros is really about the hatch, staying aboard the Colossus will be too dangerous for us!",
  ui_story_5036_50361302_7_dialog_content = "We need to hurry back and evacuate everyone!",
  ui_story_5036_50361302_8_dialog_content = "True, staying here is completely out of the question.",
  ui_story_5036_50361302_9_dialog_content = "After all, this room could crash on our heads once the Ouroboros hatches.",
  ui_story_5036_50361302_10_dialog_content = "Looks like it's time to run!",
  ui_story_5036_50361302_11_dialog_content = "This way. Don't get separated!",
  ui_story_5036_50361302_12_dialog_content = "Wait, I think there's two people on the floor over there.",
  ui_story_5036_50361302_13_dialog_content = "It's Vice and Carleen!",
  ui_story_5036_50361302_14_dialog_content = "Vice! Carleen! Wake up!",
  ui_story_5036_50361302_15_dialog_content = "What's going on? I can't wake them up!",
  ui_story_5036_50361302_16_dialog_content = "Could this be the work of the Ouroboros too?",
  ui_story_5036_50361302_17_dialog_content = "It's too dangerous to leave them here. We'll just have to carry them.",
  ui_story_5036_50361302_18_dialog_content = "Alright, leave it to me. I'll get them.",
  ui_story_5036_50361302_19_dialog_content = "Hrrrrrrrng—oof!",
  ui_story_5036_50361302_20_dialog_content = "You might consider lifting weights if we make it out of here, PlayerName.",
  ui_story_5036_50361302_21_dialog_content = "Now's definitely not the time, Vic! Help me pick them up!",
  ui_story_5036_50361302_22_dialog_content = "I don't think I'll be much help in that regard either. However—",
  ui_story_5036_50361302_23_dialog_content = "Come on out, Little Furball!",
  ui_story_5036_50361302_24_dialog_content = "Chirp!",
  ui_story_5036_50361302_25_dialog_content = "It can get bigger?!",
  ui_story_5036_50361302_26_dialog_content = "Obviously! But that doesn't change its huggable, soft fur.",
  ui_story_5036_50361302_27_dialog_content = "I couldn't ask for a better bed for my afternoon naps! Here, you want to feel it? The first touch is free!",
  ui_story_5036_50361302_28_dialog_content = "M-Maybe next time, Vic...",
  ui_story_5036_50361302_29_dialog_content = "Now then, Little Furball, or should I say Big Furball? I need you to carry those two girls over there.",
  ui_story_5036_50361302_30_dialog_content = "Chirrrrp—!",
  ui_story_5036_50361302_31_dialog_content = "Let's keep moving! We still have to warn the others!",
  ui_story_5036_50361302_32_dialog_content = "Oh no...",
  ui_story_5036_50361302_33_dialog_content = "Looks like they're all asleep.",
  ui_story_5036_50361302_34_dialog_content = "That girl even passed out on the stage all by herself.",
  ui_story_5036_50361302_35_dialog_content = "...",
  ui_story_5036_50361302_36_dialog_content = "Goldie! Snap out of it, Goldie!",
  ui_story_5036_50361302_37_dialog_content = "Why can't I wake any of them up...?",
  ui_story_5036_50361302_38_dialog_content = "Something is strange about her condition. This appears to be the work of Luminatics.",
  ui_story_5036_50361302_39_dialog_content = "You think the Ouroboros did this, too?",
  ui_story_5036_50361302_40_dialog_content = "But if so, why are we still awake when everyone else is in a coma like this?",
  ui_story_5036_50361302_41_dialog_content = "Because there's something special about the two of us.",
  ui_story_5036_50361302_42_dialog_content = "You're a Caelestite, you possess unique psychic abilities.",
  ui_story_5036_50361302_43_dialog_content = "As for me, my bloodline shares a similar origin with the Ouroboros. This could be the source of my immunity.",
  ui_story_5036_50361302_44_dialog_content = "Is there any way to wake them up?",
  ui_story_5036_50361302_45_dialog_content = "I can't say for sure, no.",
  ui_story_5036_50361302_46_dialog_content = "But how could that be? You just said it yourself: You share an origin with the Ouroboros! You must have something.",
  ui_story_5036_50361302_47_dialog_content = "Sorry, but aside from being long-lived, the Ouroboros and I don't have much else in common.",
  ui_story_5036_50361302_48_dialog_content = "You might have a better shot.",
  ui_story_5036_50361302_49_dialog_content = "Your psychic ability might allow you to sense something I don't know.",
  ui_story_5036_50361302_50_dialog_content = "Okay, I guess we don't have any other ideas.",
  ui_story_5036_50361401_1_dialog_content = "Am I... asleep?",
  ui_story_5036_50361401_2_dialog_content = "Wait, this is Eraveil! Am I dreaming again?",
  ui_story_5036_50361401_3_dialog_content = "Something's different this time. The scene looks a lot clearer than before.",
  ui_story_5036_50361401_4_dialog_content = "I can even see a white tower way over there.",
  ui_story_5036_50361401_5_dialog_content = "Wait, what's that flying above it? Is that...",
  ui_story_5036_50361401_6_dialog_content = "A dragon?",
  ui_story_5036_50361401_7_dialog_content = "Oh, I'm definitely dreaming!",
  ui_story_5036_50361401_8_dialog_content = "But how? How did this happen? Come on, Goldie. You gotta wake up! The concert's not over yet!",
  ui_story_5036_50361401_9_dialog_content = "They say that pinching your thigh in a dream will wake you up.",
  ui_story_5036_50361401_10_dialog_content = "Here goes!",
  ui_story_5036_50361401_11_dialog_content = "Yeeeeeowch!",
  ui_story_5036_50361401_12_dialog_content = "Why didn't I wake up?! Maybe I need to pinch myself even harder!",
  ui_story_5036_50361401_13_dialog_content = "♪ La—La la ♪",
  ui_story_5036_50361401_14_dialog_content = "That voice... I've heard it before! It sounds like that Caelestite girl, Chaminade!",
  ui_story_5036_50361401_15_dialog_content = "♪ Wings... soaked ♪",
  ui_story_5036_50361401_16_dialog_content = "I think I can make out her song's lyrics this time.",
  ui_story_5036_50361401_17_dialog_content = "I couldn't hear anything but the melody last time.",
  ui_story_5036_50361401_18_dialog_content = "♪... home ♪",
  ui_story_5036_50361401_19_dialog_content = "Sounds like it's coming from over there.",
  ui_story_5036_50361401_20_dialog_content = "♪ All that remains are those moments in my memories ♪",
  ui_story_5036_50361401_21_dialog_content = "♪ The white tower stands tall and proud ♪",
  ui_story_5036_50361401_22_dialog_content = "♪ But its guiding light lies beyond my sight ♪",
  ui_story_5036_50361401_23_dialog_content = "(The melody sounds so beautiful, but the look on her face is full of nothing but sadness...)",
  ui_story_5036_50361401_24_dialog_content = "♪ Wander, wander, see the land and the sea ♪",
  ui_story_5036_50361401_25_dialog_content = "♪ But never forget the home in your dreams ♪",
  ui_story_5036_50361401_26_dialog_content = "Hm? I didn't realize there'd be other visitors.",
  ui_story_5036_50361401_27_dialog_content = "(Huh?! I-Is she talking to me?!)",
  ui_story_5036_50361401_28_dialog_content = "(This never happened in my previous dreams. Unless... this isn't a dream?)",
  ui_story_5036_50361401_29_dialog_content = "H-Hello there! You must be Chaminade. My name is Goldie. I'm an idol!",
  ui_story_5036_50361401_30_dialog_content = "Hmm? You know my name?",
  ui_story_5036_50361401_31_dialog_content = "Of course I do! My friend PlayerName is a Caelestite too! He used his psychic powers to see your memories from the past.",
  ui_story_5036_50361401_32_dialog_content = "Is that so? Heheheh, that's a little embarrassing.",
  ui_story_5036_50361401_33_dialog_content = "Say, what exactly is an \"idol\"?",
  ui_story_5036_50361401_34_dialog_content = "An idol is someone who uses the power of music to bring happiness and hope to other people. I'm a professional idol!",
  ui_story_5036_50361401_35_dialog_content = "That's amazing! I want to be an idol too!",
  ui_story_5036_50361401_36_dialog_content = "I'd be happy to share some pointers with you if you like. Oh, but now's not a good time. I have to get back to my concert and finish my performance!",
  ui_story_5036_50361401_37_dialog_content = "Do you know how I can get out of here, Chaminade?",
  ui_story_5036_50361401_38_dialog_content = "I'm sorry... But I don't know how to leave this place.",
  ui_story_5036_50361401_39_dialog_content = "After all, I have no way out of here either.",
  ui_story_5036_50361401_40_dialog_content = "There's no way out?",
  ui_story_5036_50361401_41_dialog_content = "(That makes sense since the real her is already...)",
  ui_story_5036_50361401_42_dialog_content = "(Wait, if the real Chaminade is already dead... Then who, or what, is in front of me?)",
  ui_story_5036_50361401_43_dialog_content = "Mm, it's okay!",
  ui_story_5036_50361401_44_dialog_content = "As long as we search, we'll find one!",
  ui_story_5036_50361401_45_dialog_content = "<color=#e8d9bb>Crash—</color>",
  ui_story_5036_50361401_46_dialog_content = "Huh? What was that noise?",
  ui_story_5036_50361401_47_dialog_content = "It's them!",
  ui_story_5036_50361401_48_dialog_content = "They're coming! We have to get out of here!",
  ui_story_5036_50361401_49_dialog_content = "\"Them\"? Who are you talking about?",
  ui_story_5036_50361401_50_dialog_content = "The Eclipsites!",
  ui_story_5036_50361401_51_dialog_content = "Graaaaaah—!",
  ui_story_5036_50361401_52_dialog_content = "Oh, she isn't kidding! Why are there so many of them?!",
  ui_story_5036_50361401_53_dialog_content = "Grahhhhhh—!",
  ui_story_5036_50361401_54_dialog_content = "Where did they all come from?!",
  ui_story_5036_50361401_55_dialog_content = "They're coming back again, Goldie! Quick, hide!",
  ui_story_5036_50361401_56_dialog_content = "There's nowhere to hide, not with this many of them. Our only choice is to fight!",
  ui_story_5036_50361401_57_dialog_content = "I won't let you Eclipsites run amok any longer!",
  ui_story_5036_50361402_1_dialog_content = "Oof—!",
  ui_story_5036_50361402_2_dialog_content = "Darn! There's just no end to them! We can't beat them all!",
  ui_story_5036_50361402_3_dialog_content = "Grahh!",
  ui_story_5036_50361402_4_dialog_content = "Ahhh!",
  ui_story_5036_50361402_5_dialog_content = "Forget about me and just run! They'll disappear soon, so just keep away for now!",
  ui_story_5036_50361402_6_dialog_content = "Huh? What do you mean?",
  ui_story_5036_50361402_7_dialog_content = "Kree—",
  ui_story_5036_50361402_8_dialog_content = "Kree—!",
  ui_story_5036_50361402_9_dialog_content = "Is the dragon... glowing!?",
  ui_story_5036_50361402_10_dialog_content = "It's so bright! I can't see a thing—!",
  ui_story_5036_50361402_11_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5036_50361402_12_dialog_content = "Just gotta keep moving, the Eclipsites are right behind... Huh? W-Where did the Eclipsites go?",
  ui_story_5036_50361402_13_dialog_content = "They're gone now. Everything is okay.",
  ui_story_5036_50361402_13X1_dialog_content = "The Ouroboros made them all disappear!",
  ui_story_5036_50361402_13X2_dialog_content = "Oh yeah, I haven't introduced you to it yet, have I? It's there, the little one flying in the sky above!",
  ui_story_5036_50361402_14_dialog_content = "Gone? You mean the Ouroboros' light got rid of them?",
  ui_story_5036_50361402_15_dialog_content = "No, it isn't strong enough to do that. All it did was start this dream all over again.",
  ui_story_5036_50361402_16_dialog_content = "So this really is a dream!",
  ui_story_5036_50361402_17_dialog_content = "Yes, it is. A dream made for me by the Ouroboros.",
  ui_story_5036_50361402_18_dialog_content = "Since your friend is a Caelestite, then you must have already seen what happened to me...",
  ui_story_5036_50361402_19_dialog_content = "Yeah...",
  ui_story_5036_50361402_20_dialog_content = "After sensing that I died protecting it, the Ouroboros was overcome with grief.",
  ui_story_5036_50361402_21_dialog_content = "It sensed my heart's last wish to return to my home, so it created Eraveil in its dreamscape, and me.",
  ui_story_5036_50361402_22_dialog_content = "But because of its own desire to not let go of this dream, the Ouroboros forced itself into an endless sleep.",
  ui_story_5036_50361402_23_dialog_content = "Then those Eclipsites just now were—",
  ui_story_5036_50361402_24_dialog_content = "They are my fears.",
  ui_story_5036_50361402_25_dialog_content = "They're manifestations of the fear I felt in my final moments. That's why they keep constantly appearing and attacking me.",
  ui_story_5036_50361402_26_dialog_content = "But it's okay, because the Ouroboros is protecting me. Just when they're about to get me, it resets the dream and makes them disappear!",
  ui_story_5036_50361402_27_dialog_content = "Wait, maybe you can ask the Ouroboros to help you leave?",
  ui_story_5036_50361402_28_dialog_content = "Good idea! I'll go ask it now!",
  ui_story_5036_50361402_29_dialog_content = "Okay! But before you do, could you stay and talk with me a little longer?",
  ui_story_5036_50361402_30_dialog_content = "I would love to, Chaminade, I really would. But my fans are still waiting for me out there.",
  ui_story_5036_50361402_31_dialog_content = "It won't take long, I promise! I just have one little question, if that's okay?",
  ui_story_5036_50361402_32_dialog_content = "Of course, it is! What is it?",
  ui_story_5036_50361402_33_dialog_content = "What does Eraveil look like nowadays?",
  ui_story_5036_50361402_34_dialog_content = "Please tell me! I'm so curious.",
  ui_story_5036_50361402_35_dialog_content = "Um... Eraveil?",
  ui_story_5036_50361402_36_dialog_content = "I'm sorry, but I've never been there before...",
  ui_story_5036_50361402_37_dialog_content = "Oh...",
  ui_story_5036_50361402_38_dialog_content = "But don't feel so down! Even though I've never been there myself, I have a trusty Caelestite friend who lives there!",
  ui_story_5036_50361402_39_dialog_content = "You mean the Caelestite you mentioned earlier?",
  ui_story_5036_50361402_40_dialog_content = "That's right! His name is PlayerName, and he's one of the most incredible people I've ever met!",
  ui_story_5036_50361402_41_dialog_content = "Before I met him, all I knew was that he was the Caelestite pilot of a Colossus who traveled worldwide.",
  ui_story_5036_50361402_42_dialog_content = "Throughout his travels, he's made lots of friends and has gone on tons of adventures. He's also defeated more Eclipsites than I can count!",
  ui_story_5036_50361402_43_dialog_content = "I used to be so jealous of his life. To me, it was like he lived a life of ultimate freedom.",
  ui_story_5036_50361402_44_dialog_content = "But after I got to know the real him, I learned just how hard his life has been.",
  ui_story_5036_50361402_45_dialog_content = "He spent the early years of his life living underground all by himself. It wasn't until he made his first friend that he finally saw the light of day.",
  ui_story_5036_50361402_46_dialog_content = "He's the last of the Caelestites, and he even rebuilt Eraveil from its ruins.",
  ui_story_5036_50361402_47_dialog_content = "What?",
  ui_story_5036_50361402_48_dialog_content = "What do you mean? Was Eraveil... destroyed? There's only... one Caelestite left?",
  ui_story_5036_50361402_49_dialog_content = "Ah! N-No, I didn't mean it like that! What I meant to say—",
  ui_story_5036_50361402_50_dialog_content = "My... my home was destroyed...",
  ui_story_5036_50361402_51_dialog_content = "Eraveil... is Eraveil really gone?",
  ui_story_5036_50361402_52_dialog_content = "But how? How could this be?!",
  ui_story_5036_50361402_53_dialog_content = "<color=#e8d9bb>Crash!</color>",
  ui_story_5036_50361402_54_dialog_content = "<color=#e8d9bb>Crack—!</color>",
  ui_story_5036_50361402_55_dialog_content = "The dreamscape is starting to crumble apart! Is it because of Chaminade's emotions?",
  ui_story_5036_50361402_56_dialog_content = "Chaminade! P-Please calm down!",
  ui_story_5036_50361402_57_dialog_content = "My home... I just want to go home... Ahhhhh!",
  ui_story_5036_50361402_58_dialog_content = "She's not calming down at all...",
  ui_story_5036_50361402_59_dialog_content = "<color=#e8d9bb>Boom—!</color>",
  ui_story_5036_50361402_60_dialog_content = "Kree! Kree—!",
  ui_story_5036_50361402_61_dialog_content = "More and more of the dream is starting to fall apart. But why isn't it resetting?",
  ui_story_5036_50361402_62_dialog_content = "Oh, what should I do? Maybe I should start counting and skip all the sevens. Will anything good happen?",
  ui_story_5036_50361402_63_dialog_content = "No... Now's not the time to just stand around! At least I need to get away from the parts of the dream that are falling apart!",
  ui_story_5036_50361402_64_dialog_content = "That tower over there still looks like it's in good shape. It's also the closest place to the Ouroboros.",
  ui_story_5036_50361402_65_dialog_content = "Let's go, Chaminade—Ahh!",
  ui_story_5036_50361402_66_dialog_content = "*Sob*",
  ui_story_5036_50361402_67_dialog_content = "Ow! She's not letting me get near her!",
  ui_story_5036_50361402_68_dialog_content = "Chaminade! Chaminade! You need to calm down!!!",
  ui_story_5036_50361402_69_dialog_content = "She's not listening to me...",
  ui_story_5036_50361402_70_dialog_content = "If this keeps up, the whole dream will come crashing down around us!",
  ui_story_5036_50361402_71_dialog_content = "I have to find a way to fix this dream!",
  ui_story_5036_50361402_72_dialog_content = "I just hope the Ouroboros knows what to do!",
  ui_story_5036_50361402_73_dialog_content = "This tower seems endless! How am I still not at the top?",
  ui_story_5036_50361402_74_dialog_content = "What kind of place is this? It's so dark and empty.",
  ui_story_5036_50361402_75_dialog_content = "No! I can't let my fear of the dark stop me now!",
  ui_story_5036_50361402_76_dialog_content = "Grah...",
  ui_story_5036_50361402_77_dialog_content = "Looks like even this place isn't safe from the Eclipsites.",
  ui_story_5036_50361402_78_dialog_content = "I guess it makes sense. As the center of the dream, it's the most stable place.",
  ui_story_5036_50361402_79_dialog_content = "Even Eclipsites know to run from danger, it seems.",
  ui_story_5036_50361402_80_dialog_content = "I don't have any time to waste on them, though. I have to reach the top!",
  ui_story_5036_50361402_81_dialog_content = "That light up ahead must be the exit.",
  ui_story_5036_50361402_82_dialog_content = "Finally!",
  ui_story_5036_50361402_83_dialog_content = "Kree, kree!",
  ui_story_5036_50361402_84_dialog_content = "It's the Ouroboros! Hey!",
  ui_story_5036_50361402_85_dialog_content = "Can you please fix the dream and make Chaminade calm down?",
  ui_story_5036_50361402_86_dialog_content = "Kree...",
  ui_story_5036_50361402_87_dialog_content = "(It looks worried. Is it trying to tell me that it can't help, either?)",
  ui_story_5036_50361402_88_dialog_content = "(What am I supposed to do now?!)",
  ui_story_5036_50361402_89_dialog_content = "<color=#e8d9bb>Boom!!!</color>",
  ui_story_5036_50361402_90_dialog_content = "Even the sky's beginning to fall apart!!",
  ui_story_5036_50361402_91_dialog_content = "Kree! Kree—!",
  ui_story_5036_50361402_92_dialog_content = "The Ouroboros looks like it's in a lot of pain...",
  ui_story_5036_50361402_93_dialog_content = "<color=#e8d9bb>Boom—!</color>",
  ui_story_5036_50361402_94_dialog_content = "Ahhh! T-The tower is starting to collapse!",
  ui_story_5036_50361402_95_dialog_content = "Ahhhhhhh—!!!",
  ui_story_5036_50361402_96_dialog_content = "Goldie! Take my hand!",
  ui_story_5036_50361402_97_dialog_content = "PlayerName!?",
  ui_story_5036_50361402_98_dialog_content = "What are you doing here?!",
  ui_story_5036_50361402_99_dialog_content = "We noticed something was off about the Ouroboros egg, so we went back to the stage to investigate.",
  ui_story_5036_50361402_100_dialog_content = "But when we got back to the concert, everyone was passed out! Not only that, there were traces of the Ouroboros' Luminatics around your unconscious body.",
  ui_story_5036_50361402_101_dialog_content = "So the Ouroboros finally hatched? But why now, of all times?!",
  ui_story_5036_50361402_102_dialog_content = "It's possible that it hatched after hearing your song.",
  ui_story_5036_50361402_103_dialog_content = "By writing your song with a melody used to activate the Colossi, you may have unintentionally given the Ouroboros the wake-up call it needed to hatch!",
  ui_story_5036_50361402_104_dialog_content = "What?!",
  ui_story_5036_50361402_105_dialog_content = "If we keep dawdling, my hands won't be able to keep holding on...",
  ui_story_5036_50361402_106_dialog_content = "Wait! Don't let go!!!",
  ui_story_5036_50361402_107_dialog_content = "Hahaha! I was only joking! Do you really think I'm that unreliable?",
  ui_story_5036_50361402_108_dialog_content = "Alright, let's pull her out of here now!",
  ui_story_5036_50361402_109_dialog_content = "Hang on tight, Goldie!",
  ui_story_5036_50361402_110_dialog_content = "Ahhh!",
  ui_story_5036_50361402_111_dialog_content = "I-I'm awake!",
  ui_story_5036_50361402_112_dialog_content = "Are you alright?",
  ui_story_5036_50361402_113_dialog_content = "Yeah, my head just feels a little dizzy...",
  ui_story_5036_50361402_114_dialog_content = "Finally... After all this time, I'm finally... Hah? W-Was I dreaming?!",
  ui_story_5036_50361402_115_dialog_content = "Ugh... What happened?",
  ui_story_5036_50361402_116_dialog_content = "My head... Were we asleep?",
  ui_story_5036_50361402_117_dialog_content = "Ya—wn. Good morning...? Or should I say good evening?",
  ui_story_5036_50361402_118_dialog_content = "Did I actually fall asleep next to all of these commoners?! Ugh, I'll have to burn this outfit when I get home...",
  ui_story_5036_50361402_119_dialog_content = "Looks like everyone's starting to come to their senses!",
  ui_story_5036_50361402_120_dialog_content = "Is it because the dream went back to normal?",
  ui_story_5036_50361402_121_dialog_content = "No. It's because...",
  ui_story_5036_50361402_122_dialog_content = "the Ouroboros is about to hatch.",
  ui_story_5036_50361501_1_dialog_content = "<color=#e8d9bb>Umbraton, on the banks of the Gold River</color>",
  ui_story_5036_50361501_2_dialog_content = "Hey, what the hell's going on up there? What kind of performer falls asleep in the middle of their act?!",
  ui_story_5036_50361501_3_dialog_content = "I wonder if she's okay.",
  ui_story_5036_50361501_4_dialog_content = "Don't worry! I'm sure she's fine. She's strong, after all!",
  ui_story_5036_50361501_5_dialog_content = "What the heck are those two random people doing up on the stage?",
  ui_story_5036_50361501_6_dialog_content = "What a scam. I'm not wasting any more time here.",
  ui_story_5036_50361501_7_dialog_content = "Just a moment, sir.",
  ui_story_5036_50361501_8_dialog_content = "It's still too early to leave. After all, everything you've seen was part of the show.",
  ui_story_5036_50361501_9_dialog_content = "What?",
  ui_story_5036_50361501_10_dialog_content = "We went to great lengths to plan all the special effects. Just singing and dancing is so dull, don't you think?",
  ui_story_5036_50361501_11_dialog_content = "We prepared a number of surprises to complement the show and make it as exciting as possible, all for your viewing pleasure.",
  ui_story_5036_50361501_12_dialog_content = "I hope you all stay a while longer and enjoy the show. I promise it won't disappoint.",
  ui_story_5036_50361501_13_dialog_content = "Fine, we'll do as you say for now.",
  ui_story_5036_50361501_14_dialog_content = "Thank you for your understanding and support! We've also prepared snacks and refreshments for everyone.",
  ui_story_5036_50361501_15_dialog_content = "Please help yourselves.",
  ui_story_5036_50361501_16_dialog_content = "(I've got the crowd under control for now, but this won't last much longer.)",
  ui_story_5036_50361501_17_dialog_content = "(What on earth is going on up there, Goldie?)",
  ui_story_5036_50361501_18_dialog_content = "(PlayerName and his friends are up there, as well... I just hope they aren't in danger...)",
  ui_story_5036_50361501_19_dialog_content = "<color=#e8d9bb>Meanwhile, on Eulogoz</color>",
  ui_story_5036_50361501_20_dialog_content = "What? The Ouroboros is hatching?!",
  ui_story_5036_50361501_21_dialog_content = "I know it's sudden, but we don't have time to explain.",
  ui_story_5036_50361501_22_dialog_content = "If the Ouroboros hatches, it'll throw this entire Colossus off balance and put us all in danger.",
  ui_story_5036_50361501_23_dialog_content = "Our top priority right now is evacuating everyone onboard!",
  ui_story_5036_50361501_24_dialog_content = "And we better do it quickly, or... Uh-oh. Looks like we're already too late.",
  ui_story_5036_50361501_25_dialog_content = "Grahhhh—!!!",
  ui_story_5036_50361501_26_dialog_content = "Eclipsites are pouring out from inside the Colossus!",
  ui_story_5036_50361501_27_dialog_content = "Wake up, everyone! Assume defensive positions!",
  ui_story_5036_50361501_28_dialog_content = "Yes, my lady!",
  ui_story_5036_50361501_29_dialog_content = "Graaaaaah!",
  ui_story_5036_50361501_30_dialog_content = "You won't get past me!",
  ui_story_5036_50361501_31_dialog_content = "Damn! Is there no end to these filthy creatures?!",
  ui_story_5036_50361501_32_dialog_content = "Enough complaining. Focus on defense.",
  ui_story_5036_50361501_33_dialog_content = "Yes, yes, I know!",
  ui_story_5036_50361501_34_dialog_content = "<color=#e8d9bb>Rumble...</color>",
  ui_story_5036_50361501_35_dialog_content = "The whole Colossus is shaking! Is the final boss about to appear?!",
  ui_story_5036_50361501_36_dialog_content = "Hang on tight, everyone! It looks like something is coming out of the Colossus!",
  ui_story_5036_50361501_37_dialog_content = "Kree—!",
  ui_story_5036_50361501_38_dialog_content = "A dragon?! It's massive!!",
  ui_story_5036_50361501_39_dialog_content = "So it really hatched!",
  ui_story_5036_50361501_40_dialog_content = "Graagh!!!",
  ui_story_5036_50361501_41_dialog_content = "The Eclipsites are starting to attack the Ouroboros!",
  ui_story_5036_50361501_42_dialog_content = "Kree—Kree—!",
  ui_story_5036_50361501_43_dialog_content = "Look, sis! There, at the top of the Colossus!",
  ui_story_5036_50361501_44_dialog_content = "Is that... a dragon?!",
  ui_story_5036_50361501_45_dialog_content = "Hey! The Colossus is shaking so hard. It's gonna fall out of the sky!",
  ui_story_5036_50361501_46_dialog_content = "<color=#e8d9bb>BOOM!!!</color>",
  ui_story_5036_50361501_47_dialog_content = "This is bad! The Ouroboros just hatched. It can't fly yet!",
  ui_story_5036_50361501_48_dialog_content = "The Eclipsites' attacks are just gonna make it struggle even fiercer!",
  ui_story_5036_50361501_49_dialog_content = "Is there any way to calm it down first?",
  ui_story_5036_50361501_50_dialog_content = "How about using your psychic abilities?",
  ui_story_5036_50361501_51_dialog_content = "I'll try.",
  ui_story_5036_50361501_52_option_content = "\"Stop, Ouroboros!\"",
  ui_story_5036_50361501_53_dialog_content = "Kree—!",
  ui_story_5036_50361501_54_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5036_50361501_55_dialog_content = "Ah!",
  ui_story_5036_50361501_56_dialog_content = "It won't listen to me at all!",
  ui_story_5036_50361501_57_dialog_content = "The Eclipsites have... surrounded the stage.",
  ui_story_5036_50361501_58_dialog_content = "The concert... it totally ruined...",
  ui_story_5036_50361501_59_dialog_content = "Goldie, get a grip! We're still in danger!",
  ui_story_5036_50361501_60_dialog_content = "I know, but...",
  ui_story_5036_50361501_61_dialog_content = "There's no time to waste. Positions, everyone! We must put a distance between the Eclipsites and the dragon!",
  ui_story_5036_50361501_62_dialog_content = "Yes!",
  ui_story_5036_50361501_63_dialog_content = "Illumina's not gonna back down either! The boss battle has just begun!",
  ui_story_5036_50361501_64_dialog_content = "Yes!!!",
  ui_story_5036_50361501_65_dialog_content = "Vice, PlayerName! You two cover and escort the civilians away from the battle area!",
  ui_story_5036_50361501_66_dialog_content = "Contact Soroz and Lumopolis' airships and come up with an evacuation plan!",
  ui_story_5036_50361501_67_dialog_content = "Alright, leave it to me!",
  ui_story_5036_50361501_68_dialog_content = "All right!",
  ui_story_5036_50361501_69_dialog_content = "The Knights of Lumopolis are so reliable in times of danger like this!",
  ui_story_5036_50361501_70_dialog_content = "Don't you have something to do? Find a way to calm that dragon down.",
  ui_story_5036_50361501_71_dialog_content = "Spare me, I'm not a fighter...",
  ui_story_5036_50361501_72_dialog_content = "You... Never mind. Evacuate with the rest, then.",
  ui_story_5036_50361501_73_dialog_content = "No problem. I'll just see myself out now.",
  ui_story_5036_50361501_74_dialog_content = "Everyone, get over here!",
  ui_story_5036_50361501_75_dialog_content = "How's Soroz, PlayerName?",
  ui_story_5036_50361501_76_dialog_content = "The Ouroboros isn't calming down. Soroz can't link up with it!",
  ui_story_5036_50361501_77_dialog_content = "If only there was a way to calm it down for even just a sec...",
  ui_story_5036_50361501_78_dialog_content = "But it doesn't seem like it's gonna do that, at least not for a long while.",
  ui_story_5036_50361501_79_dialog_content = "Where are the Lumopolis airships?",
  ui_story_5036_50361501_80_dialog_content = "Obviously I've contacted them already.",
  ui_story_5036_50361501_81_dialog_content = "The concert already attracted a few nobles with their airships. Several of them are already helping with the evacuation.",
  ui_story_5036_50361501_82_dialog_content = "The City Lord is sending all available airships in Lumopolis here, but it'll still take some time.",
  ui_story_5036_50361501_83_dialog_content = "Not to mention Lumopolis only has small airships more often than not. It will take quite a few trips to ferry all those people out of here.",
  ui_story_5036_50361501_84_dialog_content = "We gotta buy them more time.",
  ui_story_5036_50361501_85_dialog_content = "Urgh—!",
  ui_story_5036_50361501_X85_dialog_content = "Hold steady!",
  ui_story_5036_50361501_87_dialog_content = "<color=#e8d9bb>Creak—</color>",
  ui_story_5036_50361501_88_dialog_content = "Lady Carleen, there are too many Eclipsites! We can't hold our lines!",
  ui_story_5036_50361501_89_dialog_content = "Ahh, everyone from Lumopolis, we better get away from there!",
  ui_story_5036_50361501_90_dialog_content = "The dragon is struggling way too fiercely, and the Colossus is just too old—",
  ui_story_5036_50361501_91_dialog_content = "Many of its parts can't take the beating, it's beginning to fall apart!",
  ui_story_5036_50361501_92_dialog_content = "Where are the airships?",
  ui_story_5036_50361501_93_dialog_content = "Report! Soroz is unable to connect, but airships from Lumopolis are on their way!",
  ui_story_5036_50361501_94_dialog_content = "We're out of options! Contact all teams to draw back. Stop defending the Ouroboros for now and move toward the people!",
  ui_story_5036_50361501_95_dialog_content = "Yes!",
  ui_story_5036_50361501_96_dialog_content = "Carleen!",
  ui_story_5036_50361501_97_dialog_content = "I'm fine, is everyone here?",
  ui_story_5036_50361501_98_dialog_content = "They are all here, Lady Carleen!",
  ui_story_5036_50361501_99_dialog_content = "The first batch of airships has arrived. Evacuation is underway, but...",
  ui_story_5036_50361501_100_dialog_content = "It needs time.",
  ui_story_5036_50361501_101_dialog_content = "Airships too small. Too many people.",
  ui_story_5036_50361501_102_dialog_content = "I'll do my best to buy you time.",
  ui_story_5036_50361501_103_dialog_content = "Hurry! The Colossus may tip over at any time!",
  ui_story_5036_50361501_104_dialog_content = "Sob... I...",
  ui_story_5036_50361501_105_dialog_content = "Are you okay, Goldie?",
  ui_story_5036_50361501_106_dialog_content = "I'm fine... the concert is all ruined, but I'm fine...",
  ui_story_5036_50361501_107_dialog_content = "Still, I have to protect my fans. They can't get hurt because of me!",
  ui_story_5036_50361501_108_dialog_content = "Even if... this is my last concert!",
  ui_story_5036_50361501_109_dialog_content = "Yup, let's focus on the issues at hand first.",
  ui_story_5036_50361501_110_dialog_content = "By the way Vic, can the Ouroboros really not—Vic?",
  ui_story_5036_50361501_111_dialog_content = "Where has he run off to now?",
  ui_story_5036_50361501_112_dialog_content = "Didn't he evacuate with you?",
  ui_story_5036_50361501_113_dialog_content = "I thought he was behind me, so I didn't pay much attention!",
  ui_story_5036_50361501_114_dialog_content = "Oh, I really am not a fighter at all.",
  ui_story_5036_50361501_115_dialog_content = "I think I hear him?",
  ui_story_5036_50361501_116_dialog_content = "There he is!",
  ui_story_5036_50361501_117_dialog_content = "Well, since I call myself an extrozoologist, I better start acting like one.",
  ui_story_5036_50361501_118_dialog_content = "Why is he over there all by himself?",
  ui_story_5036_50361501_119_dialog_content = "Get back here! It's dangerous!",
  ui_story_5036_50361501_120_dialog_content = "Thanks for the reminder, but I can't. Not just yet.",
  ui_story_5036_50361501_121_dialog_content = "Hey, you! You icky, ghostly things! Over here!",
  ui_story_5036_50361501_122_dialog_content = "Peeeko! Hiss—!",
  ui_story_5036_50361501_123_dialog_content = "Grrrr...",
  ui_story_5036_50361501_124_dialog_content = "Yes! That's it...",
  ui_story_5036_50361501_125_dialog_content = "Why go after an Ouroboros when there's a defenseless Aurorian right here?",
  ui_story_5036_50361501_126_dialog_content = "(Just a little closer... Gotta lead them away from the Ouroboros.)",
  ui_story_5036_50361501_127_dialog_content = "(The Lutumi Owl should be enough to hold their attention and buy some time.)",
  ui_story_5036_50361501_128_option_content = "Vic, get back here!",
  ui_story_5036_50361501_129_dialog_content = "Hahaha! Don't worry about it, I'm totally fine!",
  ui_story_5036_50361501_130_dialog_content = "Only the best extrozoologist could entrust his life to his wondrous beasts!",
  ui_story_5036_50361501_131_dialog_content = "Gahhhhhh—!",
  ui_story_5036_50361501_132_dialog_content = "(Good! They took the bait!)",
  ui_story_5036_50361501_133_dialog_content = "(Now, all I need is to summon the Lutumi Owl!)",
  ui_story_5036_50361501_134_dialog_content = "Lutumi Owl!",
  ui_story_5036_50361501_135_dialog_content = "Hoot—hoot hoot!",
  ui_story_5036_50361501_136_dialog_content = "Why are you running away, Lutumi Owl!? Get back here—!",
  ui_story_5036_50361501_137_dialog_content = "<color=#e8d9bb>Rumble!</color>",
  ui_story_5036_50361501_138_dialog_content = "Kree!",
  ui_story_5036_50361501_139_dialog_content = "What?!",
  ui_story_5036_50361501_140_dialog_content = "<color=#e8d9bb>Whoosh—Bang!</color>",
  ui_story_5036_50361501_141_dialog_content = "Vic?",
  ui_story_5036_50361501_142_dialog_content = "Ouch, ouch, ouch!",
  ui_story_5036_50361501_143_dialog_content = "(The Ouroboros' tail sent him flying! Wait a minute! That's...!)",
  ui_story_5036_50361501_144_dialog_content = "Vic! Run!",
  ui_story_5036_50361501_145_dialog_content = "Tsk! That dragon really doesn't know how to be gentle.",
  ui_story_5036_50361501_146_dialog_content = "PlayerName, what did you say? I didn't hear you!",
  ui_story_5036_50361501_147_dialog_content = "Gahhhh!",
  ui_story_5036_50361501_148_dialog_content = "Gosh... I-I'm surrounded!",
  ui_story_5036_50361501_149_dialog_content = "Hey, Eclipsites, I'm old, and that makes me taste bad!",
  ui_story_5036_50361501_150_dialog_content = "Look at the Caelestite over there! He's young and tender! And much juicier than I am!",
  ui_story_5036_50361501_151_dialog_content = "Graaaaaah!!!",
  ui_story_5036_50361501_152_dialog_content = "Save me, Little Furball!",
  ui_story_5036_50361501_153_dialog_content = "PlayerName!",
  ui_story_5036_50361502_1_dialog_content = "Fabulous! I'm still alive!",
  ui_story_5036_50361502_2_dialog_content = "Even though my whole plan to draw the Eclipsites' attention failed.",
  ui_story_5036_50361502_3_dialog_content = "How are you in the mood to laugh!?",
  ui_story_5036_50361502_4_dialog_content = "If you have a plan, you need to tell us about it!",
  ui_story_5036_50361502_5_dialog_content = "Sorry, sorry! I was so concerned about the Ouroboros' safety that I totally forgot.",
  ui_story_5036_50361502_6_dialog_content = "But, just for the record, my plan would've succeeded if it didn't send me flying.",
  ui_story_5036_50361502_7_dialog_content = "This isn't the time to be discussing would-haves!",
  ui_story_5036_50361502_8_dialog_content = "Is there any other way to calm it down?",
  ui_story_5036_50361502_9_dialog_content = "Unfortunately, I can't think of anything other than defeating all the Eclipsites.",
  ui_story_5036_50361502_10_dialog_content = "Can't we wait for the Ouroboros to muster enough strength to fly away by itself?",
  ui_story_5036_50361502_11_dialog_content = "That's a little too optimistic. The Eclipsites are not backing down at all.",
  ui_story_5036_50361502_12_dialog_content = "If this keeps up, even if the Ouroboros can fly again, it would be too wounded to.",
  ui_story_5036_50361502_13_dialog_content = "How...",
  ui_story_5036_50361502_14_dialog_content = "Lady Carleen, we've received orders from the City Lord.",
  ui_story_5036_50361502_15_dialog_content = "Go on.",
  ui_story_5036_50361502_16_dialog_content = "The evacuation is almost complete. Both the Illumina and Lumopolis administrations have completed their risk evaluation of the Colossus.",
  ui_story_5036_50361502_17_dialog_content = "They've decided to leave the soldiers behind to hold the Eclipsites back, keep the dragon under control, and maintain the Colossus' balance.",
  ui_story_5036_50361502_18_dialog_content = "Once the Colossus is out of Umbraton, they will shoot it down.",
  ui_story_5036_50361502_19_dialog_content = "You want to shoot the Colossus down along with the Ouroboros!? No way!",
  ui_story_5036_50361502_20_dialog_content = "It may be the last of its kind! They'll go completely extinct if you do that!",
  ui_story_5036_50361502_21_dialog_content = "And I'm not gonna lose Eulogoz!",
  ui_story_5036_50361502_22_dialog_content = "Do you have a better idea? If you don't, then shut up.",
  ui_story_5036_50361502_23_dialog_content = "The Colossus is right above the most populated area of Umbraton. We're not going to risk the lives of millions of Aurorians!",
  ui_story_5036_50361502_24_dialog_content = "What if I refuse to leave the Colossus?",
  ui_story_5036_50361502_25_dialog_content = "Vic, what are you saying—?",
  ui_story_5036_50361502_26_dialog_content = "I am an extrozoologist. There's no way I'm going to let harm come to that Ouroboros.",
  ui_story_5036_50361502_27_dialog_content = "If you want to shoot the Colossus down, you'll have to take me down with it.",
  ui_story_5036_50361502_28_dialog_content = "Vic, that's dangerous!",
  ui_story_5036_50361502_29_dialog_content = "Stop fooling around!",
  ui_story_5036_50361502_30_dialog_content = "(What do I do? How can I save the Ouroboros and the Colossus?)",
  ui_story_5036_50361502_31_dialog_content = "(There must be a way...)",
  ui_story_5036_50361502_32_dialog_content = "They'll definitely be able to hear my voice on the ground through the equipment!",
  ui_story_5036_50361502_33_dialog_content = "How amazing, the creature could communicate using the melody Caelestites use to control Colossi.",
  ui_story_5036_50361502_34_dialog_content = "By writing your song with a melody used to activate the Colossi, you may have unintentionally given the Ouroboros the wake-up call it needed to hatch!",
  ui_story_5036_50361502_35_dialog_content = "There's another way that I want to try!",
  ui_story_5036_50361502_36_dialog_content = "Huh?",
  ui_story_5036_50361502_37_dialog_content = "What is it?",
  ui_story_5036_50361502_38_dialog_content = "Chaminade discovered that the Ouroboros could understand the melodies Caelestites used to control Colossi.",
  ui_story_5036_50361502_39_dialog_content = "If we can play the melody that shuts down the Colossus and stop the Eclipsites at the same time, maybe we can calm it down.",
  ui_story_5036_50361502_40_dialog_content = "That's worth a try.",
  ui_story_5036_50361502_41_dialog_content = "Would a song work if even PlayerName's psychic abilities can't reach the dragon?",
  ui_story_5036_50361502_42_dialog_content = "Well... As long as it's loud enough, we should be able to get its attention.",
  ui_story_5036_50361502_43_dialog_content = "We can use the stage's speaker system!",
  ui_story_5036_50361502_44_dialog_content = "Yeah. I'll need Goldie's help. We should be able to do it with her Luminatics and the equipment!",
  ui_story_5036_50361502_45_dialog_content = "Me?",
  ui_story_5036_50361502_46_dialog_content = "...",
  ui_story_5036_50361502_47_dialog_content = "Got it.",
  ui_story_5036_50361502_48_dialog_content = "My concert can't end before I've finished my song.",
  ui_story_5036_50361502_49_dialog_content = "Even if I can no longer take the stage as an idol in the future, as long as you and my fans are out there...",
  ui_story_5036_50361502_50_dialog_content = "I'll sing for you all whenever you need me to.",
  ui_story_5036_50361502_51_dialog_content = "Not to mention that Umbraton is right beneath us. It's my home, and the home of my fans.",
  ui_story_5036_50361502_52_dialog_content = "How sure are you that this will work, PlayerName?",
  ui_story_5036_50361502_53_option_content = "I can't promise you anything...",
  ui_story_5036_50361502_54_option_content = "I want to give it a shot!",
  ui_story_5036_50361502_55_dialog_content = "Alright.",
  ui_story_5036_50361502_56_dialog_content = "I'll help.",
  ui_story_5036_50361502_57_dialog_content = "Lady Carleen! Are you serious?",
  ui_story_5036_50361502_58_dialog_content = "Of course. And I will also provide support if it fails.",
  ui_story_5036_50361502_59_dialog_content = "Notify all teams to be on standby!",
  ui_story_5036_50361502_60_dialog_content = "Understood. Knights, form up!",
  ui_story_5036_50361502_61_dialog_content = "Carleen, thanks so much!",
  ui_story_5036_50361502_62_dialog_content = "I'll help too!",
  ui_story_5036_50361502_63_dialog_content = "But the crew that handles the speaker system already left on an airship.",
  ui_story_5036_50361502_64_dialog_content = "Don't forget us! We've got this.",
  ui_story_5036_50361502_65_dialog_content = "The equipment may be modified, but they are still very much the same. Leave them to us.",
  ui_story_5036_50361502_66_dialog_content = "Gronru, Siobhan!?",
  ui_story_5036_50361502_67_dialog_content = "PlayerName, you're trying to challenge some super hard stages, right?",
  ui_story_5036_50361502_68_dialog_content = "How could I miss out on something so fun?",
  ui_story_5036_50361502_69_dialog_content = "A-And me!",
  ui_story_5036_50361502_70_dialog_content = "I've been interviewing people the last few days, including the ones who handled the speaker system.",
  ui_story_5036_50361502_71_dialog_content = "I also learned a thing or two from them!",
  ui_story_5036_50361502_72_dialog_content = "This seems like a crazy endeavor, but please let me tag along! I will do my best to help Goldie and you!",
  ui_story_5036_50361502_73_dialog_content = "Thanks...",
  ui_story_5036_50361502_74_dialog_content = "PlayerName, you sure have a way of uniting everyone.",
  ui_story_5036_50361502_75_dialog_content = "This ability alone makes the Caelestite a wondrous beast.",
  ui_story_5036_50361502_76_dialog_content = "Hang on, I'm not a wondrous beast!",
  ui_story_5036_50361502_77_dialog_content = "Hahah. There's no time to debate.",
  ui_story_5036_50361502_78_dialog_content = "We're short on time. Let's save the Ouroboros first!",
  ui_story_5036_50361502_79_dialog_content = "Right. To the stage!",
  ui_story_5036_50361601_1_dialog_content = "Goldie, did you memorize the melody I taught you?",
  ui_story_5036_50361601_2_dialog_content = "Of course! Every note of it!",
  ui_story_5036_50361601_3_dialog_content = "But there are so many Eclipsites in our way...",
  ui_story_5036_50361601_4_dialog_content = "Don't worry. We'll take care of them and clear the way for you.",
  ui_story_5036_50361601_5_dialog_content = "Yeah. Leave the combat to us. You just focus on singing!",
  ui_story_5036_50361601_6_dialog_content = "Indeed. I can't fight, but Little Furball will help.",
  ui_story_5036_50361601_7_dialog_content = "Chirp!",
  ui_story_5036_50361601_8_dialog_content = "Thank you for still wanting to help me, Goldie.",
  ui_story_5036_50361601_9_dialog_content = "No need to thank me.",
  ui_story_5036_50361601_10_dialog_content = "You've been helping me for the past few days, PlayerName.",
  ui_story_5036_50361601_11_dialog_content = "If it weren't for your help, this concert would never have come to be.",
  ui_story_5036_50361601_12_dialog_content = "But it got ruined...",
  ui_story_5036_50361601_13_dialog_content = "Even so, I know how much effort you put in.",
  ui_story_5036_50361601_14_dialog_content = "The concert's failure doesn't change that fact.",
  ui_story_5036_50361601_15_dialog_content = "So now, it's time I repay you!",
  ui_story_5036_50361601_16_dialog_content = "Okay!",
  ui_story_5036_50361601_17_dialog_content = "Let's go, then!",
  ui_story_5036_50361601_18_dialog_content = "Graaaaaah!!!",
  ui_story_5036_50361601_19_dialog_content = "Eclipsites incoming! Prepare for battle!",
  ui_story_5036_50361602_1_dialog_content = "We've reached the stage! How's the equipment?",
  ui_story_5036_50361602_2_dialog_content = "The equipment is fine!",
  ui_story_5036_50361602_3_dialog_content = "Volume output at max—!",
  ui_story_5036_50361602_4_dialog_content = "Grahhhhhh—!",
  ui_story_5036_50361602_5_dialog_content = "Huh?!",
  ui_story_5036_50361602_6_dialog_content = "Rapid Torrent!",
  ui_story_5036_50361602_7_dialog_content = "Th-Thanks!",
  ui_story_5036_50361602_8_dialog_content = "You're welcome.",
  ui_story_5036_50361602_9_dialog_content = "Leave the Eclipsites to us! You just focus on handling the equipment!",
  ui_story_5036_50361602_10_dialog_content = "As long as we are still here, we won't let any Eclipsite through!",
  ui_story_5036_50361602_11_dialog_content = "Grahhhh!",
  ui_story_5036_50361602_12_dialog_content = "Don't even think of escaping!",
  ui_story_5036_50361602_13_dialog_content = "Here's your chance! Little Furball, attack its back!",
  ui_story_5036_50361602_14_dialog_content = "Chirp!",
  ui_story_5036_50361602_15_dialog_content = "Grahhhh—",
  ui_story_5036_50361602_16_dialog_content = "Wow, that thing's fast. Even Little Furball has trouble catching up to it.",
  ui_story_5036_50361602_17_dialog_content = "It keeps on running around. How troublesome!",
  ui_story_5036_50361602_18_dialog_content = "Hang on! Don't let it interfere with Goldie's singing, at the very least!",
  ui_story_5036_50361602_19_dialog_content = "Right!",
  ui_story_5036_50361602_20_dialog_content = "(Everyone is fighting. I have to do my job.)",
  ui_story_5036_50361602_21_dialog_content = "Kree—Kree!",
  ui_story_5036_50361602_22_dialog_content = "<color=#e8d9bb>Rumble—!</color>",
  ui_story_5036_50361602_23_dialog_content = "Ouroboros, you're struggling too, aren't you?",
  ui_story_5036_50361602_24_dialog_content = "Just hang on a little bit longer. Trust us. We'll protect you.",
  ui_story_5036_50361602_25_dialog_content = "Uhm... I'm gonna start singing!",
  ui_story_5036_50361602_26_dialog_content = "Got it!",
  ui_story_5036_50361602_27_dialog_content = "(Calm down, Goldie.)",
  ui_story_5036_50361602_28_dialog_content = "(Soothe the Ouroboros' nerves with this song, and calm it down.)",
  ui_story_5036_50361602_29_dialog_content = "(Make this song worthy of a final farewell to the stage, and to life as an idol.)",
  ui_story_5036_50361602_30_dialog_content = "Ouroboros, listen to my song!",
  ui_story_5036_50361602_31_dialog_content = "♪ The world is vast, the universe an ocean ♪",
  ui_story_5036_50361602_32_dialog_content = "♪ We are born like meteorites, playful and bright ♪",
  ui_story_5036_50361602_33_dialog_content = "♪ We play with joy, but at times we tire ♪",
  ui_story_5036_50361602_34_dialog_content = "♪ The lights of home, guide us warmly to our nests ♪",
  ui_story_5036_50361602_35_dialog_content = "Everyone, follow the instructions and evacuate! The Shadowlord will ensure your safety!",
  ui_story_5036_50361602_36_dialog_content = "♪ The lights of home, guide us warmly to our nests ♪",
  ui_story_5036_50361602_37_dialog_content = "Sis, do you hear that?",
  ui_story_5036_50361602_38_dialog_content = "It's singing!",
  ui_story_5036_50361602_39_dialog_content = "Miss, all the evacuated people have exited the airship.",
  ui_story_5036_50361602_40_dialog_content = "Okay. Get ready to go out again and evacuate the next group of civilians!",
  ui_story_5036_50361602_41_dialog_content = "♪ The lights of home, guide us warmly to our nests ♪",
  ui_story_5036_50361602_42_dialog_content = "Is that... singing?",
  ui_story_5036_50361602_43_dialog_content = "Such a gentle voice. Is it coming from the Colossus?",
  ui_story_5036_50361602_44_dialog_content = "♪ Exhausted child, go to sleep ♪",
  ui_story_5036_50361602_45_dialog_content = "♪ May this lullaby, guard your dreams ♪",
  ui_story_5036_50361602_46_dialog_content = "♪ This is your home ♪",
  ui_story_5036_50361602_47_dialog_content = "Kree—!",
  ui_story_5036_50361602_48_dialog_content = "(The Ouroboros seems to be responding!)",
  ui_story_5036_50361602_49_dialog_content = "Carleen, PlayerName! It seems to be calming down!",
  ui_story_5036_50361602_50_dialog_content = "Great! The song is working!",
  ui_story_5036_50361602_51_dialog_content = "The Colossus has stopped rocking. This will work!",
  ui_story_5036_50361602_52_dialog_content = "Advance on the Eclipsites!",
  ui_story_5036_50361602_53_dialog_content = "♪ This is your home ♪",
  ui_story_5036_50361602_54_dialog_content = "A song?",
  ui_story_5036_50361602_55_dialog_content = "It's the melody that shuts the Colossus down. It's gentle like a lullaby.",
  ui_story_5036_50361602_56_dialog_content = "Is that Goldie singing? But...",
  ui_story_5036_50361602_57_dialog_content = "♪ Now that home is no more ♪",
  ui_story_5036_50361602_58_dialog_content = "(I seem to be hearing Chaminade singing!)",
  ui_story_5036_50361602_59_dialog_content = "(She must be devastated. I didn't even get the chance to comfort her...)",
  ui_story_5036_50361602_60_dialog_content = "(She may just be a figure from a dream, and doesn't really exist.)",
  ui_story_5036_50361602_61_dialog_content = "(But her sadness and loneliness are so real.)",
  ui_story_5036_50361602_62_dialog_content = "(Then I shall dedicate this song to you, Chaminade.)",
  ui_story_5036_50361602_63_dialog_content = "(And hope it takes away your sadness.)",
  ui_story_5036_50361602_64_dialog_content = "♪ Now that home is no more ♪",
  ui_story_5036_50361602_65_dialog_content = "♪ Still, do youngsters set off on journeys ♪",
  ui_story_5036_50361602_66_dialog_content = "♪ Through tears that flow through the night ♪",
  ui_story_5036_50361602_67_dialog_content = "♪ Through sorrows and joys, departures and reunions ♪",
  ui_story_5036_50361602_68_dialog_content = "♪ Can they still see the dawning light of hope? ♪",
  ui_story_5036_50361602_69_dialog_content = "♪ The light that must still be waiting ahead ♪",
  ui_story_5036_50361602_70_dialog_content = "Rapid Torrent!",
  ui_story_5036_50361602_71_dialog_content = "How many more are there...?",
  ui_story_5036_50361602_72_dialog_content = "Grah!!!",
  ui_story_5036_50361602_73_dialog_content = "Watch it! It's coming back!",
  ui_story_5036_50361602_74_dialog_content = "I won't let you get close!",
  ui_story_5036_50361602_75_dialog_content = "Is that your song, Goldie?",
  ui_story_5036_50361602_76_dialog_content = "It's so warm, like the sun and wind in Eraveil.",
  ui_story_5036_50361602_77_dialog_content = "I see now. Even if Eraveil was destroyed, it's not gone. Home... can be rebuilt.",
  ui_story_5036_50361602_78_dialog_content = "Goldie, I hear you.",
  ui_story_5036_50361602_79_dialog_content = "So, I should—",
  ui_story_5036_50361602_80_dialog_content = "♪ Try wiping those tears ♪",
  ui_story_5036_50361602_81_dialog_content = "♪ Wipe away those tears, set off again— ♪",
  ui_story_5036_50361602_82_dialog_content = "♪ Spread this song afar ♪",
  ui_story_5036_50361602_83_dialog_content = "Thank you, Goldie.",
  ui_story_5036_50361602_84_dialog_content = "Idol from the future, I entrust Ouroboros and the future to you.",
  ui_story_5036_50361602_85_dialog_content = "Chaminade... seems to be completely gone.",
  ui_story_5036_50361602_86_dialog_content = "Kree—",
  ui_story_5036_50361602_87_dialog_content = "The Ouroboros has calmed down!",
  ui_story_5036_50361602_88_dialog_content = "It worked! PlayerName, your plan worked!",
  ui_story_5036_50361602_89_dialog_content = "That's great!",
  ui_story_5036_50361602_90_dialog_content = "But we can't hold on any longer here!",
  ui_story_5036_50361602_91_dialog_content = "Urgh!",
  ui_story_5036_50361602_92_dialog_content = "Grah!!!",
  ui_story_5036_50361602_93_dialog_content = "Rapid Torrent!",
  ui_story_5036_50361602_94_dialog_content = "Grahh! Grah!",
  ui_story_5036_50361602_95_dialog_content = "How is this thing still alive?!",
  ui_story_5036_50361602_96_dialog_content = "Any Eclipsite that can survive on this Colossus should be no pushover.",
  ui_story_5036_50361602_97_dialog_content = "Just hang on. The Ouroboros should be able to fly any minute now!",
  ui_story_5036_50361602_98_dialog_content = "Roar—!",
  ui_story_5036_50361602_99_dialog_content = "Watch out, Carleen!",
  ui_story_5036_50361602_100_dialog_content = "Kree!",
  ui_story_5036_50361602_101_dialog_content = "<color=#e8d9bb>Slap—!</color>",
  ui_story_5036_50361602_102_dialog_content = "Roar—",
  ui_story_5036_50361602_103_dialog_content = "Whoa! Wh-What...?",
  ui_story_5036_50361602_104_dialog_content = "The Ouroboros sent that Eclipsite flying with its tail!",
  ui_story_5036_50361602_105_dialog_content = "Kree, kree!",
  ui_story_5036_50361602_106_dialog_content = "It doesn't look afraid anymore! It's happy!",
  ui_story_5036_50361602_107_dialog_content = "That was brilliant! Without that Eclipsite messing around, the rest should be easy to handle.",
  ui_story_5036_50361602_108_dialog_content = "Ice Blossom!",
  ui_story_5036_50361602_109_dialog_content = "Grrrr...",
  ui_story_5036_50361602_110_dialog_content = "Kree—!",
  ui_story_5036_50361602_111_dialog_content = "<color=#e8d9bb>Crash—</color>",
  ui_story_5036_50361602_112_dialog_content = "The Colossus is rocking again!?",
  ui_story_5036_50361602_113_dialog_content = "The Ouroboros calmed down though.",
  ui_story_5036_50361602_114_dialog_content = "Hang on! It seems to be taking flight!",
  ui_story_5036_50361602_115_dialog_content = "Kree—!",
  ui_story_5036_50361602_116_dialog_content = "Kree!",
  ui_story_5036_50361602_117_dialog_content = "Look, the dragon on the Colossus just took off!",
  ui_story_5036_50361602_118_dialog_content = "It's true! Is Goldie still on the Colossus? Is she safe?",
  ui_story_5036_50361602_119_dialog_content = "She's an amazing idol.",
  ui_story_5036_50361602_120_dialog_content = "No matter what lies ahead, she'll make it through.",
  ui_story_5036_50361602_121_dialog_content = "So... just believe in her.",
  ui_story_5036_50361602_122_dialog_content = "Right!",
  ui_story_5036_50361602_123_dialog_content = "I believe in her too!",
  ui_story_5036_50361602_124_dialog_content = "Alright. You should join the others in the evacuation.",
  ui_story_5036_50361602_125_dialog_content = "Now that the dragon's flown off, is everything over?",
  ui_story_5036_50361602_126_dialog_content = "I have to contact them and confirm the situation.",
  ui_story_5036_50361602_127_dialog_content = "Report! All personnel evacuated from the Wandering Colossus have been secured.",
  ui_story_5036_50361602_128_dialog_content = "Only a few suffered minor injuries. No heavy injuries or deaths!",
  ui_story_5036_50361602_129_dialog_content = "Fortunately, the City Lord was on an airship near the Wandering Colossus.",
  ui_story_5036_50361602_130_dialog_content = "Lumopolis was only able to respond so rapidly and minimize injuries because of this.",
  ui_story_5036_50361602_131_dialog_content = "What's the current situation with the Colossus and the dragon?",
  ui_story_5036_50361602_132_dialog_content = "The dragon left the Colossus, but Carleen and the rest are still onboard.",
  ui_story_5036_50361602_133_dialog_content = "...",
  ui_story_5036_50361602_134_dialog_content = "PlayerName and Vice are there, so Carleen must be safe!",
  ui_story_5036_50361602_135_dialog_content = "Order the airships to continue with the evacuation of the personnel onboard the Colossus.",
  ui_story_5036_50361602_136_dialog_content = "Yes, sir!",
  ui_story_5036_50361602_137_dialog_content = "<color=#e8d9bb>Rumble!</color>",
  ui_story_5036_50361602_138_dialog_content = "Huh?!",
  ui_story_5036_50361602_139_dialog_content = "Is the Colossus tipping over?!",
  ui_story_5036_50361602_140_dialog_content = "Aah?!",
  ui_story_5036_50361602_141_dialog_content = "The Ouroboros' departure changed the balance of the Colossus!",
  ui_story_5036_50361602_142_dialog_content = "It's gaining altitude!",
  ui_story_5036_50361602_143_dialog_content = "The plan was a great success!",
  ui_story_5036_50361602_144_dialog_content = "Let's hurry and get out of here. There are too many Eclipsites. They outnumber us!",
  ui_story_5036_50361602_145_dialog_content = "PlayerName!",
  ui_story_5036_50361602_146_dialog_content = "The Ouroboros flew off. We succeeded!",
  ui_story_5036_50361602_147_dialog_content = "What a blessed conclusion for us all!",
  ui_story_5036_50361602_148_option_content = "Where's Chaminade?",
  ui_story_5036_50361602_149_dialog_content = "I thought I heard her singing with you.",
  ui_story_5036_50361602_150_dialog_content = "I think she's already gone...",
  ui_story_5036_50361602_151_dialog_content = "Not gone with the Ouroboros, but gone completely.",
  ui_story_5036_50361602_152_dialog_content = "I see...",
  ui_story_5036_50361602_153_dialog_content = "Yeah. She said she would entrust everything to me.",
  ui_story_5036_50361602_154_dialog_content = "She probably wants this song to be heard by all of Astra.",
  ui_story_5036_50361602_155_option_content = "What about Eulogoz?",
  ui_story_5036_50361602_156_dialog_content = "It's fine now, but the Ouroboros' departure deviated its path.",
  ui_story_5036_50361602_157_dialog_content = "It's gaining altitude.",
  ui_story_5036_50361602_158_dialog_content = "PlayerName, there's no time for chit-chat. Let's get out of here!",
  ui_story_5036_50361602_159_dialog_content = "The Ouroboros' departure changed Eulogoz's route and the lightened load made it accelerate.",
  ui_story_5036_50361602_160_dialog_content = "Yeah, at the rate it's going now, we'll be so high up that we won't be able to breathe in ten minutes or so.",
  ui_story_5036_50361602_161_dialog_content = "Let's hurry up and get out of here!",
  ui_story_5036_50361602_162_dialog_content = "But Eulogoz—",
  ui_story_5036_50361602_163_dialog_content = "Eulogoz may never return...",
  ui_story_5036_50361602_164_dialog_content = "Even Gronru can't fix Eulogoz's control system in such a short time.",
  ui_story_5036_50361602_165_dialog_content = "Then wasn't all our effort for nothing?",
  ui_story_5036_50361602_166_dialog_content = "Not at all!",
  ui_story_5036_50361602_167_dialog_content = "The concert may not have gone as planned, but we got to share it with everyone in the interim.",
  ui_story_5036_50361602_168_dialog_content = "And we got to learn about Eulogoz and Chaminade through our adventure.",
  ui_story_5036_50361602_169_dialog_content = "As long as we don't forget them, they will always be with us.",
  ui_story_5036_50361602_170_dialog_content = "...",
  ui_story_5036_50361602_171_option_content = "Let's go.",
  ui_story_5036_50361602_172_option_content = "I'll never forget them.",
  ui_story_5036_50361602_173_dialog_content = "Yup!",
  ui_story_5036_50361602_174_dialog_content = "PlayerName, we're running out of time.",
  ui_story_5036_50361602_175_dialog_content = "Let's head back.",
  ui_story_5036_50361602_176_dialog_content = "Right.",
  ui_story_5036_50361602_177_dialog_content = "I'm sorry, Eulogoz.",
  ui_story_5036_50361602_178_dialog_content = "Goodbye.",
  ui_story_5036_50361701_1_dialog_content = "Engage, Soroz!",
  ui_story_5036_50361701_2_dialog_content = "<color=#e8d9bb>Rumble!</color>",
  ui_story_5036_50361701_3_dialog_content = "Eulogoz is flying higher and higher, towards the universe up above.",
  ui_story_5036_50361701_4_dialog_content = "It's going to bring Chaminade's song to the stars.",
  ui_story_5036_50361701_5_dialog_content = "No matter what, we're finally safe.",
  ui_story_5036_50361701_6_dialog_content = "Even though the concert failed, and we couldn't save Eulogoz.",
  ui_story_5036_50361701_7_dialog_content = "Everyone's safe now. The people of Umbraton don't have to fear anymore. That has to be enough.",
  ui_story_5036_50361701_8_dialog_content = "What I still don't understand is why the Ouroboros suddenly hatched.",
  ui_story_5036_50361701_9_dialog_content = "If only it hatched a little bit later, things would be so different now...",
  ui_story_5036_50361701_10_dialog_content = "Actually, I gave it some thought, and I think it's because of me.",
  ui_story_5036_50361701_11_dialog_content = "In my dream... No, actually, it was Ouroboros' dream. I met Chaminade.",
  ui_story_5036_50361701_12_dialog_content = "Met? Don't you mean you dreamt of her?",
  ui_story_5036_50361701_13_dialog_content = "No. I met her.",
  ui_story_5036_50361701_14_dialog_content = "Who or what really is Chaminade?",
  ui_story_5036_50361701_15_dialog_content = "Could there really be a way for the dead to continue to exist?",
  ui_story_5036_50361701_16_dialog_content = "The mere thought of it gives me the chills...",
  ui_story_5036_50361701_17_dialog_content = "Maybe the Chaminade in the dream was merely a figment of the Ouroboros' imagination.",
  ui_story_5036_50361701_18_dialog_content = "You mean she wasn't the real Chaminade?",
  ui_story_5036_50361701_19_dialog_content = "Yeah. I remember the Chaminade in my dream said—",
  ui_story_5036_50361701_20_dialog_content = "It sensed my heart's last wish to return to my home, so it created Eraveil in its dreamscape, and me.",
  ui_story_5036_50361701_21_dialog_content = "So I guess, the Eraveil and Chaminade I saw in the dream was all created by the Ouroboros.",
  ui_story_5036_50361701_22_dialog_content = "We weren't all immersed in dreams on the Colossus simply because of the Ouroboros' psychic abilities.",
  ui_story_5036_50361701_23_dialog_content = "We were dreaming because it was dreaming.",
  ui_story_5036_50361701_24_dialog_content = "We weren't having the same dream. We were all sharing the dragon's dream.",
  ui_story_5036_50361701_25_dialog_content = "But why did it create a dream like that?",
  ui_story_5036_50361701_26_dialog_content = "Out of longing and hatred, probably...",
  ui_story_5036_50361701_27_dialog_content = "Even though it had become an egg, it could still sense that Chaminade was in danger.",
  ui_story_5036_50361701_28_dialog_content = "It couldn't help her, but it knew her wish was to return home.",
  ui_story_5036_50361701_29_dialog_content = "So, the dream was born from how it missed her. It created a dream where its friend finally returned home.",
  ui_story_5036_50361701_30_dialog_content = "The Ouroboros continued to sleep just to keep that dream alive.",
  ui_story_5036_50361701_31_dialog_content = "I see. No wonder it never hatched!",
  ui_story_5036_50361701_32_dialog_content = "Then why did it hatch suddenly? Could it have something to do with the dream as well?",
  ui_story_5036_50361701_33_dialog_content = "Because I might've slipped up...",
  ui_story_5036_50361701_34_dialog_content = "Chaminade was devastated upon learning that Eraveil was destroyed.",
  ui_story_5036_50361701_35_dialog_content = "So the dream collapsed, and it could never return to how it was.",
  ui_story_5036_50361701_36_dialog_content = "I didn't even get the chance to apologize to her.",
  ui_story_5036_50361701_37_dialog_content = "But, in the end, she wanted me to bring the song to everyone.",
  ui_story_5036_50361701_38_dialog_content = "I'll keep that promise, even if I can no longer be an idol.",
  ui_story_5036_50361701_39_dialog_content = "<color=#e8d9bb>Beep beep beep—</color>",
  ui_story_5036_50361701_40_dialog_content = "Hey! A message request from Sheol!",
  ui_story_5036_50361701_41_dialog_content = "W-What do we do? Should we answer it?",
  ui_story_5036_50361701_42_dialog_content = "Somehow, I have a bad feeling about this.",
  ui_story_5036_50361701_43_dialog_content = "Wait, let's ask my hairpin!",
  ui_story_5036_50361701_44_dialog_content = "<color=#e8d9bb>Ding—</color>",
  ui_story_5036_50361701_45_dialog_content = "It's pointed downwards. That's a good sign!",
  ui_story_5036_50361701_46_dialog_content = "Should we answer?",
  ui_story_5036_50361701_47_dialog_content = "Let's answer it, PlayerName.",
  ui_story_5036_50361701_48_dialog_content = "The only way forward is to face our problems.",
  ui_story_5036_50361701_49_dialog_content = "Alright then. Putting her through—",
  ui_story_5036_50361701_50_dialog_content = "PlayerName?",
  ui_story_5036_50361701_51_dialog_content = "Lady Sheol? I'm listening!",
  ui_story_5036_50361701_52_dialog_content = "Where are you now? What's going on?",
  ui_story_5036_50361701_53_dialog_content = "We're on Soroz. We're all here. Everyone's fine.",
  ui_story_5036_50361701_54_dialog_content = "No one's hurt? That's great... now then...",
  ui_story_5036_50361701_55_dialog_content = "GOL—DIE!",
  ui_story_5036_50361701_56_dialog_content = "*Sob*",
  ui_story_5036_50361701_57_dialog_content = "You better explain yourself. How did a concert that was supposed to go smoothly turn into this catastrophe!?",
  ui_story_5036_50361701_58_dialog_content = "I, uh...",
  ui_story_5036_50361701_59_dialog_content = "I'm sorry. I messed it up...",
  ui_story_5036_50361701_60_dialog_content = "I didn't inspect the venue carefully enough so I failed to find the Ouroboros egg on the Colossus and realize the potential threat it represented.",
  ui_story_5036_50361701_61_dialog_content = "And I didn't foresee Ouroboros would somehow react to my singing and hatch...",
  ui_story_5036_50361701_62_dialog_content = "You know, you could just blame Ouroboros for everything.",
  ui_story_5036_50361701_63_dialog_content = "No. I'll assume full responsibility for this and fully compensate for all the losses per the contract.",
  ui_story_5036_50361701_64_dialog_content = "Sigh... you really screwed me over.",
  ui_story_5036_50361701_65_dialog_content = "I invested a lot of money into promoting the concert. With the Colossus gone, all the money that was spent on maintaining its equipment and setting up the stage also went down the drain.",
  ui_story_5036_50361701_66_dialog_content = "Not to mention there were other costs, such as the costs of taking care of the audience when the incident occurred.",
  ui_story_5036_50361701_67_dialog_content = "I'm so sorry...",
  ui_story_5036_50361701_68_dialog_content = "But please rest assured, I'll pay you back in full.",
  ui_story_5036_50361701_69_dialog_content = "Even if I am no longer an idol in the future, I'll still work hard to pay⁠—",
  ui_story_5036_50361701_70_dialog_content = "Huh? When did I ask you to cover the losses?",
  ui_story_5036_50361701_71_dialog_content = "Huh...?",
  ui_story_5036_50361701_72_dialog_content = "The concert was a disaster, yes, but you performed unexpectedly well!",
  ui_story_5036_50361701_73_dialog_content = "The emotions in your song were passed not only to Ouroboros but also to the audience!",
  ui_story_5036_50361701_74_dialog_content = "Even those who were never interested in idols learned about you because of this incident!",
  ui_story_5036_50361701_75_dialog_content = "And many came asking about \"the idol\"!",
  ui_story_5036_50361701_76_dialog_content = "What?!",
  ui_story_5036_50361701_77_dialog_content = "You not only completed your contract in full but far exceeded it.",
  ui_story_5036_50361701_78_dialog_content = "A-Are you serious?",
  ui_story_5036_50361701_79_dialog_content = "Am I? Why don't you find out from your fans?",
  ui_story_5036_50361701_80_dialog_content = "Miss! Is that you?",
  ui_story_5036_50361701_81_dialog_content = "It's you! Are you and your sister safe?",
  ui_story_5036_50361701_82_dialog_content = "We're fine! You were amazing!",
  ui_story_5036_50361701_83_dialog_content = "The song was nice, and you even tamed that dragon!",
  ui_story_5036_50361701_84_dialog_content = "Everyone saw how courageous you were! So cool!",
  ui_story_5036_50361701_85_dialog_content = "Really? Heheh! I'm so happy to hear you say that!",
  ui_story_5036_50361701_86_dialog_content = "Someone else also wants to talk to you!",
  ui_story_5036_50361701_87_dialog_content = "Is that Goldie?",
  ui_story_5036_50361701_88_dialog_content = "Y-Yes, This is Goldie speaking. And you are—?",
  ui_story_5036_50361701_89_dialog_content = "Are you interested in being my personal soloist?",
  ui_story_5036_50361701_90_dialog_content = "What did you say!?",
  ui_story_5036_50361701_91_dialog_content = "Your performance has me believe you're a trusty person of honor and valor.",
  ui_story_5036_50361701_92_dialog_content = "Please be my soloist! I can help you sing on the most luxurious stages in all of Lumopolis.",
  ui_story_5036_50361701_93_dialog_content = "Thank you for your gracious offer, but...",
  ui_story_5036_50361701_94_dialog_content = "How can I convince you? Name your price!",
  ui_story_5036_50361701_95_dialog_content = "It's not a matter of money. I would much rather stay an idol than become a private performer.",
  ui_story_5036_50361701_96_dialog_content = "An idol brings hope and happiness to everyone, regardless of status.",
  ui_story_5036_50361701_97_dialog_content = "I've promised an important friend and predecessor to bring our song to everyone!",
  ui_story_5036_50361701_98_dialog_content = "Is that so...? What a pity.",
  ui_story_5036_50361701_99_dialog_content = "Well, I wish you luck with your dreams, and I'll be sure to attend your next concert.",
  ui_story_5036_50361701_100_dialog_content = "Thank you so much!",
  ui_story_5036_50361701_101_dialog_content = "So? Are you convinced now?",
  ui_story_5036_50361701_102_dialog_content = "Yes! Without a doubt!",
  ui_story_5036_50361701_103_dialog_content = "Then cheer up and get ready for the next challenge.",
  ui_story_5036_50361701_104_dialog_content = "I've already filled up your schedule. You'll have a lot to do once you get back to Umbraton.",
  ui_story_5036_50361701_105_dialog_content = "Okay! I'll be heading back right now!",
  ui_story_5036_50361701_106_dialog_content = "By the way, I heard you discovered a potential new talent called Vic. Is he here?",
  ui_story_5036_50361701_107_dialog_content = "Who, me?",
  ui_story_5036_50361701_108_dialog_content = "Are you interested in signing on as one of my idols?",
  ui_story_5036_50361701_109_dialog_content = "What? Hahaha? You've gotta be kidding me.",
  ui_story_5036_50361701_110_dialog_content = "I'm not cut out to be under the spotlight. I like spending time with animals.",
  ui_story_5036_50361701_111_dialog_content = "You won't reconsider?",
  ui_story_5036_50361701_112_dialog_content = "I can pay you handsomely and include the best champagne from Umbraton as a bonus.",
  ui_story_5036_50361701_113_dialog_content = "That sure sounds enticing. I wouldn't need to take care of Little Furball, and I could drink every day—",
  ui_story_5036_50361701_114_dialog_content = "Chirp?!",
  ui_story_5036_50361701_115_dialog_content = "CHIRP!!!",
  ui_story_5036_50361701_116_dialog_content = "Huh? Hey! Let go, you! Let go!",
  ui_story_5036_50361701_117_dialog_content = "Looks like someone strongly disagrees.",
  ui_story_5036_50361701_118_dialog_content = "All right, then. We'll talk about this some other time.",
  ui_story_5036_50361701_119_dialog_content = "Then, I'll see you all in Umbraton.",
  ui_story_5036_50361701_120_dialog_content = "Great! It really is... perfect!",
  ui_story_5036_50361701_121_dialog_content = "I can continue to be an idol!",
  ui_story_5036_50361701_122_dialog_content = "Congratulations, Goldie!",
  ui_story_5036_50361701_123_dialog_content = "Despite how this concert failed, next time I'll succeed!",
  ui_story_5036_50361701_124_dialog_content = "Please do come, PlayerName. I'll save you the best spots!",
  ui_story_5036_50361701_125_dialog_content = "Of course. It's a deal!",
  ui_story_5036_50361701_126_dialog_content = "But it'll be some time before that happens.",
  ui_story_5036_50361701_127_dialog_content = "After I get back, I'm going to write a song about this ordeal!",
  ui_story_5036_50361701_128_dialog_content = "Looks like all's well that ends well.",
  ui_story_5036_50361701_129_dialog_content = "It sure looks like it. Wow, now that I get a moment to relax, I'm suddenly so tired.",
  ui_story_5036_50361701_130_dialog_content = "I'm already getting sleepy... Yawn...",
  ui_story_5036_50361701_131_dialog_content = "Hmph! If it weren't for this drama, I'd be having a nice, hot bath right now!",
  ui_story_5036_50361701_132_dialog_content = "No bath, no problem.",
  ui_story_5036_50361701_133_dialog_content = "No difference, anyway.",
  ui_story_5036_50361701_134_dialog_content = "It was so nice to see all that rare ancient tech on Eulogoz though.",
  ui_story_5036_50361701_135_dialog_content = "The screen and stereo system were fascinating. I am inspired!",
  ui_story_5036_50361701_136_dialog_content = "I'm wondering if I should look into their working principles and make a few for the throne...",
  ui_story_5036_50361701_137_dialog_content = "Don't tell me...",
  ui_story_5036_50361701_138_dialog_content = "Then I can play games anytime, all the time!",
  ui_story_5036_50361701_139_dialog_content = "As I thought.",
  ui_story_5036_50361701_140_dialog_content = "Anyway. Let's get ourselves back down to the surface first.",
  ui_story_5036_50361701_141_dialog_content = "<color=#e8d9bb>Sometime later</color>",
  ui_story_5036_50361701_142_dialog_content = "It's already daytime. I didn't realize so much time had passed.",
  ui_story_5036_50361701_143_dialog_content = "Finally back on land! That was quite something, wasn't it, Little Furball?",
  ui_story_5036_50361701_144_dialog_content = "Chirp!",
  ui_story_5036_50361701_145_dialog_content = "We were the ones doing the fighting while you were just watching!",
  ui_story_5036_50361701_146_dialog_content = "Hey, it's not fair to say that. I did my best to protect Ouroboros as well!",
  ui_story_5036_50361701_147_dialog_content = "Never mind, I'll not argue with you since you put in some effort.",
  ui_story_5036_50361701_148_dialog_content = "I'll be taking off now. Fia and Shira are still waiting for me to get back to them and tell them about Ouroboros.",
  ui_story_5036_50361701_149_dialog_content = "Until next time.",
  ui_story_5036_50361701_150_dialog_content = "Later, Vic!",
  ui_story_5036_50361701_151_dialog_content = "Be careful out there! Don't get kidnapped again!",
  ui_story_5036_50361701_152_dialog_content = "Don't worry! I am a totally dependable adult!",
  ui_story_5036_50361701_153_dialog_content = "We shall also take an airship back to Lumopolis.",
  ui_story_5036_50361701_154_dialog_content = "(Honestly, I gotta get someone to prepare a hot bath for me in advance next time...)",
  ui_story_5036_50361701_155_dialog_content = "Hey, you Rediesel Wrench brats. Next time I see you, I'll be sending you all to prison.",
  ui_story_5036_50361701_156_dialog_content = "What? How arrogant. Who the heck do you think you are?",
  ui_story_5036_50361701_157_dialog_content = "Later, Caelestite.",
  ui_story_5036_50361701_158_dialog_content = "Goodbye!",
  ui_story_5036_50361701_159_dialog_content = "Everyone's gone? Sio, let's go back too.",
  ui_story_5036_50361701_160_dialog_content = "Alright. Vacation time is over. It's time to get back to work.",
  ui_story_5036_50361701_161_dialog_content = "Officer Gronru, are you not flying back with us on the Colossus?",
  ui_story_5036_50361701_162_dialog_content = "It's fine. Sio and I will take the car, so we don't interfere with your plans.",
  ui_story_5036_50361701_163_dialog_content = "Plus I need to discuss with Sio the possibility of adding a screen and a game console to the throne!",
  ui_story_5036_50361701_164_dialog_content = "Wh-What did you say!?",
  ui_story_5036_50361701_165_dialog_content = "Let's go, my little Sio!",
  ui_story_5036_50361701_166_dialog_content = "H-Help me...!",
  ui_story_5036_50361701_167_dialog_content = "Looks like there are still unsolvable problems for someone like Siobhan.",
  ui_story_5036_50361701_168_dialog_content = "Guess we should also get back.",
  ui_story_5036_50361701_169_dialog_content = "Yup, yup!",
  ui_story_5036_50361701_170_dialog_content = "I've decided!",
  ui_story_5036_50361701_171_dialog_content = "Hah? What crazy thing have you decided this time?",
  ui_story_5036_50361701_172_dialog_content = "Once we get back, I'm gonna convince the boss to put a stage on Lepidoz's head!",
  ui_story_5036_50361701_173_dialog_content = "That actually sounds like a good idea!",
  ui_story_5036_50361701_174_dialog_content = "Hey! It was my idea! I'm gonna ask the boss to make a an idol stage!",
  ui_story_5036_50361701_175_dialog_content = "Get back here, you! Heavy metal is real music!",
  ui_story_5036_50361701_176_dialog_content = "Oh, how lively.",
  ui_story_5036_50361701_177_dialog_content = "Let's bid farewell too, PlayerName.",
  ui_story_5036_50361701_178_dialog_content = "Thanks for everything!",
  ui_story_5036_50361701_179_dialog_content = "You too. You worked hard to make this concert happen, and we fought a long battle. It's time to take a good rest.",
  ui_story_5036_50361701_180_dialog_content = "I am a professional idol, you know. Just a little nap and I'll be ready to go!",
  ui_story_5036_50361701_181_dialog_content = "Please look forward to my next concert!",
  ui_story_5036_50361701_182_dialog_content = "I'll be sure to wait for your good news!",
  ui_story_5036_50361701_183_dialog_content = "Bye, then!",
  ui_story_5036_50361701_184_dialog_content = "So Goldie's violent tendencies were just pure hearsay. I have to clear that up in my article.",
  ui_story_5036_50361701_185_dialog_content = "Hey, chief editor?",
  ui_story_5036_50361701_186_dialog_content = "<size=45>Brandy! What took you so long to contact me?</size>",
  ui_story_5036_50361701_187_dialog_content = "You'll be fired if you don't have something big for me!",
  ui_story_5036_50361701_188_dialog_content = "I-I've looked into the rumors claiming that Goldie is a violent person. It's all fake!",
  ui_story_5036_50361701_189_dialog_content = "...",
  ui_story_5036_50361701_190_dialog_content = "Is that all you found out the entire time the Wandering Colossus was flying over Umbraton!?",
  ui_story_5036_50361701_191_dialog_content = "Even if it's fake news, it'll still attract readers, won't it? Without this type of gossip, we'd have to shut down.",
  ui_story_5036_50361701_192_dialog_content = "I'm very disappointed in you, Brandy. You are getting demoted⁠—",
  ui_story_5036_50361701_193_dialog_content = "Wait! That's not the only thing! I have exclusive details on the Wandering Colossus concert!",
  ui_story_5036_50361701_194_dialog_content = "What!? You're serious! Well, get it over here, then!",
  ui_story_5036_50361701_195_dialog_content = "On one condition.",
  ui_story_5036_50361701_196_dialog_content = "What is it?",
  ui_story_5036_50361701_197_dialog_content = "The exclusive and the article dispelling the rumors about Goldie have to be on the same page.",
  ui_story_5036_50361701_198_dialog_content = "I want everyone to know that they've got the wrong idea about Goldie!",
  ui_story_5036_50361701_199_dialog_content = "T-That's prepost...",
  ui_story_5036_50361701_200_dialog_content = "<size=45>Ugh, alright, fine!</size>",
  ui_story_5036_50361701_201_dialog_content = "I'll do that. Now get your reports over here.",
  ui_story_5036_50361701_202_dialog_content = "Right away!",
  ui_story_5036_50361701_203_dialog_content = "So you kidnapped the Drakolion with animal cookies and sneaked onto the Wandering Colossus to investigate it... for nothing!?",
  ui_story_5036_50361701_204_dialog_content = "I almost got ambushed by Eclipsites while trying to find the Drakolion!",
  ui_story_5036_50361701_205_dialog_content = "How are you gonna compensate me for this, huh!? Master?",
  ui_story_5036_50361701_206_dialog_content = "Well! Despite failing to find out more about Ouroboros, we did wake it up and got lots of intel!",
  ui_story_5036_50361701_207_dialog_content = "The return of the Ouroboros will definitely shake things up in Astra!",
  ui_story_5036_50361701_208_dialog_content = "Trust me, with the intel I have now. It'll be easy to track down Ouroboros in the future!",
  ui_story_5036_50361701_209_dialog_content = "Why does that sound so familiar?",
  ui_story_5036_50361701_210_dialog_content = "That's what he said the last time.",
  ui_story_5036_50361701_211_dialog_content = "\"Trust me, I'll definitely make a lot of cash next time!\"",
  ui_story_5036_50361701_212_dialog_content = "How is it that you remember it so well?",
  ui_story_5036_50361701_213_dialog_content = "Because that's what he said the time before that as well.",
  ui_story_5036_50361701_214_dialog_content = "But, until now, there has been no positive change in his financial status. He just keeps on getting poorer.",
  ui_story_5036_50361701_215_dialog_content = "True. He still hasn't paid for last month's wondrous beast feed!",
  ui_story_5036_50361701_216_dialog_content = "*Sob* Am I really such a loser in your eyes?",
  ui_story_5036_50361701_217_dialog_content = "What did you expect?",
  ui_story_5036_50361701_218_dialog_content = "I'm so sad!",
  ui_story_5036_50361701_219_dialog_content = "So does everyone think I'd be better off being an idol?",
  ui_story_5036_50361701_220_dialog_content = "They gave you applause because they took pity on you. You shouldn't take it seriously.",
  ui_story_5036_50361701_221_dialog_content = "*Sob*",
  ui_story_5036_50361701_222_dialog_content = "But, you were right for once. Ouroboros really was on the Wandering Colossus.",
  ui_story_5036_50361701_223_dialog_content = "How did you find out?",
  ui_story_5036_50361701_224_dialog_content = "Maybe to the Ouroboros, heading to the Colossus was a manner of return.",
  ui_story_5036_50361701_225_dialog_content = "What do you mean by that?",
  ui_story_5036_50361701_226_dialog_content = "It doesn't matter how long an Ouroboros can live or how many times it has hatched...",
  ui_story_5036_50361701_227_dialog_content = "It began as an egg from another Ouroboros.",
  ui_story_5036_50361701_228_dialog_content = "A youngling relies on its parents for protection by instinct.",
  ui_story_5036_50361701_229_dialog_content = "The same holds true even for an Ouroboros that returns to its infancy stage in every life cycle.",
  ui_story_5036_50361701_230_dialog_content = "However, Ouroboroses are too few in number. Many never find their parents.",
  ui_story_5036_50361701_231_dialog_content = "Because of it, they can only search out the Colossi, whom they share strong bonds with.",
  ui_story_5036_50361701_232_dialog_content = "Treating the Colossi as their parents... how sad.",
  ui_story_5036_50361701_233_dialog_content = "Well then, since you share blood with an Ouroboros, does that mean one day you'll be seeking out a Colosuss or something?",
  ui_story_5036_50361701_234_dialog_content = "My past is a mystery! Don't make wild conjectures!",
  ui_story_5036_50361701_235_dialog_content = "That's true. For someone as useless as you who can't even use psychic abilities, you were probably bluffing when you said you share bloodlines with an Ouroboros.",
  ui_story_5036_50361701_236_dialog_content = "It's true!",
  ui_story_5036_50361701_237_dialog_content = "If that's true, why didn't the Ouroboros come to find you?",
  ui_story_5036_50361701_238_dialog_content = "Isn't that what we should be looking into? Let's—",
  ui_story_5036_50361701_239_dialog_content = "Kree—!",
  ui_story_5036_50361701_240_dialog_content = "?!"
}
return config
